INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('3acf6339-9f5c-592a-a281-ffb328ea4915', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 6, 6, 'For this is what Yahweh of Armies says: ''Yet once, it is a little while, and I will shake the heavens, the earth, the sea, and the dry land;'),
  ('24c3fc1f-9296-528e-ad5d-34540d5f481e', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 7, 7, 'and I will shake all nations. The precious things of all nations will come, and I will fill this house with glory, says Yahweh of Armies.'),
  ('76e461e6-ab18-5758-ae62-52608b54d7dc', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 8, 8, 'The silver is mine, and the gold is mine,'' says Yahweh of Armies.'),
  ('a5a3ae49-77df-5139-a12e-150f0d4f7c2c', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 9, 9, '''The latter glory of this house will be greater than the former,'' says Yahweh of Armies; ''and in this place will I give peace,'' says Yahweh of Armies."'),
  ('44a3c7f1-a353-5755-a769-75b23690ffe7', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 10, 10, 'In the twenty-fourth day of the ninth month, in the second year of Darius, the Word of Yahweh came by Haggai the prophet, saying,'),
  ('f25413c8-f788-5aa0-a369-57eb29f7c04d', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 11, 11, '"Thus says Yahweh of Armies: Ask now the priests concerning the law, saying,'),
  ('504af44f-0176-5e5e-a1b7-1f8dac63cb00', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 12, 12, '''If someone carries holy meat in the fold of his garment, and with his fold touches bread, stew, wine, oil, or any food, will it become holy?''" The priests answered, "No."'),
  ('2eb041b6-e7ab-58eb-a26e-058cc294a857', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 13, 13, 'Then Haggai said, "If one who is unclean by reason of a dead body touch any of these, will it be unclean?" The priests answered, "It will be unclean."'),
  ('b9988322-7843-5719-aea3-b28c259c13b7', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 14, 14, 'Then Haggai answered, "''So is this people, and so is this nation before me,'' says Yahweh; ''and so is every work of their hands. That which they offer there is unclean.'),
  ('ae9d4554-1cf4-5ac2-a9bb-61c4eeee6c8d', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 15, 15, 'Now, please consider from this day and backward, before a stone was laid on a stone in the temple of Yahweh.'),
  ('e35054d1-f2a2-5bc1-a828-f4ae60300ea5', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 16, 16, 'Through all that time, when one came to a heap of twenty measures, there were only ten. When one came to the wine vat to draw out fifty, there were only twenty.'),
  ('f98b0ace-63db-5260-a915-1706fc3edeb6', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 17, 17, 'I struck you with blight, mildew, and hail in all the work of your hands; yet you didn''t turn to me,'' says Yahweh.'),
  ('e5c3ec35-b0aa-52a3-a117-90eea79a599e', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 18, 18, '''Consider, please, from this day and backward, from the twenty-fourth day of the ninth month, since the day that the foundation of Yahweh''s temple was laid, consider it.'),
  ('87eeb83d-fb10-5537-a16e-b52c419ec2b2', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 19, 19, 'Is the seed yet in the barn? Yes, the vine, the fig tree, the pomegranate, and the olive tree haven''t brought forth. From this day will I bless you.''"'),
  ('2ce84ed7-144f-5ec0-ac86-272c05a1f513', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 20, 20, 'The Word of Yahweh came the second time to Haggai in the twenty-fourth day of the month, saying,'),
  ('eb011e9b-7468-5754-abf7-d38416af267b', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 21, 21, '"Speak to Zerubbabel, governor of Judah, saying, ''I will shake the heavens and the earth.'),
  ('d294790d-0243-5fdf-a16e-a6876b836f17', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 22, 22, 'I will overthrow the throne of kingdoms. I will destroy the strength of the kingdoms of the nations. I will overthrow the chariots, and those who ride in them. The horses and their riders will come down, everyone by the sword of his brother.'),
  ('84385821-b3d6-571d-a5de-bcd1cabda73c', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 23, 23, 'In that day, says Yahweh of Armies, will I take you, Zerubbabel, my servant, the son of Shealtiel,'' says Yahweh, ''and will make you as a signet, for I have chosen you,'' says Yahweh of Armies."'),
  ('62f8bd19-537e-56dc-ac54-08667fd8797b', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 1, 1, 'In the eighth month, in the second year of Darius, the word of Yahweh came to Zechariah the son of Berechiah, the son of Iddo, the prophet, saying,'),
  ('e7a3ec2f-681e-579a-a94d-00819babc3a7', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 2, 2, '"Yahweh was very displeased with your fathers.'),
  ('de75abfb-727a-5518-a8e4-d1ebd9c9dba4', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 3, 3, 'Therefore tell them: Thus says Yahweh of Armies: ''Return to me,'' says Yahweh of Armies, ''and I will return to you,'' says Yahweh of Armies.'),
  ('7ab3709d-f477-5c22-aa4f-d281c88bce7d', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 4, 4, 'Don''t you be like your fathers, to whom the former prophets proclaimed, saying: Thus says Yahweh of Armies, ''Return now from your evil ways, and from your evil doings;'' but they did not hear, nor listen to me, says Yahweh.'),
  ('c62d3339-fcdb-53bb-ad56-c3e0c9b38808', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 5, 5, 'Your fathers, where are they? And the prophets, do they live forever?'),
  ('22aaffc5-06d8-5b25-acf8-cf1ede9d1496', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 6, 6, 'But my words and my decrees, which I commanded my servants the prophets, didn''t they overtake your fathers? "Then they repented and said, ''Just as Yahweh of Armies determined to do to us, according to our ways, and according to our practices, so he has dealt with us.''"'),
  ('d1ff126e-7175-5d98-a475-4e0c31e159ff', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 7, 7, 'On the twenty-fourth day of the eleventh month, which is the month Shebat, in the second year of Darius, the word of Yahweh came to Zechariah the son of Berechiah, the son of Iddo, the prophet, saying,'),
  ('87e6d69a-ae35-5f11-afbc-66c665a68ac7', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 8, 8, '"I had a vision in the night, and behold, a man riding on a red horse, and he stood among the myrtle trees that were in a ravine; and behind him there were red, brown, and white horses.'),
  ('3f17412c-258a-5e35-a467-7bc94ed9345d', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 9, 9, 'Then I asked, ''My lord, what are these?''" The angel who talked with me said to me, "I will show you what these are."'),
  ('88aa46ed-c80f-544e-a9aa-6a2e59c1aba2', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 10, 10, 'The man who stood among the myrtle trees answered, "They are the ones Yahweh has sent to go back and forth through the earth."'),
  ('44a37321-d278-5f00-ab7f-533cbf667e24', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 11, 11, 'They reported to the angel of Yahweh who stood among the myrtle trees, and said, "We have walked back and forth through the earth, and behold, all the earth is at rest and in peace."'),
  ('bd5ab22b-6b59-50c7-accc-638e7049a140', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 12, 12, 'Then the angel of Yahweh replied, "O Yahweh of Armies, how long will you not have mercy on Jerusalem and on the cities of Judah, against which you have had indignation these seventy years?"'),
  ('c67ca0b2-84f0-58af-aba5-5d64725b5313', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 13, 13, 'Yahweh answered the angel who talked with me with kind and comforting words.'),
  ('fe81faa7-f64d-5f79-a57d-487aa7787506', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 14, 14, 'So the angel who talked with me said to me, "Proclaim, saying, ''Thus says Yahweh of Armies: "I am jealous for Jerusalem and for Zion with a great jealousy.'),
  ('7ef5cc31-ce30-59cf-ad55-e45c17eb9658', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 15, 15, 'I am very angry with the nations that are at ease; for I was but a little displeased, but they added to the calamity."'),
  ('1f6372f4-37e4-50b6-a45b-61f1f3f1ab73', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 16, 16, 'Therefore thus says Yahweh: "I have returned to Jerusalem with mercy. My house shall be built in it," says Yahweh of Armies, "and a line shall be stretched forth over Jerusalem."'''),
  ('b5f6f259-53b3-59c3-a32d-a720b1134cba', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 17, 17, '"Proclaim further, saying, ''Thus says Yahweh of Armies: "My cities will again overflow with prosperity, and Yahweh will again comfort Zion, and will again choose Jerusalem."''"'),
  ('e96b5e59-667b-5799-a567-327cbe3c976b', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 18, 18, 'I lifted up my eyes, and saw, and behold, four horns.'),
  ('f0b32231-f32a-5182-ae1c-93c9472b3df6', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 19, 19, 'I asked the angel who talked with me, "What are these?" He answered me, "These are the horns which have scattered Judah, Israel, and Jerusalem."'),
  ('a74d2c26-a10e-5e64-ac6e-1ff47b4985a7', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 20, 20, 'Yahweh showed me four craftsmen.'),
  ('f37e36df-ddc9-5092-a330-1a146ed58c8a', '44ca78b5-6104-566d-ae63-c0aadf52a6ed', NULL, 21, 21, 'Then I asked, "What are these coming to do?" He said, "These are the horns which scattered Judah, so that no man lifted up his head; but these have come to terrify them, to cast down the horns of the nations, which lifted up their horn against the land of Judah to scatter it."'),
  ('f41ff651-c37b-5699-a135-779011c92f49', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 1, 1, 'I lifted up my eyes, and saw, and behold, a man with a measuring line in his hand.'),
  ('21a2ff97-99eb-55ba-a77c-e3268007954c', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 2, 2, 'Then I asked, "Where are you going?" He said to me, "To measure Jerusalem, to see what is its breadth and what is its length."'),
  ('d3e8e483-d424-57a6-a19d-e6d03f4e33eb', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 3, 3, 'Behold, the angel who talked with me went forth, and another angel went out to meet him,'),
  ('4e0fd7e1-5e50-5aa5-aa94-cd36dec47044', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 4, 4, 'and said to him, "Run, speak to this young man, saying, ''Jerusalem will be inhabited as villages without walls, because of the multitude of men and livestock in it.'),
  ('a2ee5461-ccdc-5d21-afa7-e6fb6730e0d0', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 5, 5, 'For I,'' says Yahweh, ''will be to her a wall of fire around it, and I will be the glory in the midst of her.'),
  ('4b1d4032-3e4e-5a3c-a1ac-5d7fba3fd898', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 6, 6, 'Come! Come! Flee from the land of the north,'' says Yahweh; ''for I have spread you abroad as the four winds of the sky,'' says Yahweh.'),
  ('4f8d669e-a83b-5e2c-acf6-3a274d6c64ff', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 7, 7, '''Come, Zion! Escape, you who dwell with the daughter of Babylon.'''),
  ('498a691f-8de1-550d-a7c5-f3998bfc986e', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 8, 8, 'For thus says Yahweh of Armies: ''For honor he has sent me to the nations which plundered you; for he who touches you touches the apple of his eye.'),
  ('43e2bc37-388b-54e0-aa1e-2b8e96257af2', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 9, 9, 'For, behold, I will shake my hand over them, and they will be a spoil to those who served them; and you will know that Yahweh of Armies has sent me.'),
  ('bef2ed5b-b5ab-513a-a705-70e5740c6ae4', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 10, 10, 'Sing and rejoice, daughter of Zion; for, behold, I come, and I will dwell in the midst of you,'' says Yahweh.'),
  ('db5bf36f-c539-540c-a617-8822ea9b7b1a', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 11, 11, 'Many nations shall join themselves to Yahweh in that day, and shall be my people; and I will dwell in the midst of you, and you shall know that Yahweh of Armies has sent me to you.'),
  ('f7a39dda-f300-5b1c-a73b-7072dc3d8dab', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 12, 12, 'Yahweh will inherit Judah as his portion in the holy land, and will again choose Jerusalem.'),
  ('c050ac6f-3cb5-5665-a4f6-d3696f691567', 'fbcb7ac0-6971-5035-a1d8-e7b7f49bc103', NULL, 13, 13, 'Be silent, all flesh, before Yahweh; for he has roused himself from his holy habitation!"'),
  ('dd4a1f07-9225-521c-a792-719cf881c873', 'af2d2acb-960e-5cdd-a889-56bc41a006e1', NULL, 1, 1, 'He showed me Joshua the high priest standing before the angel of Yahweh, and Satan standing at his right hand to be his adversary.'),
  ('3fb6eb1c-0b92-5486-a7c2-df118e848160', 'af2d2acb-960e-5cdd-a889-56bc41a006e1', NULL, 2, 2, 'Yahweh said to Satan, "Yahweh rebuke you, Satan! Yes, Yahweh who has chosen Jerusalem rebuke you! Isn''t this a burning stick plucked out of the fire?"'),
  ('390b5aaa-6559-562e-aa44-1eedbf38831b', 'af2d2acb-960e-5cdd-a889-56bc41a006e1', NULL, 3, 3, 'Now Joshua was clothed with filthy garments, and was standing before the angel.'),
  ('b0d679da-de06-57da-a273-0f8993d63a4e', 'af2d2acb-960e-5cdd-a889-56bc41a006e1', NULL, 4, 4, 'He answered and spoke to those who stood before him, saying, "Take the filthy garments off of him." To him he said, "Behold, I have caused your iniquity to pass from you, and I will clothe you with rich clothing."'),
  ('0dab77c7-7336-5270-a0ae-11d8ea535321', 'af2d2acb-960e-5cdd-a889-56bc41a006e1', NULL, 5, 5, 'I said, "Let them set a clean turban on his head." So they set a clean turban on his head, and clothed him; and the angel of Yahweh was standing by.'),
  ('96e45527-f973-5978-a937-32d0cd6654b4', 'af2d2acb-960e-5cdd-a889-56bc41a006e1', NULL, 6, 6, 'The angel of Yahweh protested to Joshua, saying,'),
  ('3244a042-82bb-5e69-acf8-b4dd336de6cf', 'af2d2acb-960e-5cdd-a889-56bc41a006e1', NULL, 7, 7, '"Thus says Yahweh of Armies: ''If you will walk in my ways, and if you will follow my instructions, then you also shall judge my house, and shall also keep my courts, and I will give you a place of access among these who stand by.'),
  ('175b0a11-8f5b-5b64-a389-731095f2b998', 'af2d2acb-960e-5cdd-a889-56bc41a006e1', NULL, 8, 8, 'Hear now, Joshua the high priest, you and your fellows who sit before you; for they are men who are a sign: for, behold, I will bring forth my servant, the Branch.'),
  ('83d243e0-084e-5da2-ad4d-a111cc040062', 'af2d2acb-960e-5cdd-a889-56bc41a006e1', NULL, 9, 9, 'For, behold, the stone that I have set before Joshua; on one stone are seven eyes: behold, I will engrave its engraving,'' says Yahweh of Armies, ''and I will remove the iniquity of that land in one day.'),
  ('4e1c417e-ed4d-5fe6-a2c9-c81667eb6211', 'af2d2acb-960e-5cdd-a889-56bc41a006e1', NULL, 10, 10, 'In that day,'' says Yahweh of Armies, ''you will invite every man his neighbor under the vine and under the fig tree.''"'),
  ('62173acf-f706-5d32-afab-ec4e5137da73', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 1, 1, 'The angel who talked with me came again, and wakened me, as a man who is wakened out of his sleep.'),
  ('79e743d8-93b5-55aa-a322-0e07e0dd626d', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 2, 2, 'He said to me, "What do you see?" I said, "I have seen, and behold, a lampstand all of gold, with its bowl on the top of it, and its seven lamps thereon; there are seven pipes to each of the lamps, which are on the top of it;'),
  ('d50a2a4b-c49b-5380-a931-1c0f34d94811', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 3, 3, 'and two olive trees by it, one on the right side of the bowl, and the other on the left side of it."'),
  ('939f31fa-56a4-5c84-ada2-21674c7851ed', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 4, 4, 'I answered and spoke to the angel who talked with me, saying, "What are these, my lord?"'),
  ('2b27663d-3ded-580d-a4b6-16fe705afc0e', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 5, 5, 'Then the angel who talked with me answered me, "Don''t you know what these are?" I said, "No, my lord."'),
  ('cffdb1cc-c039-51d8-a0bf-62326fa9ec82', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 6, 6, 'Then he answered and spoke to me, saying, "This is the word of Yahweh to Zerubbabel, saying, ''Not by might, nor by power, but by my Spirit,'' says Yahweh of Armies.'),
  ('7cb2b6b1-97bb-518f-a6c5-8aff7adca777', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 7, 7, 'Who are you, great mountain? Before Zerubbabel you are a plain; and he will bring out the capstone with shouts of ''Grace, grace, to it!''"'),
  ('4bad7231-a098-5093-a458-23fd25cbcc6a', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 8, 8, 'Moreover the word of Yahweh came to me, saying,'),
  ('db64f5fe-40c3-5f61-a50c-0ff78bd856a6', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 9, 9, '"The hands of Zerubbabel have laid the foundation of this house. His hands shall also finish it; and you will know that Yahweh of Armies has sent me to you.'),
  ('af1890df-c553-513f-a0f4-a8146316428c', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 10, 10, 'Indeed, who despises the day of small things? For these seven shall rejoice, and shall see the plumb line in the hand of Zerubbabel. These are the eyes of Yahweh, which run back and forth through the whole earth."'),
  ('2cbb45bd-46c1-5e5c-a289-bc08a01aacaa', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 11, 11, 'Then I asked him, "What are these two olive trees on the right side of the lampstand and on the left side of it?"'),
  ('8c9d0a9b-0b70-5211-a1ed-a6720c47340d', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 12, 12, 'I asked him the second time, "What are these two olive branches, which are beside the two golden spouts, that pour the golden oil out of themselves?"'),
  ('de2a42c4-0373-5b8a-aa3c-1480051f2f2c', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 13, 13, 'He answered me, "Don''t you know what these are?" I said, "No, my lord."'),
  ('2508fc0e-f745-591f-a888-adace68edcf2', 'fee83f36-7f0a-5076-a006-a5760d3961d4', NULL, 14, 14, 'Then he said, "These are the two anointed ones who stand by the Lord of the whole earth."'),
  ('8a3ea221-c6f9-5ed4-a8b0-78638383b9df', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 1, 1, 'Then again I lifted up my eyes, and saw, and behold, a flying scroll.'),
  ('76fcdf99-22b2-5824-a504-cb67e504486e', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 2, 2, 'He said to me, "What do you see?" I answered, "I see a flying scroll; its length is twenty cubits, and its breadth ten cubits."'),
  ('4a2959b5-5c30-5ff8-a7af-20c7c54f1ece', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 3, 3, 'Then he said to me, "This is the curse that goes out over the surface of the whole land; for everyone who steals shall be cut off according to it on the one side; and everyone who swears falsely shall be cut off according to it on the other side.'),
  ('09b4196a-4152-53be-ad0c-11d9f21d61fe', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 4, 4, 'I will cause it to go out," says Yahweh of Armies, "and it will enter into the house of the thief, and into the house of him who swears falsely by my name; and it will remain in the midst of his house, and will destroy it with its timber and its stones."'),
  ('fde713e1-b6f3-5fcb-ad54-6d89abd774b7', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 5, 5, 'Then the angel who talked with me came forward, and said to me, "Lift up now your eyes, and see what is this that is appearing."'),
  ('7eb2f6bc-5124-5b01-aa39-be402b37cc53', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 6, 6, 'I said, "What is it?" He said, "This is the ephah basket that is appearing." He said moreover, "This is their appearance in all the land'),
  ('e0ff1801-7609-5be6-aff6-72068d1d2bf6', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 7, 7, '(and behold, a talent of lead was lifted up); and this is a woman sitting in the midst of the ephah basket."'),
  ('d689ee0f-b0f8-5713-a72b-2017d1554094', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 8, 8, 'He said, "This is Wickedness;" and he threw her down into the midst of the ephah basket; and he threw the weight of lead on its mouth.'),
  ('0c8e1438-39e5-581f-a1f1-2d6e3d64f9af', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 9, 9, 'Then lifted I up my eyes, and saw, and behold, there were two women, and the wind was in their wings. Now they had wings like the wings of a stork, and they lifted up the ephah basket between earth and the sky.'),
  ('e5d72f89-c4d0-5afd-ad33-f0ad2a54345d', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 10, 10, 'Then I said to the angel who talked with me, "Where are these carrying the ephah basket?"'),
  ('a3166a20-7c84-5179-aadf-826b071b2609', '9f89b2f1-3278-5f01-a8db-b029d5b1680e', NULL, 11, 11, 'He said to me, "To build her a house in the land of Shinar. When it is prepared, she will be set there in her own place."'),
  ('99a53f4c-338b-53d8-ac82-165232ce145a', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 1, 1, 'Again I lifted up my eyes, and saw, and behold, four chariots came out from between two mountains; and the mountains were mountains of brass.'),
  ('0f42eab8-88a8-5b1f-a99c-ad1334a117c1', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 2, 2, 'In the first chariot were red horses; in the second chariot black horses;'),
  ('3cd50892-6433-590a-a836-5e73c518c42b', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 3, 3, 'in the third chariot white horses; and in the fourth chariot dappled horses, all of them powerful.'),
  ('06c9efc8-1505-5a17-ab72-7e9f9bc66eff', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 4, 4, 'Then I asked the angel who talked with me, "What are these, my lord?"'),
  ('b2f00541-fb65-5d72-a1c3-839b738bcb68', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 5, 5, 'The angel answered me, "These are the four winds of the sky, which go forth from standing before the Lord of all the earth.'),
  ('2fcab71f-185e-5e6f-af40-9528e76bc216', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 6, 6, 'The one with the black horses goes out toward the north country; and the white went out after them; and the dappled went forth toward the south country."'),
  ('b4122cdc-23ee-5510-ae5c-4a231fbadf63', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 7, 7, 'The strong went out, and sought to go that they might walk back and forth through the earth: and he said, "Go around and through the earth!" So they walked back and forth through the earth.'),
  ('94cda456-0693-5139-ab87-08330fe40250', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 8, 8, 'Then he called to me, and spoke to me, saying, "Behold, those who go toward the north country have quieted my spirit in the north country."'),
  ('96981ac9-7921-5a9d-a716-2e2dd8357b9a', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 9, 9, 'The word of Yahweh came to me, saying,'),
  ('7fae2e2b-c2dd-5b8f-ae80-cace09eb141d', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 10, 10, '"Take of them of the captivity, even of Heldai, of Tobijah, and of Jedaiah; and come the same day, and go into the house of Josiah the son of Zephaniah, where they have come from Babylon.'),
  ('7764ea67-13d2-5ada-a08d-de8cc1eb5703', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 11, 11, 'Yes, take silver and gold, and make crowns, and set them on the head of Joshua the son of Jehozadak, the high priest;'),
  ('95486be5-564a-534e-ae06-12988b27df2d', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 12, 12, 'and speak to him, saying, ''Thus says Yahweh of Armies, "Behold, the man whose name is the Branch: and he shall grow up out of his place; and he shall build the temple of Yahweh;'),
  ('717cd16a-6f84-55f0-a5f4-58d98c05706f', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 13, 13, 'even he shall build the temple of Yahweh; and he shall bear the glory, and shall sit and rule on his throne; and he shall be a priest on his throne; and the counsel of peace shall be between them both.'),
  ('e19459af-81c5-57f8-a224-1323b3928536', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 14, 14, 'The crowns shall be to Helem, and to Tobijah, and to Jedaiah, and to Hen the son of Zephaniah, for a memorial in the temple of Yahweh.'),
  ('84cd1806-c992-56da-aa23-d720770a658e', '67b41d7f-96ff-5190-a993-58fea7fdb062', NULL, 15, 15, 'Those who are far off shall come and build in the temple of Yahweh; and you shall know that Yahweh of Armies has sent me to you. This will happen, if you will diligently obey the voice of Yahweh your God."''"'),
  ('549f4ee9-d289-5c60-ac6e-2fd64ae5f153', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 1, 1, 'It happened in the fourth year of king Darius that the word of Yahweh came to Zechariah in the fourth day of the ninth month, the month of Chislev.'),
  ('1c50e2da-2dde-5305-a7de-94e70fbd560a', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 2, 2, 'The people of Bethel sent Sharezer and Regem Melech, and their men, to entreat Yahweh''s favor,'),
  ('cb39d25a-7850-5ea3-a4fc-8c64b2a1b7e2', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 3, 3, 'and to speak to the priests of the house of Yahweh of Armies, and to the prophets, saying, "Should I weep in the fifth month, separating myself, as I have done these so many years?"'),
  ('20082c63-490d-542e-a0fa-76fe3775ef0a', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 4, 4, 'Then the word of Yahweh of Armies came to me, saying,'),
  ('f922c8fd-8d66-57f1-ac2d-edef112d01a4', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 5, 5, '"Speak to all the people of the land, and to the priests, saying, ''When you fasted and mourned in the fifth and in the seventh month for these seventy years, did you at all fast to me, really to me?'),
  ('789b96d4-c0b8-56c3-a2ce-970c480b50bc', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 6, 6, 'When you eat, and when you drink, don''t you eat for yourselves, and drink for yourselves?'),
  ('74625d27-d1e1-57c9-a922-231b692dd5d2', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 7, 7, 'Aren''t these the words which Yahweh proclaimed by the former prophets, when Jerusalem was inhabited and in prosperity, and its cities around her, and the South and the lowland were inhabited?''"'),
  ('2379572f-9c05-5cc8-a7e7-d9be576c3de6', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 8, 8, 'The word of Yahweh came to Zechariah, saying,'),
  ('6cfbd6a5-8885-5752-a382-cc87dd597d2e', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 9, 9, '"Thus has Yahweh of Armies spoken, saying, ''Execute true judgment, and show kindness and compassion every man to his brother.'),
  ('ecc54fc4-2437-5a31-a2b1-a561ac21a5a8', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 10, 10, 'Don''t oppress the widow, nor the fatherless, the foreigner, nor the poor; and let none of you devise evil against his brother in your heart.'''),
  ('1962099f-13fb-55a4-a5ba-1871d4579f7a', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 11, 11, 'But they refused to listen, and turned their backs, and stopped their ears, that they might not hear.'),
  ('655a597c-ac78-5756-a663-89f709902d82', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 12, 12, 'Yes, they made their hearts as hard as flint, lest they might hear the law, and the words which Yahweh of Armies had sent by his Spirit by the former prophets. Therefore great wrath came from Yahweh of Armies.'),
  ('b7209935-4f7a-58bf-ad33-a8165abd9715', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 13, 13, 'It has come to pass that, as he called, and they refused to listen, so they will call, and I will not listen," said Yahweh of Armies;'),
  ('309c85ff-4984-5c55-a2e3-4ca7bb53730e', '37ecc945-d291-5eb0-a882-ea9fb7e1ddc6', NULL, 14, 14, '"but I will scatter them with a whirlwind among all the nations which they have not known. Thus the land was desolate after them, so that no man passed through nor returned: for they made the pleasant land desolate."'),
  ('b289428e-b9d1-5f89-a5d3-04cd84965509', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 1, 1, 'The word of Yahweh of Armies came to me.'),
  ('7761646f-70a6-503f-a4a7-136c80f0cf3d', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 2, 2, 'Thus says Yahweh of Armies: "I am jealous for Zion with great jealousy, and I am jealous for her with great wrath."'),
  ('f2706fbf-34c0-5685-a6e4-0b3f1c87e66b', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 3, 3, 'Thus says Yahweh: "I have returned to Zion, and will dwell in the midst of Jerusalem. Jerusalem shall be called ''The City of Truth;'' and the mountain of Yahweh of Armies, ''The Holy Mountain.''"'),
  ('251b3a75-3ee0-5aeb-aaf0-14aa07f177af', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 4, 4, 'Thus says Yahweh of Armies: "Old men and old women will again dwell in the streets of Jerusalem, every man with his staff in his hand for very age.'),
  ('c2f7f215-4ccf-54eb-a594-ed38c211cc1f', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 5, 5, 'The streets of the city will be full of boys and girls playing in its streets."'),
  ('02ef4a08-beb1-5686-aabd-074ea49e0561', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 6, 6, 'Thus says Yahweh of Armies: "If it is marvelous in the eyes of the remnant of this people in those days, should it also be marvelous in my eyes?" says Yahweh of Armies.'),
  ('bce8438d-ce8b-5e7e-a438-406ac0e95498', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 7, 7, 'Thus says Yahweh of Armies: "Behold, I will save my people from the east country, and from the west country;'),
  ('17807df7-4ad5-51b6-a105-ffc7727cd635', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 8, 8, 'and I will bring them, and they will dwell in the midst of Jerusalem; and they will be my people, and I will be their God, in truth and in righteousness."'),
  ('f65170e8-2a49-5555-a90e-d765d5dfda90', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 9, 9, 'Thus says Yahweh of Armies: "Let your hands be strong, you who hear in these days these words from the mouth of the prophets who were in the day that the foundation of the house of Yahweh of Armies was laid, even the temple, that it might be built.'),
  ('14ccc162-53c3-59dc-a527-af488968be79', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 10, 10, 'For before those days there was no wages for man, nor any wages for an animal; neither was there any peace to him who went out or came in, because of the adversary. For I set all men everyone against his neighbor.'),
  ('a2951cb5-9a7d-5f3e-ab84-d96c6e089844', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 11, 11, 'But now I will not be to the remnant of this people as in the former days," says Yahweh of Armies.'),
  ('d43fdc66-4499-5d47-a5ae-155353d5342d', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 12, 12, '"For the seed of peace and the vine will yield its fruit, and the ground will give its increase, and the heavens will give their dew; and I will cause the remnant of this people to inherit all these things.'),
  ('31ca9d0a-92df-57d4-a977-ee0843984fa0', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 13, 13, 'It shall come to pass that, as you were a curse among the nations, house of Judah and house of Israel, so will I save you, and you shall be a blessing. Don''t be afraid. Let your hands be strong."'),
  ('0f4dd09d-7cd6-5f9d-a4fd-4c53990537df', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 14, 14, 'For thus says Yahweh of Armies: "As I thought to do evil to you, when your fathers provoked me to wrath," says Yahweh of Armies, "and I didn''t repent;'),
  ('5f59c7fc-6183-5dbe-a32c-03c72d875c8e', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 15, 15, 'so again have I thought in these days to do good to Jerusalem and to the house of Judah. Don''t be afraid.'),
  ('29a0017b-da75-586f-ac6a-08279110fb8c', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 16, 16, 'These are the things that you shall do: speak every man the truth with his neighbor. Execute the judgment of truth and peace in your gates,'),
  ('fcd6d45d-f023-52d5-a3f7-76054f87d2ee', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 17, 17, 'and let none of you devise evil in your hearts against his neighbor, and love no false oath: for all these are things that I hate," says Yahweh.'),
  ('f9952b94-9e3c-5b6a-a2a4-bb780f596aa7', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 18, 18, 'The word of Yahweh of Armies came to me.'),
  ('82f8683c-a4c2-59d8-af60-53aae8640c02', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 19, 19, 'Thus says Yahweh of Armies: "The fasts of the fourth fifth, seventh, and tenth months shall be for the house of Judah joy and gladness, and cheerful feasts. Therefore love truth and peace."'),
  ('7e4b4737-4ca4-5f9e-af57-0d63a748b907', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 20, 20, 'Thus says Yahweh of Armies: "Many peoples, and the inhabitants of many cities will yet come;'),
  ('16c5915a-5453-57f6-a14d-2207d84f9656', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 21, 21, 'and the inhabitants of one shall go to another, saying, ''Let us go speedily to entreat the favor of Yahweh, and to seek Yahweh of Armies. I will go also.'''),
  ('688ecc93-55b4-530c-ac09-a7e0b366f0aa', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 22, 22, 'Yes, many peoples and strong nations will come to seek Yahweh of Armies in Jerusalem, and to entreat the favor of Yahweh."'),
  ('a79c39c3-ca6e-514c-a98f-14e9e710c15b', 'c7e6cfb6-a1fb-5ad1-a9b2-1ac5a06dac07', NULL, 23, 23, 'Thus says Yahweh of Armies: "In those days, ten men will take hold, out of all the languages of the nations, they will take hold of the skirt of him who is a Jew, saying, ''We will go with you, for we have heard that God is with you.''"'),
  ('04feffae-2538-5975-ae9c-6b796cfc4cef', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 1, 1, 'An oracle. The word of Yahweh is against the land of Hadrach, and will rest upon Damascus; for the eye of man and of all the tribes of Israel is toward Yahweh;'),
  ('eac715fc-46c4-5628-a31f-ead2790f1ab0', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 2, 2, 'and Hamath, also, which borders on it; Tyre and Sidon, because they are very wise.'),
  ('33334d5a-2b2a-574f-a4d9-9c5c54aeffc0', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 3, 3, 'Tyre built herself a stronghold, and heaped up silver like the dust, and fine gold like the mire of the streets.'),
  ('54ea3920-a7fc-56c7-ac96-48c715397c8c', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 4, 4, 'Behold, the Lord will dispossess her, and he will strike her power in the sea; and she will be devoured with fire.'),
  ('01bff07e-0818-5469-a6c0-a6eb0ecf58e2', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 5, 5, 'Ashkelon will see it, and fear; Gaza also, and will writhe in agony; as will Ekron, for her expectation will be disappointed; and the king will perish from Gaza, and Ashkelon will not be inhabited.'),
  ('73f080fb-0750-542e-a773-53ab9a418bf3', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 6, 6, 'Foreigners will dwell in Ashdod, and I will cut off the pride of the Philistines.'),
  ('66faa979-d99d-5f23-adea-e15e5a70b5c8', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 7, 7, 'I will take away his blood out of his mouth, and his abominations from between his teeth; and he also will be a remnant for our God; and he will be as a chieftain in Judah, and Ekron as a Jebusite.'),
  ('f6f8698c-d26d-5809-af00-f831fd300cfc', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 8, 8, 'I will encamp around my house against the army, that none pass through or return; and no oppressor will pass through them any more: for now I have seen with my eyes.'),
  ('6d4c0869-055a-57cb-af6b-f18826887265', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 9, 9, 'Rejoice greatly, daughter of Zion! Shout, daughter of Jerusalem! Behold, your King comes to you! He is righteous, and having salvation; lowly, and riding on a donkey, even on a colt, the foal of a donkey.'),
  ('83eaa617-e903-54c9-a4ab-b2f064aa0815', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 10, 10, 'I will cut off the chariot from Ephraim, and the horse from Jerusalem; and the battle bow will be cut off; and he will speak peace to the nations: and his dominion will be from sea to sea, and from the River to the ends of the earth.'),
  ('d309e3d6-b259-532a-a0e9-855ad2b9094c', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 11, 11, 'As for you also, because of the blood of your covenant, I have set free your prisoners from the pit in which is no water.'),
  ('80815aca-b3e1-5b8b-add0-588e217eb2eb', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 12, 12, 'Turn to the stronghold, you prisoners of hope! Even today I declare that I will restore double to you.'),
  ('d440fb4d-f3df-5813-ade4-e94da6e2e0cd', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 13, 13, 'For indeed I bend Judah as a bow for me. I have filled the bow with Ephraim; and I will stir up your sons, Zion, against your sons, Greece, and will make you like the sword of a mighty man.'),
  ('4fe9cb5e-2b66-56cd-a380-8957c5ed724c', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 14, 14, 'Yahweh will be seen over them; and his arrow will go flash like lightning; and the Lord Yahweh will blow the trumpet, and will go with whirlwinds of the south.'),
  ('a8a9bd2c-85f7-511b-adcd-fb7c94ee7339', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 15, 15, 'Yahweh of Armies will defend them; and they will destroy and overcome with sling stones; and they will drink, and roar as through wine; and they will be filled like bowls, like the corners of the altar.'),
  ('01f8a4a9-5fb3-5325-a03c-ef0bb47e351a', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 16, 16, 'Yahweh their God will save them in that day as the flock of his people; for they are like the jewels of a crown, lifted on high over his land.'),
  ('461d5d95-45fa-51f1-af81-8877d6a856d4', '08db100a-3c49-57d7-a7b3-251b03940e99', NULL, 17, 17, 'For how great is his goodness, and how great is his beauty! Grain will make the young men flourish, and new wine the virgins.'),
  ('c05c04bc-d477-5b8e-a9db-448a735ebb70', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 1, 1, 'Ask of Yahweh rain in the spring time, Yahweh who makes storm clouds, and he gives rain showers to everyone for the plants in the field.'),
  ('fdf97f16-bcca-591a-a327-867b8d87596a', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 2, 2, 'For the teraphim have spoken vanity, and the diviners have seen a lie; and they have told false dreams. They comfort in vain. Therefore they go their way like sheep. They are oppressed, because there is no shepherd.'),
  ('bfe95738-e160-530c-a9eb-db17421a0b19', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 3, 3, 'My anger is kindled against the shepherds, and I will punish the male goats; For Yahweh of Armies has visited his flock, the house of Judah, and will make them as his majestic horse in the battle.'),
  ('68deaa8e-cd10-5ec4-a8ec-0da0720b7cf7', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 4, 4, 'From him will come forth the cornerstone, from him the nail, from him the battle bow, from him every ruler together.'),
  ('b7a36694-54ea-54df-ad4f-fe06392e3582', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 5, 5, 'They shall be as mighty men, treading down muddy streets in the battle; and they shall fight, because Yahweh is with them; and the riders on horses will be confounded.'),
  ('d73ec383-b799-5517-a416-92b686407845', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 6, 6, '"I will strengthen the house of Judah, and I will save the house of Joseph, and I will bring them back; for I have mercy on them; and they will be as though I had not cast them off: for I am Yahweh their God, and I will hear them.'),
  ('a3bd40db-f454-5e34-acb6-2ae284469992', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 7, 7, 'Ephraim will be like a mighty man, and their heart will rejoice as through wine; yes, their children will see it, and rejoice. Their heart will be glad in Yahweh.'),
  ('d8f1550f-c634-51c8-a942-b2e7801b6906', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 8, 8, 'I will signal for them, and gather them; for I have redeemed them; and they will increase as they have increased.'),
  ('9cf177a6-5871-5188-aac9-cdc2a6d7ed1d', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 9, 9, 'I will sow them among the peoples; and they will remember me in far countries; and they will live with their children, and will return.'),
  ('4e8a337e-9a75-5b08-ab9c-a7378e1add42', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 10, 10, 'I will bring them again also out of the land of Egypt, and gather them out of Assyria; and I will bring them into the land of Gilead and Lebanon; and there won''t be room enough for them.'),
  ('7f59d596-0872-576c-a558-21c491c851fa', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 11, 11, 'He will pass through the sea of affliction, and will strike the waves in the sea, and all the depths of the Nile will dry up; and the pride of Assyria will be brought down, and the scepter of Egypt will depart.'),
  ('9503665a-5f04-52ce-a505-dadfae3bdeb9', 'be85addf-8580-59f2-a0a0-7ae9f3da6296', NULL, 12, 12, 'I will strengthen them in Yahweh; and they will walk up and down in his name," says Yahweh.'),
  ('17063b20-b479-5efb-a273-d4681dfd52b5', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 1, 1, 'Open your doors, Lebanon, that the fire may devour your cedars.'),
  ('e9649beb-aff8-5a95-a875-0255a1309a40', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 2, 2, 'Wail, fir tree, for the cedar has fallen, because the stately ones are destroyed. Wail, you oaks of Bashan, for the strong forest has come down.'),
  ('0753ca03-df0b-537f-a615-2511b96c0522', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 3, 3, 'A voice of the wailing of the shepherds! For their glory is destroyed: a voice of the roaring of young lions! For the pride of the Jordan is ruined.'),
  ('3e323000-557d-5433-a2ef-d2015786c2cc', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 4, 4, 'Thus says Yahweh my God: "Feed the flock of slaughter.'),
  ('ce9d875b-b9fd-5c0f-ac1b-94c73b25ec3c', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 5, 5, 'Their buyers slaughter them, and go unpunished. Those who sell them say, ''Blessed be Yahweh, for I am rich;'' and their own shepherds don''t pity them.'),
  ('851b8d7b-60c3-5a80-a3fc-10f49ab91340', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 6, 6, 'For I will no more pity the inhabitants of the land," says Yahweh; "but, behold, I will deliver the men everyone into his neighbor''s hand, and into the hand of his king. They will strike the land, and out of their hand I will not deliver them."'),
  ('1204dd29-0f71-510b-a762-f88c0f5dcd06', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 7, 7, 'So I fed the flock of slaughter, especially the oppressed of the flock. I took for myself two staffs. The one I called "Favor," and the other I called "Union," and I fed the flock.'),
  ('7cbcb32b-774d-5e73-a58d-a1fe57b21d96', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 8, 8, 'I cut off the three shepherds in one month; for my soul was weary of them, and their soul also loathed me.'),
  ('94ad2398-23c1-5d3d-a89d-d7a8cfa3a6e0', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 9, 9, 'Then I said, "I will not feed you. That which dies, let it die; and that which is to be cut off, let it be cut off; and let those who are left eat each other''s flesh."'),
  ('b3d5f072-8718-5799-aa4b-f267b5c2c31c', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 10, 10, 'I took my staff Favor, and cut it apart, that I might break my covenant that I had made with all the peoples.'),
  ('6f8d5407-afb8-584d-a1cb-06a0774a3278', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 11, 11, 'It was broken in that day; and thus the poor of the flock that listened to me knew that it was the word of Yahweh.'),
  ('38b7d048-1185-51a9-adf8-31a49749488e', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 12, 12, 'I said to them, "If you think it best, give me my wages; and if not, keep them." So they weighed for my wages thirty pieces of silver.'),
  ('a5e50345-8a64-5e5c-ab07-009908ea2088', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 13, 13, 'Yahweh said to me, "Throw it to the potter, the handsome price that I was valued at by them!" I took the thirty pieces of silver, and threw them to the potter, in the house of Yahweh.'),
  ('79fb414b-cb88-5f62-ac33-9385f32422b5', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 14, 14, 'Then I cut apart my other staff, even Union, that I might break the brotherhood between Judah and Israel.'),
  ('1e022aa3-12b6-5033-a55a-c13f54b39d4d', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 15, 15, 'Yahweh said to me, "Take for yourself yet again the equipment of a foolish shepherd.'),
  ('36ff9aab-903e-5f5e-ada7-d77b044eaf88', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 16, 16, 'For, behold, I will raise up a shepherd in the land, who will not visit those who are cut off, neither will seek those who are scattered, nor heal that which is broken, nor feed that which is sound; but he will eat the flesh of the fat sheep, and will tear their hoofs in pieces.'),
  ('3b7f51a3-84a0-59ab-af97-390bc823b6e2', 'e64222a3-06e3-5387-a3be-6c2518a48899', NULL, 17, 17, 'Woe to the worthless shepherd who leaves the flock! The sword will be on his arm, and on his right eye. His arm will be completely withered, and his right eye will be totally blinded!"'),
  ('3469be61-aaa9-584a-ad92-229ec0932db4', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 1, 1, 'An oracle. The word of Yahweh concerning Israel. Yahweh, who stretches out the heavens, and lays the foundation of the earth, and forms the spirit of man within him says:'),
  ('bd1ba1c0-d555-5cc2-aa61-7d94770947a7', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 2, 2, '"Behold, I will make Jerusalem a cup of reeling to all the surrounding peoples, and on Judah also will it be in the siege against Jerusalem.'),
  ('e5b74499-e3fb-50e4-a1be-95f11bdfbb81', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 3, 3, 'It will happen in that day, that I will make Jerusalem a burdensome stone for all the peoples. All who burden themselves with it will be severely wounded, and all the nations of the earth will be gathered together against it.'),
  ('4b04a5d0-d48d-5b32-ab96-e24f49d08e92', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 4, 4, 'In that day," says Yahweh, "I will strike every horse with terror, and his rider with madness; and I will open my eyes on the house of Judah, and will strike every horse of the peoples with blindness.'),
  ('ed1795ca-4e55-5a00-afb6-9f939ae99561', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 5, 5, 'The chieftains of Judah will say in their heart, ''The inhabitants of Jerusalem are my strength in Yahweh of Armies their God.'''),
  ('01aeb44c-a602-5c67-afd1-d3005b1e57ce', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 6, 6, 'In that day I will make the chieftains of Judah like a pan of fire among wood, and like a flaming torch among sheaves; and they will devour all the surrounding peoples, on the right hand and on the left; and Jerusalem will yet again dwell in their own place, even in Jerusalem.'),
  ('ea3c37d9-333b-5bdf-aed2-52475bfeeb15', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 7, 7, 'Yahweh also will save the tents of Judah first, that the glory of the house of David and the glory of the inhabitants of Jerusalem not be magnified above Judah.'),
  ('67525ae4-5128-5455-a0bf-ebf5c2bc60ad', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 8, 8, 'In that day Yahweh will defend the inhabitants of Jerusalem. He who is feeble among them at that day will be like David, and the house of David will be like God, like the angel of Yahweh before them.'),
  ('7e9fce8a-e4e9-5bec-a6c1-0c6c0548d087', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 9, 9, 'It will happen in that day, that I will seek to destroy all the nations that come against Jerusalem.'),
  ('874e6056-ba6a-5fa3-a98c-adda4cb41b28', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 10, 10, 'I will pour on the house of David, and on the inhabitants of Jerusalem, the spirit of grace and of supplication; and they will look to me whom they have pierced; and they shall mourn for him, as one mourns for his only son, and will grieve bitterly for him, as one grieves for his firstborn.'),
  ('bd706ae8-3123-5bae-a84b-65807e4a8a83', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 11, 11, 'In that day there will be a great mourning in Jerusalem, like the mourning of Hadadrimmon in the valley of Megiddon.'),
  ('fb8981f3-4973-5103-a16a-cc56e6e31ef0', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 12, 12, 'The land will mourn, every family apart; the family of the house of David apart, and their wives apart; the family of the house of Nathan apart, and their wives apart;'),
  ('b5803581-9ca1-5314-aa22-b7023b8a217a', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 13, 13, 'the family of the house of Levi apart, and their wives apart; the family of the Shimeites apart, and their wives apart;'),
  ('5419612c-9258-5518-a387-7ba804b071ec', '72c83e7d-3ee5-5d03-ab4f-3d6b56a26c23', NULL, 14, 14, 'all the families who remain, every family apart, and their wives apart.'),
  ('102dbf5e-3928-5250-a0d2-a555a5440556', '3f745081-a60d-5d4d-ae4b-7765ece7778c', NULL, 1, 1, '"In that day there will be a spring opened to the house of David and to the inhabitants of Jerusalem, for sin and for uncleanness.'),
  ('b1ab58a9-5af3-50df-a38c-4b397451631e', '3f745081-a60d-5d4d-ae4b-7765ece7778c', NULL, 2, 2, 'It will come to pass in that day, says Yahweh of Armies, that I will cut off the names of the idols out of the land, and they will be remembered no more. I will also cause the prophets and the spirit of impurity to pass out of the land.'),
  ('d38dd9f5-d151-5d0d-abc6-df082b1c5438', '3f745081-a60d-5d4d-ae4b-7765ece7778c', NULL, 3, 3, 'It will happen that, when anyone still prophesies, then his father and his mother who bore him will tell him, ''You must die, because you speak lies in the name of Yahweh;'' and his father and his mother who bore him will stab him when he prophesies.'),
  ('07626253-0ebe-5c24-a8aa-04fac9f6a1db', '3f745081-a60d-5d4d-ae4b-7765ece7778c', NULL, 4, 4, 'It will happen in that day, that the prophets will each be ashamed of his vision, when he prophesies; neither will they wear a hairy mantle to deceive:'),
  ('4e4bd980-1517-558d-a7e3-9e02c4593655', '3f745081-a60d-5d4d-ae4b-7765ece7778c', NULL, 5, 5, 'but he will say, ''I am no prophet, I am a tiller of the ground; for I have been made a bondservant from my youth.'''),
  ('e2fefed9-208f-510f-a56b-a4a298b5ffea', '3f745081-a60d-5d4d-ae4b-7765ece7778c', NULL, 6, 6, 'One will say to him, ''What are these wounds between your arms?'' Then he will answer, ''Those with which I was wounded in the house of my friends.'''),
  ('249149ef-6403-5654-a8f2-7f711af2bfb6', '3f745081-a60d-5d4d-ae4b-7765ece7778c', NULL, 7, 7, '"Awake, sword, against my shepherd, and against the man who is close to me," says Yahweh of Armies. "Strike the shepherd, and the sheep will be scattered; and I will turn my hand against the little ones.'),
  ('137b045d-1b9a-5bf3-a6e7-22a58f1477b4', '3f745081-a60d-5d4d-ae4b-7765ece7778c', NULL, 8, 8, 'It shall happen that in all the land," says Yahweh, "two parts in it will be cut off and die; but the third will be left in it.'),
  ('03717e37-4564-5726-a4e2-45d114de59d4', '3f745081-a60d-5d4d-ae4b-7765ece7778c', NULL, 9, 9, 'I will bring the third part into the fire, and will refine them as silver is refined, and will test them like gold is tested. They will call on my name, and I will hear them. I will say, ''It is my people;'' and they will say, ''Yahweh is my God.''"'),
  ('2369dea8-6a1f-59ca-a4c6-ecd5aac4647a', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 1, 1, 'Behold, a day of Yahweh comes, when your spoil will be divided in your midst.'),
  ('866a200f-71ea-58cb-ab0f-0db11111aa4d', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 2, 2, 'For I will gather all nations against Jerusalem to battle; and the city will be taken, the houses rifled, and the women ravished. Half of the city will go out into captivity, and the rest of the people will not be cut off from the city.'),
  ('0729e47c-dfe3-534e-a566-544bfe8be043', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 3, 3, 'Then Yahweh will go out and fight against those nations, as when he fought in the day of battle.'),
  ('861f9176-a71c-5a27-ae4d-aafe6e95d399', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 4, 4, 'His feet will stand in that day on the Mount of Olives, which is before Jerusalem on the east; and the Mount of Olives will be split in two, from east to west, making a very great valley. Half of the mountain will move toward the north, and half of it toward the south.'),
  ('28bdace7-fa85-52eb-a50b-cff7c018562b', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 5, 5, 'You shall flee by the valley of my mountains; for the valley of the mountains shall reach to Azel; yes, you shall flee, just like you fled from before the earthquake in the days of Uzziah king of Judah. Yahweh my God will come, and all the holy ones with you.'),
  ('afabe5d2-a1b1-590a-af48-14ff4385560c', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 6, 6, 'It will happen in that day, that there will not be light, cold, or frost.'),
  ('2fda0163-6ab3-5495-a33d-c71b604fc140', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 7, 7, 'It will be a unique day which is known to Yahweh; not day, and not night; but it will come to pass, that at evening time there will be light.'),
  ('2be553e0-6b3e-5ce5-af90-d4ec729ae652', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 8, 8, 'It will happen in that day, that living waters will go out from Jerusalem; half of them toward the eastern sea, and half of them toward the western sea; in summer and in winter will it be.'),
  ('4e5acb54-a7b5-5e1e-a62e-8fc35b469880', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 9, 9, 'Yahweh will be King over all the earth. In that day Yahweh will be one, and his name one.'),
  ('68b53008-b2dd-5098-ac65-7d10093f8645', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 10, 10, 'All the land will be made like the Arabah, from Geba to Rimmon south of Jerusalem; and she will be lifted up, and will dwell in her place, from Benjamin''s gate to the place of the first gate, to the corner gate, and from the tower of Hananel to the king''s winepresses.'),
  ('68f576be-510d-5a92-afbb-f586ceb3def5', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 11, 11, 'Men will dwell therein, and there will be no more curse; but Jerusalem will dwell safely.'),
  ('52c1c846-cb10-573a-a6e3-767f3283a66b', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 12, 12, 'This will be the plague with which Yahweh will strike all the peoples who have warred against Jerusalem: their flesh will consume away while they stand on their feet, and their eyes will consume away in their sockets, and their tongue will consume away in their mouth.'),
  ('ff322175-d480-5aca-a346-8b929372d37b', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 13, 13, 'It will happen in that day, that a great panic from Yahweh will be among them; and they will lay hold everyone on the hand of his neighbor, and his hand will rise up against the hand of his neighbor.'),
  ('f172c3d9-6fbc-504c-a387-e181ed4c715d', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 14, 14, 'Judah also will fight at Jerusalem; and the wealth of all the surrounding nations will be gathered together: gold, and silver, and clothing, in great abundance.'),
  ('c374d264-410f-5e2b-aa2d-0a61ae5fb8ef', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 15, 15, 'So will be the plague of the horse, of the mule, of the camel, and of the donkey, and of all the animals that will be in those camps, as that plague.'),
  ('08755cbc-d939-5590-a351-042dd1229296', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 16, 16, 'It will happen that everyone who is left of all the nations that came against Jerusalem will go up from year to year to worship the King, Yahweh of Armies, and to keep the feast of tents.'),
  ('5182d5cf-f94e-5de1-a01f-7fd3548b7c44', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 17, 17, 'It will be, that whoever of all the families of the earth doesn''t go up to Jerusalem to worship the King, Yahweh of Armies, on them there will be no rain.'),
  ('7ba3ab22-3e8d-569b-aeee-9a22adcf7c48', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 18, 18, 'If the family of Egypt doesn''t go up, and doesn''t come, neither will it rain on them. This will be the plague with which Yahweh will strike the nations that don''t go up to keep the feast of tents.'),
  ('2e0ac52a-f11f-5765-a8ad-f883fd33be3c', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 19, 19, 'This will be the punishment of Egypt, and the punishment of all the nations that don''t go up to keep the feast of tents.'),
  ('03e58b66-7b48-5808-a210-b0fa5a304d35', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 20, 20, 'In that day there will be on the bells of the horses, "HOLY TO YAHWEH;" and the pots in Yahweh''s house will be like the bowls before the altar.'),
  ('cf92feec-9b90-5b4c-a092-f224a9798dbd', '46bb3880-ceae-5554-ad38-5e136b91b82b', NULL, 21, 21, 'Yes, every pot in Jerusalem and in Judah will be holy to Yahweh of Armies; and all those who sacrifice will come and take of them, and cook in them. In that day there will no longer be a Canaanite in the house of Yahweh of Armies.'),
  ('66be2c4e-9cb4-562d-a749-70924ea48aed', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 1, 1, 'An oracle: the word of Yahweh to Israel by Malachi.'),
  ('c7a8d400-780a-5541-a5f9-ebb52781136d', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 2, 2, '"I have loved you," says Yahweh. Yet you say, "How have you loved us?" "Wasn''t Esau Jacob''s brother?" says Yahweh, "Yet I loved Jacob;'),
  ('fb743367-3593-5acc-a1f1-d7bc1756ba4b', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 3, 3, 'but Esau I hated, and made his mountains a desolation, and gave his heritage to the jackals of the wilderness."'),
  ('e55c2054-8b3d-5775-ad0e-eba744d439fe', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 4, 4, 'Whereas Edom says, "We are beaten down, but we will return and build the waste places;" thus says Yahweh of Armies, "They shall build, but I will throw down; and men will call them ''The Wicked Land,'' even the people against whom Yahweh shows wrath forever."'),
  ('f8833364-25c7-54c5-acc4-96f239f5ede9', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 5, 5, 'Your eyes will see, and you will say, "Yahweh is great--even beyond the border of Israel!"'),
  ('063ab144-94ae-5883-a5b4-befebf3438d7', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 6, 6, '"A son honors his father, and a servant his master. If I am a father, then where is my honor? And if I am a master, where is the respect due me? Says Yahweh of Armies to you, priests, who despise my name. You say, ''How have we despised your name?'''),
  ('9b0bcd59-a75a-566a-a6e5-1f882d2ccbfc', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 7, 7, 'You offer polluted bread on my altar. You say, ''How have we polluted you?'' In that you say, ''Yahweh''s table contemptible.'''),
  ('735c83bc-2a16-585e-ab7c-8202f6b37a78', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 8, 8, 'When you offer the blind for sacrifice, isn''t that evil? And when you offer the lame and sick, isn''t that evil? Present it now to your governor! Will he be pleased with you? Or will he accept your person?" says Yahweh of Armies.'),
  ('d17c9f13-f75e-5fab-abb4-f575e61b6ea4', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 9, 9, '"Now, please entreat the favor of God, that he may be gracious to us. With this, will he accept any of you?" says Yahweh of Armies.'),
  ('d305d3ff-2054-59e5-ae43-e99d47f9906e', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 10, 10, '"Oh that there were one among you who would shut the doors, that you might not kindle fire on my altar in vain! I have no pleasure in you," says Yahweh of Armies, "neither will I accept an offering at your hand.'),
  ('c7f30977-622f-5d8e-ab9b-f13f19a79149', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 11, 11, 'For from the rising of the sun even to the going down of the same, my name is great among the nations, and in every place incense will be offered to my name, and a pure offering: for my name is great among the nations," says Yahweh of Armies.'),
  ('7567db3d-6c9f-5d8c-aa7c-19f5956337d7', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 12, 12, '"But you profane it, in that you say, ''Yahweh''s table is polluted, and its fruit, even its food, is contemptible.'''),
  ('140a131a-4858-54da-a363-df6cf9e9017b', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 13, 13, 'You say also, ''Behold, what a weariness it is!'' and you have sniffed at it," says Yahweh of Armies; "and you have brought that which was taken by violence, the lame, and the sick; thus you bring the offering. Should I accept this at your hand?" says Yahweh.'),
  ('30d41441-f673-5d44-a21a-77d24c79c1d3', 'f90f37dc-cfe3-54f0-a74b-8efce416ec8e', NULL, 14, 14, '"But the deceiver is cursed, who has in his flock a male, and vows, and sacrifices to the Lord a blemished thing; for I am a great King," says Yahweh of Armies, "and my name is awesome among the nations."'),
  ('e415d411-afa6-56d6-a280-d958e495f41f', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 1, 1, '"Now, you priests, this commandment is for you.'),
  ('c5f510c9-1ce4-59d5-af9b-d07e4e960e9b', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 2, 2, 'If you will not listen, and if you will not lay it to heart, to give glory to my name," says Yahweh of Armies, "then will I send the curse on you, and I will curse your blessings. Indeed, I have cursed them already, because you do not lay it to heart.'),
  ('61140add-b986-590f-ae83-5d936c5c74f9', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 3, 3, 'Behold, I will rebuke your seed, and will spread dung on your faces, even the dung of your feasts; and you will be taken away with it.'),
  ('c2087564-a2f5-5737-a2df-89b30f698583', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 4, 4, 'You will know that I have sent this commandment to you, that my covenant may be with Levi," says Yahweh of Armies.'),
  ('9f30cc97-1257-54af-a490-a9ef0eba9a1a', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 5, 5, '"My covenant was with him of life and peace; and I gave them to him that he might be reverent toward me; and he was reverent toward me, and stood in awe of my name.'),
  ('a28c32a8-d148-5ec6-a2b3-14ae3a05519c', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 6, 6, 'The law of truth was in his mouth, and unrighteousness was not found in his lips. He walked with me in peace and uprightness, and turned many away from iniquity.'),
  ('c4f9eaf3-080e-586f-abe5-e6e8ff8e1a60', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 7, 7, 'For the priest''s lips should keep knowledge, and they should seek the law at his mouth; for he is the messenger of Yahweh of Armies.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('eb2e06d9-9b64-557e-a6bc-05de48327cbb', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 8, 8, 'But you have turned aside out of the way. You have caused many to stumble in the law. You have corrupted the covenant of Levi," says Yahweh of Armies.'),
  ('867a274d-7492-5e68-a495-ac2d3dc728b2', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 9, 9, '"Therefore I have also made you contemptible and base before all the people, according to the way you have not kept my ways, but have had respect for persons in the law.'),
  ('2894630f-2ca4-5a9b-a9d5-dea9936228a7', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 10, 10, 'Don''t we all have one father? Hasn''t one God created us? Why do we deal treacherously every man against his brother, profaning the covenant of our fathers?'),
  ('33bc2db0-07df-52fe-ac14-188b32d1d153', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 11, 11, 'Judah has dealt treacherously, and an abomination is committed in Israel and in Jerusalem; for Judah has profaned the holiness of Yahweh which he loves, and has married the daughter of a foreign god.'),
  ('373f2f2a-f96c-570a-a911-c3ce5c268571', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 12, 12, 'Yahweh will cut off, to the man who does this, him who wakes and him who answers, out of the tents of Jacob, and him who offers an offering to Yahweh of Armies.'),
  ('55cab1c0-fd18-5321-a1f8-c5c4daebe933', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 13, 13, 'This again you do: you cover the altar of Yahweh with tears, with weeping, and with sighing, because he doesn''t regard the offering any more, neither receives it with good will at your hand.'),
  ('4bba2a3c-fcb4-548a-a53c-a198bc5677fa', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 14, 14, 'Yet you say, ''Why?'' Because Yahweh has been witness between you and the wife of your youth, against whom you have dealt treacherously, though she is your companion, and the wife of your covenant.'),
  ('d8affc29-7f9b-5dc9-a9c4-cbb422afbb6e', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 15, 15, 'Did he not make you one, although he had the residue of the Spirit? Why one? He sought a godly seed. Therefore take heed to your spirit, and let no one deal treacherously against the wife of his youth.'),
  ('a3eb2246-cf8a-5c74-a650-34082735bd72', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 16, 16, 'For I hate divorce," says Yahweh, the God of Israel, "and him who covers his garment with violence!" says Yahweh of Armies. "Therefore take heed to your spirit, that you don''t deal treacherously.'),
  ('b6cb6c6b-040f-567d-a492-b1afe9ed2a64', '25c829fd-6d95-555f-ac1a-f518806604bd', NULL, 17, 17, 'You have wearied Yahweh with your words. Yet you say, ''How have we wearied him?'' In that you say, ''Everyone who does evil is good in the sight of Yahweh, and he delights in them;'' or ''Where is the God of justice?'''),
  ('c99fde5e-2544-5f42-ac29-57e534c26565', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 1, 1, '"Behold, I send my messenger, and he will prepare the way before me; and the Lord, whom you seek, will suddenly come to his temple; and the messenger of the covenant, whom you desire, behold, he comes!" says Yahweh of Armies.'),
  ('040b66bb-ec53-55c9-aa42-0738f9f0338b', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 2, 2, '"But who can endure the day of his coming? And who will stand when he appears? For he is like a refiner''s fire, and like launderer''s soap;'),
  ('0580e3bf-08d7-5561-aa6b-4fdfb793541a', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 3, 3, 'and he will sit as a refiner and purifier of silver, and he will purify the sons of Levi, and refine them as gold and silver; and they shall offer to Yahweh offerings in righteousness.'),
  ('910a7cab-7eb4-51ad-a15c-3814a203a0db', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 4, 4, 'Then the offering of Judah and Jerusalem will be pleasant to Yahweh, as in the days of old, and as in ancient years.'),
  ('8b83f1a4-78fe-57df-a9dc-3a097d893bed', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 5, 5, 'I will come near to you to judgment; and I will be a swift witness against the sorcerers, and against the adulterers, and against the perjurers, and against those who oppress the hireling in his wages, the widow, and the fatherless, and who deprive the foreigner of justice, and don''t fear me," says Yahweh of Armies.'),
  ('4274fa38-76c4-5989-af63-8fff045d45d2', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 6, 6, '"For I, Yahweh, don''t change; therefore you, sons of Jacob, are not consumed.'),
  ('3c19d574-cad3-5d27-ac50-e28fe060702e', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 7, 7, 'From the days of your fathers you have turned aside from my ordinances, and have not kept them. Return to me, and I will return to you," says Yahweh of Armies. "But you say, ''How shall we return?'''),
  ('c56e9da1-d317-57f2-a2fe-3a887e08c462', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 8, 8, 'Will a man rob God? Yet you rob me! But you say, ''How have we robbed you?'' In tithes and offerings.'),
  ('e3168985-e50a-55d9-a976-fe95332034af', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 9, 9, 'You are cursed with the curse; for you rob me, even this whole nation.'),
  ('d9570f9a-0c3b-5f4f-a385-7ec372f6ab76', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 10, 10, 'Bring the whole tithe into the storehouse, that there may be food in my house, and test me now in this," says Yahweh of Armies, "if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough for.'),
  ('2229b31d-85a8-59bf-ac6a-31c3208f5c17', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 11, 11, 'I will rebuke the devourer for your sakes, and he shall not destroy the fruits of your ground; neither shall your vine cast its fruit before its time in the field," says Yahweh of Armies.'),
  ('16796f24-f28d-5164-ad38-6b926e19dccf', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 12, 12, '"All nations shall call you blessed, for you will be a delightful land," says Yahweh of Armies.'),
  ('864f6f0e-ce47-57b9-a170-d2de0338f567', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 13, 13, '"Your words have been stout against me," says Yahweh. "Yet you say, ''What have we spoken against you?'''),
  ('6ba4670d-699c-50d2-ae7e-4a3bedd8e17a', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 14, 14, 'You have said, ''It is vain to serve God;'' and ''What profit is it that we have followed his instructions, and that we have walked mournfully before Yahweh of Armies?'),
  ('483a4660-48cb-53dd-a5ab-532155f6fe2f', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 15, 15, 'Now we call the proud happy; yes, those who work wickedness are built up; yes, they tempt God, and escape.'''),
  ('28e1757e-ce80-5b37-a0b7-26795e103ba4', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 16, 16, 'Then those who feared Yahweh spoke one with another; and Yahweh listened, and heard, and a book of memory was written before him, for those who feared Yahweh, and who honored his name.'),
  ('6d1b5c68-4e26-515f-a179-f4f8b6a19476', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 17, 17, 'They shall be mine," says Yahweh of Armies, "my own possession in the day that I make, and I will spare them, as a man spares his own son who serves him.'),
  ('6cabe48d-74c5-511a-aac1-fe11812ea181', 'be22feb4-58d9-5b86-a410-179d44a1d0b0', NULL, 18, 18, 'Then you shall return and discern between the righteous and the wicked, between him who serves God and him who doesn''t serve him.'),
  ('c65c5d0e-709c-5dc8-a604-0f51a8c32017', '8e323c08-5397-521f-a6f5-7dea8b8d2a69', NULL, 1, 1, '"For, behold, the day comes, it burns as a furnace; and all the proud, and all who work wickedness, will be stubble; and the day that comes will burn them up," says Yahweh of Armies, "that it shall leave them neither root nor branch.'),
  ('f25bacec-b6a2-59d6-ae6d-7155915e4706', '8e323c08-5397-521f-a6f5-7dea8b8d2a69', NULL, 2, 2, 'But to you who fear my name shall the sun of righteousness arise with healing in its wings. You will go out, and leap like calves of the stall.'),
  ('8be2efa2-c842-55cf-a3fa-66eede78cbf1', '8e323c08-5397-521f-a6f5-7dea8b8d2a69', NULL, 3, 3, 'You shall tread down the wicked; for they will be ashes under the soles of your feet in the day that I make," says Yahweh of Armies.'),
  ('6489f525-1cfe-5360-aebd-64729dbaea1a', '8e323c08-5397-521f-a6f5-7dea8b8d2a69', NULL, 4, 4, '"Remember the law of Moses my servant, which I commanded to him in Horeb for all Israel, even statutes and ordinances.'),
  ('c6cfce5e-1258-5ec7-a38b-3dbabe24c1d1', '8e323c08-5397-521f-a6f5-7dea8b8d2a69', NULL, 5, 5, 'Behold, I will send you Elijah the prophet before the great and terrible day of Yahweh comes.'),
  ('2d1ac407-07f4-5953-a4b1-3237faf54d1f', '8e323c08-5397-521f-a6f5-7dea8b8d2a69', NULL, 6, 6, 'He will turn the hearts of the fathers to the children, and the hearts of the children to their fathers, lest I come and strike the earth with a curse."'),
  ('b2505d5b-c940-5df9-af4d-613649039e6e', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 1, 1, 'The book of the genealogy of Jesus Christ, the son of David, the son of Abraham.'),
  ('ae8d559a-6d87-5eec-adba-9bf7fc7f308c', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 2, 2, 'Abraham became the father of Isaac. Isaac became the father of Jacob. Jacob became the father of Judah and his brothers.'),
  ('9214131d-4040-5c1e-a232-7d1b28ed0de5', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 3, 3, 'Judah became the father of Perez and Zerah by Tamar. Perez became the father of Hezron. Hezron became the father of Ram.'),
  ('01c7e0b5-0b01-51ff-ad7c-117286bdc19c', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 4, 4, 'Ram became the father of Amminadab. Amminadab became the father of Nahshon. Nahshon became the father of Salmon.'),
  ('9b73eb8b-b55b-580c-aa1f-39ae9e1bf906', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 5, 5, 'Salmon became the father of Boaz by Rahab. Boaz became the father of Obed by Ruth. Obed became the father of Jesse.'),
  ('35a65c47-d5c5-525b-a121-b59965a647f2', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 6, 6, 'Jesse became the father of King David. David became the father of Solomon by her who had been the wife of Uriah.'),
  ('6a028d8f-fbf0-5784-abbb-1b8e85c5a4e6', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 7, 7, 'Solomon became the father of Rehoboam. Rehoboam became the father of Abijah. Abijah became the father of Asa.'),
  ('f8c084ee-08a6-5824-a722-c13fe7259650', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 8, 8, 'Asa became the father of Jehoshaphat. Jehoshaphat became the father of Joram. Joram became the father of Uzziah.'),
  ('e13122f6-1294-59b1-a045-417c06381a74', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 9, 9, 'Uzziah became the father of Jotham. Jotham became the father of Ahaz. Ahaz became the father of Hezekiah.'),
  ('2c868cb9-e65a-5644-a1f5-f7c228377637', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 10, 10, 'Hezekiah became the father of Manasseh. Manasseh became the father of Amon. Amon became the father of Josiah.'),
  ('98a651f6-0f58-5c9b-a9f8-e62b99d2f9e2', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 11, 11, 'Josiah became the father of Jechoniah and his brothers, at the time of the exile to Babylon.'),
  ('ab362a2d-7bd9-5cd3-a926-4e5b52182e30', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 12, 12, 'After the exile to Babylon, Jechoniah became the father of Shealtiel. Shealtiel became the father of Zerubbabel.'),
  ('06fed997-03e0-55a0-a821-51f5c8bfd23b', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 13, 13, 'Zerubbabel became the father of Abiud. Abiud became the father of Eliakim. Eliakim became the father of Azor.'),
  ('abd4fed2-a69a-5314-ad6d-be7c568fb401', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 14, 14, 'Azor became the father of Sadoc. Sadoc became the father of Achim. Achim became the father of Eliud.'),
  ('7b831c80-6f79-5439-a0d0-d67014bb5634', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 15, 15, 'Eliud became the father of Eleazar. Eleazar became the father of Matthan. Matthan became the father of Jacob.'),
  ('29480be0-af04-5efb-aed6-b298a2d43757', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 16, 16, 'Jacob became the father of Joseph, the husband of Mary, from whom was born Jesus, who is called Christ.'),
  ('9dbb15af-9ffd-5e0c-a0c8-2343b91ed5c3', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 17, 17, 'So all the generations from Abraham to David are fourteen generations; from David to the exile to Babylon fourteen generations; and from the carrying away to Babylon to the Christ, fourteen generations.'),
  ('713c03f9-6ab8-5f93-a897-c1383c6fd3cb', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 18, 18, 'Now the birth of Jesus Christ was like this; for after his mother, Mary, was engaged to Joseph, before they came together, she was found pregnant by the Holy Spirit.'),
  ('50f2575c-59bc-5583-ab64-377f63ff060e', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 19, 19, 'Joseph, her husband, being a righteous man, and not willing to make her a public example, intended to put her away secretly.'),
  ('e202940d-86f4-50e0-ad7c-94403e413da0', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 20, 20, 'But when he thought about these things, behold, an angel of the Lord appeared to him in a dream, saying, "Joseph, son of David, don''t be afraid to take to yourself Mary, your wife, for that which is conceived in her is of the Holy Spirit.'),
  ('5afec246-7d82-5e06-adf5-0e7be8b4875f', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 21, 21, 'She shall bring forth a son. You shall call his name Jesus, for it is he who shall save his people from their sins."'),
  ('ab9d58dc-216d-545c-a9f7-5ebca973e983', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 22, 22, 'Now all this has happened, that it might be fulfilled which was spoken by the Lord through the prophet, saying,'),
  ('3c42e5e4-600a-5988-a50c-2b887a0257f7', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 23, 23, '"Behold, the virgin shall be with child, and shall bring forth a son. They shall call his name Immanuel;" which is, being interpreted, "God with us."'),
  ('667b41d6-b1f3-5843-ab13-e393f86f6347', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 24, 24, 'Joseph arose from his sleep, and did as the angel of the Lord commanded him, and took his wife to himself;'),
  ('6695491f-e55c-5255-ab0e-571e04ebe8b4', '99ef5f42-ce67-53fa-a072-4b0848a36343', NULL, 25, 25, 'and didn''t know her sexually until she had brought forth her firstborn son. He named him Jesus.'),
  ('3206ae8d-ebd2-534b-adb3-c47436645e39', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 1, 1, 'Now when Jesus was born in Bethlehem of Judea in the days of King Herod, behold, wise men from the east came to Jerusalem, saying,'),
  ('fd793b03-6498-5e2a-a125-7a42a5b8dfdd', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 2, 2, '"Where is he who is born King of the Jews? For we saw his star in the east, and have come to worship him."'),
  ('d5d14e7d-4ee4-5d03-ad73-0b7ec7cb9dad', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 3, 3, 'When King Herod heard it, he was troubled, and all Jerusalem with him.'),
  ('c2d2f5b0-7743-5bb7-a787-bda7750b3c1a', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 4, 4, 'Gathering together all the chief priests and scribes of the people, he asked them where the Christ would be born.'),
  ('f8901405-638f-5aac-a266-493db1d3f4a9', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 5, 5, 'They said to him, "In Bethlehem of Judea, for this is written through the prophet,'),
  ('b4e92ee1-7656-5c6a-a9e2-7bca7d30c1cf', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 6, 6, '''You Bethlehem, land of Judah, are in no way least among the princes of Judah: for out of you shall come forth a governor, who shall shepherd my people, Israel.''"'),
  ('408995c5-435b-59f1-a1ad-5f3c5e3dd285', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 7, 7, 'Then Herod secretly called the wise men, and learned from them exactly what time the star appeared.'),
  ('2ad0dd5c-d1a6-598b-a1e9-ccf238f64f50', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 8, 8, 'He sent them to Bethlehem, and said, "Go and search diligently for the young child. When you have found him, bring me word, so that I also may come and worship him."'),
  ('c368dbbd-4f52-5bb5-a83d-48c4fc7afe4d', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 9, 9, 'They, having heard the king, went their way; and behold, the star, which they saw in the east, went before them, until it came and stood over where the young child was.'),
  ('7ed40bbc-4b71-5d5a-a527-cf75169c249d', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 10, 10, 'When they saw the star, they rejoiced with exceedingly great joy.'),
  ('e9e91d17-abb8-5165-a9c5-1d2d9dbe5964', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 11, 11, 'They came into the house and saw the young child with Mary, his mother, and they fell down and worshiped him. Opening their treasures, they offered to him gifts: gold, frankincense, and myrrh.'),
  ('cc5b6f15-2daa-5fc4-aaa8-8728aa3bedb5', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 12, 12, 'Being warned in a dream that they shouldn''t return to Herod, they went back to their own country another way.'),
  ('f282d924-dac8-515c-a16a-5d4fb565bc57', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 13, 13, 'Now when they had departed, behold, an angel of the Lord appeared to Joseph in a dream, saying, "Arise and take the young child and his mother, and flee into Egypt, and stay there until I tell you, for Herod will seek the young child to destroy him."'),
  ('f43d8807-0686-5868-a9ee-929b0bb31cac', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 14, 14, 'He arose and took the young child and his mother by night, and departed into Egypt,'),
  ('18277fe0-872d-5110-ad27-5b65b7d3464e', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 15, 15, 'and was there until the death of Herod; that it might be fulfilled which was spoken by the Lord through the prophet, saying, "Out of Egypt I called my son."'),
  ('586484b7-8fb9-58bf-a9a6-5b1edec7a270', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 16, 16, 'Then Herod, when he saw that he was mocked by the wise men, was exceedingly angry, and sent out, and killed all the male children who were in Bethlehem and in all the surrounding countryside, from two years old and under, according to the exact time which he had learned from the wise men.'),
  ('5c816d09-0773-594e-a770-008701e98942', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 17, 17, 'Then that which was spoken by Jeremiah the prophet was fulfilled, saying,'),
  ('6cbd373c-5b3f-569d-aeb2-b1c963795773', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 18, 18, '"A voice was heard in Ramah, lamentation, weeping and great mourning, Rachel weeping for her children; she wouldn''t be comforted, because they are no more."'),
  ('1ae96f9c-53a4-5543-a459-730ba22b2e93', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 19, 19, 'But when Herod was dead, behold, an angel of the Lord appeared in a dream to Joseph in Egypt, saying,'),
  ('945d0583-4c4a-5c43-afbf-2c0c1d342e1e', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 20, 20, '"Arise and take the young child and his mother, and go into the land of Israel, for those who sought the young child''s life are dead."'),
  ('6d82a9b5-40be-58f3-a53c-8f3a99ac82a3', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 21, 21, 'He arose and took the young child and his mother, and came into the land of Israel.'),
  ('ae0f6a7b-284a-540f-ac91-705c227e0f3c', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 22, 22, 'But when he heard that Archelaus was reigning over Judea in the place of his father, Herod, he was afraid to go there. Being warned in a dream, he withdrew into the region of Galilee,'),
  ('a94260d2-c934-5d65-a1f5-b9f5afebd159', 'a848085e-380c-5228-a3b6-6130150e6ca5', NULL, 23, 23, 'and came and lived in a city called Nazareth; that it might be fulfilled which was spoken through the prophets: "He will be called a Nazarene."'),
  ('46f59c8f-1d56-555b-ab44-2f0049b862d8', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 1, 1, 'In those days, John the Baptizer came, preaching in the wilderness of Judea, saying,'),
  ('cf7ee778-5315-59aa-a1b0-f82bb74069d8', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 2, 2, '"Repent, for the Kingdom of Heaven is at hand!"'),
  ('39d488c9-c08d-5157-a918-fe9f89c557cc', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 3, 3, 'For this is he who was spoken of by Isaiah the prophet, saying, "The voice of one crying in the wilderness, make ready the way of the Lord. Make his paths straight."'),
  ('a41bf915-ad91-57a7-ab01-f7e0180ee3b9', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 4, 4, 'Now John himself wore clothing made of camel''s hair, with a leather belt around his waist. His food was locusts and wild honey.'),
  ('43f5e984-5323-5932-a12e-23cbccda1564', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 5, 5, 'Then people from Jerusalem, all of Judea, and all the region around the Jordan went out to him.'),
  ('01f51fc0-3a37-5e01-a458-ab2d8bb00610', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 6, 6, 'They were baptized by him in the Jordan, confessing their sins.'),
  ('914567c6-f0ca-5c9c-a251-826b34faa3a7', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 7, 7, 'But when he saw many of the Pharisees and Sadducees coming for his baptism, he said to them, "You offspring of vipers, who warned you to flee from the wrath to come?'),
  ('6b00e31d-5d80-54e3-aef6-e21db02ab59d', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 8, 8, 'Therefore bring forth fruit worthy of repentance!'),
  ('33dab4da-3bc8-5131-a432-2c70bcd1ae65', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 9, 9, 'Don''t think to yourselves, ''We have Abraham for our father,'' for I tell you that God is able to raise up children to Abraham from these stones.'),
  ('23e80d49-e511-5263-a556-5dd1e4a1a78b', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 10, 10, '"Even now the axe lies at the root of the trees. Therefore, every tree that doesn''t bring forth good fruit is cut down, and cast into the fire.'),
  ('5fc837e3-9cba-555e-a550-8e562a422d86', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 11, 11, 'I indeed baptize you in water for repentance, but he who comes after me is mightier than I, whose shoes I am not worthy to carry. He will baptize you in the Holy Spirit.'),
  ('787d8d24-5803-5907-ae15-4af3aec67f0a', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 12, 12, 'His winnowing fork is in his hand, and he will thoroughly cleanse his threshing floor. He will gather his wheat into the barn, but the chaff he will burn up with unquenchable fire."'),
  ('be373bac-ee16-5f5f-afc5-ddb1c39bd958', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 13, 13, 'Then Jesus came from Galilee to the Jordan to John, to be baptized by him.'),
  ('fd9378a3-e080-5cf9-aa68-fef0a32196fa', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 14, 14, 'But John would have hindered him, saying, "I need to be baptized by you, and you come to me?"'),
  ('46672a3b-5963-591f-a4cc-7cc11bb5924e', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 15, 15, 'But Jesus, answering, said to him, "Allow it now, for this is the fitting way for us to fulfill all righteousness." Then he allowed him.'),
  ('037eeb52-caa1-554e-ab72-87a84e695480', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 16, 16, 'Jesus, when he was baptized, went up directly from the water: and behold, the heavens were opened to him. He saw the Spirit of God descending as a dove, and coming on him.'),
  ('cd289fb3-b339-54d4-a871-435245067f3c', 'd760bfed-8c11-5e8e-a609-ad99ffd9530e', NULL, 17, 17, 'Behold, a voice out of the heavens said, "This is my beloved Son, with whom I am well pleased."'),
  ('b8acebb4-db7f-5381-a78b-26cf1544f388', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 1, 1, 'Then Jesus was led up by the Spirit into the wilderness to be tempted by the devil.'),
  ('19712570-95f3-523d-a43e-a98b4355becd', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 2, 2, 'When he had fasted forty days and forty nights, he was hungry afterward.'),
  ('4d19f311-62b4-5238-a699-bb4001e8debe', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 3, 3, 'The tempter came and said to him, "If you are the Son of God, command that these stones become bread."'),
  ('5b59f150-e561-5026-a167-0174457b16b7', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 4, 4, 'But he answered, "It is written, ''Man shall not live by bread alone, but by every word that proceeds out of the mouth of God.''"'),
  ('cc50d604-b7b7-5920-a006-eed923710bce', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 5, 5, 'Then the devil took him into the holy city. He set him on the pinnacle of the temple,'),
  ('d4cd5e79-9bf1-5c18-ae32-fd9fa5d560e1', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 6, 6, 'and said to him, "If you are the Son of God, throw yourself down, for it is written, ''He will put his angels in charge of you.'' and, ''On their hands they will bear you up, so that you don''t dash your foot against a stone.''"'),
  ('c3dcecf0-9c3f-56ba-addb-25ec1206c2bf', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 7, 7, 'Jesus said to him, "Again, it is written, ''You shall not test the Lord, your God.''"'),
  ('9c70d1c8-a05b-5cb8-aa61-71e83c90ba5e', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 8, 8, 'Again, the devil took him to an exceedingly high mountain, and showed him all the kingdoms of the world, and their glory.'),
  ('95d87074-7a5f-58a8-a3ff-49bfbc4f735e', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 9, 9, 'He said to him, "I will give you all of these things, if you will fall down and worship me."'),
  ('b7870ea1-ec98-5caf-abba-ce5c8efa53bb', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 10, 10, 'Then Jesus said to him, "Get behind me, Satan! For it is written, ''You shall worship the Lord your God, and you shall serve him only.''"'),
  ('5e0afc8f-84b7-582b-a6fc-5c17426a1873', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 11, 11, 'Then the devil left him, and behold, angels came and served him.'),
  ('f29fde13-b306-5209-accd-677e7035c6e7', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 12, 12, 'Now when Jesus heard that John was delivered up, he withdrew into Galilee.'),
  ('ab66f219-6f6c-5e22-a578-01f4a6853cb2', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 13, 13, 'Leaving Nazareth, he came and lived in Capernaum, which is by the sea, in the region of Zebulun and Naphtali,'),
  ('c2e65ef4-002d-53d1-a9c7-644e06e58578', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 14, 14, 'that it might be fulfilled which was spoken through Isaiah the prophet, saying,'),
  ('125af6ef-2367-5486-a511-46b29dd7f34d', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 15, 15, '"The land of Zebulun and the land of Naphtali, toward the sea, beyond the Jordan, Galilee of the Gentiles,'),
  ('dac9731e-f897-586c-a998-f1d3ce16c6c5', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 16, 16, 'the people who sat in darkness saw a great light, to those who sat in the region and shadow of death, to them light has dawned."'),
  ('3ec941ce-0e78-5ade-a93d-b19be0637760', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 17, 17, 'From that time, Jesus began to preach, and to say, "Repent! For the Kingdom of Heaven is at hand."'),
  ('1fea6d31-99d0-5472-a854-062c3f508777', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 18, 18, 'Walking by the sea of Galilee, he saw two brothers: Simon, who is called Peter, and Andrew, his brother, casting a net into the sea; for they were fishermen.'),
  ('2147bfad-2b1d-5a14-a056-c479d664d042', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 19, 19, 'He said to them, "Come after me, and I will make you fishers for men."'),
  ('a5338eda-2fa8-545a-a7fb-b5b9a6ac5567', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 20, 20, 'They immediately left their nets and followed him.'),
  ('0d5527b7-dcc4-502f-aad6-b2e1224976fd', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 21, 21, 'Going on from there, he saw two other brothers, James the son of Zebedee, and John his brother, in the boat with Zebedee their father, mending their nets. He called them.'),
  ('6351dbba-386c-58cc-a4b1-dd4611c67190', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 22, 22, 'They immediately left the boat and their father, and followed him.'),
  ('7ccead9c-024c-5e7a-a4a5-c13969cdb6de', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 23, 23, 'Jesus went about in all Galilee, teaching in their synagogues, preaching the Good News of the Kingdom, and healing every disease and every sickness among the people.'),
  ('34d7a2d4-f2d5-53db-a9ac-146ad380a15c', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 24, 24, 'The report about him went out into all Syria. They brought to him all who were sick, afflicted with various diseases and torments, possessed with demons, epileptics, and paralytics; and he healed them.'),
  ('55ac965d-5603-56e6-ab0b-daeb85668481', 'bb37329a-18a6-5e21-aca4-909dccc2befc', NULL, 25, 25, 'Great multitudes from Galilee, Decapolis, Jerusalem, Judea and from beyond the Jordan followed him.'),
  ('489b098a-ab8e-53e4-a9ed-69101b4cac0a', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 1, 1, 'Seeing the multitudes, he went up onto the mountain. When he had sat down, his disciples came to him.'),
  ('0b49827b-ddca-5d5d-ac67-cb956e6cae9e', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 2, 2, 'He opened his mouth and taught them, saying,'),
  ('627154e4-d01e-5040-a679-730678545982', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 3, 3, '"Blessed are the poor in spirit, for theirs is the Kingdom of Heaven.'),
  ('9ff3af32-e7ad-519c-a863-3689db95e992', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 4, 4, 'Blessed are those who mourn, for they shall be comforted.'),
  ('8b6b23fc-698d-5708-aed2-81cd3b3f8782', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 5, 5, 'Blessed are the gentle, for they shall inherit the earth.'),
  ('d2cb218a-f849-517a-a9fe-da3f89756dd1', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 6, 6, 'Blessed are those who hunger and thirst after righteousness, for they shall be filled.'),
  ('663bd8ba-5d7c-59fa-ad2c-2093471d8e31', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 7, 7, 'Blessed are the merciful, for they shall obtain mercy.'),
  ('4b72dcb4-224c-5d24-a897-707f61e4251b', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 8, 8, 'Blessed are the pure in heart, for they shall see God.'),
  ('899dd18c-0ef8-5107-a834-fbee404c7c97', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 9, 9, 'Blessed are the peacemakers, for they shall be called children of God.'),
  ('7c065d11-eaf3-5839-aef4-a58ecdb1c510', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 10, 10, 'Blessed are those who have been persecuted for righteousness'' sake, for theirs is the Kingdom of Heaven.'),
  ('efed992e-6cb5-5885-a711-862ea31d1954', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 11, 11, '"Blessed are you when people reproach you, persecute you, and say all kinds of evil against you falsely, for my sake.'),
  ('82926e0b-ff47-51bc-abcc-288c0efa63c7', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 12, 12, 'Rejoice, and be exceedingly glad, for great is your reward in heaven. For that is how they persecuted the prophets who were before you.'),
  ('2aec47c6-b6b3-518f-a421-12a80d76be99', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 13, 13, '"You are the salt of the earth, but if the salt has lost its flavor, with what will it be salted? It is then good for nothing, but to be cast out and trodden under the feet of men.'),
  ('b7deea08-0ee5-5b74-a037-48d845264f5f', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 14, 14, 'You are the light of the world. A city located on a hill can''t be hidden.'),
  ('bd8e2d39-c804-5c25-a7cd-563c07857e0c', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 15, 15, 'Neither do you light a lamp, and put it under a measuring basket, but on a stand; and it shines to all who are in the house.'),
  ('a6116c5a-42ee-5102-a2bb-26a265a9284f', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 16, 16, 'Even so, let your light shine before men; that they may see your good works, and glorify your Father who is in heaven.'),
  ('8c8e6070-0cc7-5a45-a490-48463f3bf8ad', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 17, 17, '"Don''t think that I came to destroy the law or the prophets. I didn''t come to destroy, but to fulfill.'),
  ('a4a15ec8-59dc-5a3a-a42c-a9b0082ebad6', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 18, 18, 'For most certainly, I tell you, until heaven and earth pass away, not even one smallest letter or one tiny pen stroke shall in any way pass away from the law, until all things are accomplished.'),
  ('aec94fd6-7b6d-5d90-a8b6-6126a0fd1538', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 19, 19, 'Whoever, therefore, shall break one of these least commandments, and teach others to do so, shall be called least in the Kingdom of Heaven; but whoever shall do and teach them shall be called great in the Kingdom of Heaven.'),
  ('28ac0b76-d21f-5952-a3b7-b1ecb8145c29', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 20, 20, 'For I tell you that unless your righteousness exceeds that of the scribes and Pharisees, there is no way you will enter into the Kingdom of Heaven.'),
  ('fb37405b-dbc6-52d4-a892-4c9c5137de7d', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 21, 21, '"You have heard that it was said to the ancient ones, ''You shall not murder;'' and ''Whoever shall murder shall be in danger of the judgment.'''),
  ('6933b2ec-5673-5004-acad-3b1e071f1932', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 22, 22, 'But I tell you, that everyone who is angry with his brother without a cause shall be in danger of the judgment; and whoever shall say to his brother, ''Raca!'' shall be in danger of the council; and whoever shall say, ''You fool!'' shall be in danger of the fire of Gehenna.'),
  ('a1fd9102-7e63-52e6-a31e-bab77a3c8cc6', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 23, 23, '"If therefore you are offering your gift at the altar, and there remember that your brother has anything against you,'),
  ('7151d315-4a27-5bd4-a110-2505a5018e14', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 24, 24, 'leave your gift there before the altar, and go your way. First be reconciled to your brother, and then come and offer your gift.'),
  ('b5124172-3843-5652-a2bd-790be8c697de', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 25, 25, 'Agree with your adversary quickly, while you are with him in the way; lest perhaps the prosecutor deliver you to the judge, and the judge deliver you to the officer, and you be cast into prison.'),
  ('093a2a7d-2200-5b73-acc3-f21ce5995d3d', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 26, 26, 'Most certainly I tell you, you shall by no means get out of there, until you have paid the last penny.'),
  ('ebe2b795-8556-5c47-a035-6262a4edf7bb', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 27, 27, '"You have heard that it was said, ''You shall not commit adultery;'''),
  ('7283421f-2ca2-5fda-a773-5b0b9997d7bd', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 28, 28, 'but I tell you that everyone who gazes at a woman to lust after her has committed adultery with her already in his heart.'),
  ('41ddb3b0-e792-5b66-a353-77224b17ce3d', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 29, 29, 'If your right eye causes you to stumble, pluck it out and throw it away from you. For it is more profitable for you that one of your members should perish, than for your whole body to be cast into Gehenna.'),
  ('3ccf7711-999c-5cd2-a30c-e0bc66e8efb5', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 30, 30, 'If your right hand causes you to stumble, cut it off, and throw it away from you. For it is more profitable for you that one of your members should perish, than for your whole body to be cast into Gehenna.'),
  ('0be1bd58-f482-53e4-a3aa-cf64806897a5', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 31, 31, '"It was also said, ''Whoever shall put away his wife, let him give her a writing of divorce,'''),
  ('cd47d67c-9ad5-585f-afc7-73824de05261', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 32, 32, 'but I tell you that whoever puts away his wife, except for the cause of sexual immorality, makes her an adulteress; and whoever marries her when she is put away commits adultery.'),
  ('ed327b05-8344-5e15-a388-b7523aca8f28', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 33, 33, '"Again you have heard that it was said to them of old time, ''You shall not make false vows, but shall perform to the Lord your vows,'''),
  ('47ba2f02-ea1b-5a4c-a931-58889350b9f2', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 34, 34, 'but I tell you, don''t swear at all: neither by heaven, for it is the throne of God;'),
  ('0a620e48-e7bd-5a5d-a007-2d08cea6eb16', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 35, 35, 'nor by the earth, for it is the footstool of his feet; nor by Jerusalem, for it is the city of the great King.'),
  ('6147825f-e287-5666-a696-59e484ab2437', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 36, 36, 'Neither shall you swear by your head, for you can''t make one hair white or black.'),
  ('75b7ae48-3d97-57a6-a25b-2c02f296caa1', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 37, 37, 'But let your ''Yes'' be ''Yes'' and your ''No'' be ''No.'' Whatever is more than these is of the evil one.'),
  ('d0b044db-38ce-5972-a93e-6159a1577f20', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 38, 38, '"You have heard that it was said, ''An eye for an eye, and a tooth for a tooth.'''),
  ('c642b3b5-cb83-5049-a08e-224722ae706e', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 39, 39, 'But I tell you, don''t resist him who is evil; but whoever strikes you on your right cheek, turn to him the other also.'),
  ('14f11c04-fb72-5ca2-a4a7-9272c90d14e4', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 40, 40, 'If anyone sues you to take away your coat, let him have your cloak also.'),
  ('50f1dd8c-5395-50c6-aef4-1a4c0c98c68b', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 41, 41, 'Whoever compels you to go one mile, go with him two.'),
  ('9218b9c3-cc7d-510f-a145-df24285725f6', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 42, 42, 'Give to him who asks you, and don''t turn away him who desires to borrow from you.'),
  ('63102736-9788-5eaa-ae83-3c7d35e036c8', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 43, 43, '"You have heard that it was said, ''You shall love your neighbor, and hate your enemy.'''),
  ('c765dcfa-cf11-52ec-a112-de5781d541d4', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 44, 44, 'But I tell you, love your enemies, bless those who curse you, do good to those who hate you, and pray for those who mistreat you and persecute you,'),
  ('98d45e07-c571-5021-a572-90b87d62a01d', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 45, 45, 'that you may be children of your Father who is in heaven. For he makes his sun to rise on the evil and the good, and sends rain on the just and the unjust.'),
  ('48878801-4580-5321-a1b7-19dd6de0e3c4', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 46, 46, 'For if you love those who love you, what reward do you have? Don''t even the tax collectors do the same?'),
  ('24b4ed77-71bf-5d45-a31f-33af117570c8', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 47, 47, 'If you only greet your friends, what more do you do than others? Don''t even the tax collectors do the same?'),
  ('8fa02c10-d286-5290-a6bb-2e2e7668a637', '9e429f61-eccf-543b-adf7-16dae0ce71cf', NULL, 48, 48, 'Therefore you shall be perfect, just as your Father in heaven is perfect.'),
  ('71ef5946-75f3-529a-a177-320331381651', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 1, 1, '"Be careful that you don''t do your charitable giving before men, to be seen by them, or else you have no reward from your Father who is in heaven.'),
  ('e76dac7b-3ca4-5ae3-a3e8-6ddf08d92663', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 2, 2, 'Therefore when you do merciful deeds, don''t sound a trumpet before yourself, as the hypocrites do in the synagogues and in the streets, that they may get glory from men. Most certainly I tell you, they have received their reward.'),
  ('84522d85-1814-5b3b-a4b6-5a15fd7b0ca6', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 3, 3, 'But when you do merciful deeds, don''t let your left hand know what your right hand does,'),
  ('0939fbb4-07c5-525f-a089-894c94602e1c', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 4, 4, 'so that your merciful deeds may be in secret, then your Father who sees in secret will reward you openly.'),
  ('cc08b6a5-9dce-5fd6-a35e-f58f2f64fe5f', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 5, 5, '"When you pray, you shall not be as the hypocrites, for they love to stand and pray in the synagogues and in the corners of the streets, that they may be seen by men. Most certainly, I tell you, they have received their reward.'),
  ('af9b0c8a-990a-56fb-aeda-df669133dc7f', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 6, 6, 'But you, when you pray, enter into your inner room, and having shut your door, pray to your Father who is in secret, and your Father who sees in secret will reward you openly.'),
  ('e4eb9972-7824-5a06-a1f8-3f44ecfbc351', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 7, 7, 'In praying, don''t use vain repetitions, as the Gentiles do; for they think that they will be heard for their much speaking.'),
  ('e9e058d3-3c95-5697-a863-2ac5993265cf', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 8, 8, 'Therefore don''t be like them, for your Father knows what things you need, before you ask him.'),
  ('e2a7903a-6fd5-55b9-a997-89ae99ed2c44', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 9, 9, 'Pray like this: ''Our Father in heaven, may your name be kept holy.'),
  ('c6e34e0a-8f7e-5269-aeb1-5b73b0899877', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 10, 10, 'Let your Kingdom come. Let your will be done, as in heaven, so on earth.'),
  ('d6057e27-08b9-53bb-a424-ea50a8febb8f', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 11, 11, 'Give us today our daily bread.'),
  ('542d7c81-f40b-5f63-a305-aabf9ff6aa9c', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 12, 12, 'Forgive us our debts, as we also forgive our debtors.'),
  ('b31ef22a-f4b9-52f2-ae77-6f4e3596348e', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 13, 13, 'Bring us not into temptation, but deliver us from the evil one. For yours is the Kingdom, the power, and the glory forever. Amen.'''),
  ('8018a524-36c9-517a-a89c-4784d78a7e39', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 14, 14, '"For if you forgive men their trespasses, your heavenly Father will also forgive you.'),
  ('7cdb75ab-a025-5b9d-a32b-c09ab5876f03', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 15, 15, 'But if you don''t forgive men their trespasses, neither will your Father forgive your trespasses.'),
  ('f06d58e6-fa27-51bd-a6e4-b4b09dc85b68', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 16, 16, '"Moreover when you fast, don''t be like the hypocrites, with sad faces. For they disfigure their faces, that they may be seen by men to be fasting. Most certainly I tell you, they have received their reward.'),
  ('a1a9d061-b068-5fd2-a993-93b6abff01cd', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 17, 17, 'But you, when you fast, anoint your head, and wash your face;'),
  ('35f107b8-113d-5184-a40f-c05f002425a4', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 18, 18, 'so that you are not seen by men to be fasting, but by your Father who is in secret, and your Father, who sees in secret, will reward you.'),
  ('681cd973-933f-5711-aec1-03dbaad00821', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 19, 19, '"Don''t lay up treasures for yourselves on the earth, where moth and rust consume, and where thieves break through and steal;'),
  ('80e54639-f819-5d34-abfa-80584e5927c6', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 20, 20, 'but lay up for yourselves treasures in heaven, where neither moth nor rust consume, and where thieves don''t break through and steal;'),
  ('f4c5d0a2-315b-52be-adeb-b7da2e303a36', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 21, 21, 'for where your treasure is, there your heart will be also.'),
  ('4fc6320b-740e-573e-ad01-507a6bdb9d9b', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 22, 22, '"The lamp of the body is the eye. If therefore your eye is sound, your whole body will be full of light.'),
  ('c1119a04-7935-5c9b-a7d1-c7f5822aa64e', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 23, 23, 'But if your eye is evil, your whole body will be full of darkness. If therefore the light that is in you is darkness, how great is the darkness!'),
  ('715cc399-b790-58b6-a1be-70a04c0f0ca1', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 24, 24, '"No one can serve two masters, for either he will hate the one and love the other; or else he will be devoted to one and despise the other. You can''t serve both God and Mammon.'),
  ('8446f3f9-0b1b-5317-a635-b6e1141ad4ce', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 25, 25, 'Therefore, I tell you, don''t be anxious for your life: what you will eat, or what you will drink; nor yet for your body, what you will wear. Isn''t life more than food, and the body more than clothing?'),
  ('666d46f1-2e60-5f02-a270-ebddbf8710ad', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 26, 26, 'See the birds of the sky, that they don''t sow, neither do they reap, nor gather into barns. Your heavenly Father feeds them. Aren''t you of much more value than they?'),
  ('d81658f1-cb70-58c5-a526-a9a2f60f87e0', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 27, 27, '"Which of you, by being anxious, can add one moment to his lifespan?'),
  ('f7105755-aac3-5129-aefd-8b6a149f5531', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 28, 28, 'Why are you anxious about clothing? Consider the lilies of the field, how they grow. They don''t toil, neither do they spin,'),
  ('a18a0154-5c74-5d8f-a483-97eda04159fd', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 29, 29, 'yet I tell you that even Solomon in all his glory was not dressed like one of these.'),
  ('68e90cab-b8fc-533f-a00c-b8206f8f7007', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 30, 30, 'But if God so clothes the grass of the field, which today exists, and tomorrow is thrown into the oven, won''t he much more clothe you, you of little faith?'),
  ('7071ea2e-5c50-50c2-a6ad-1b143890a3f0', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 31, 31, '"Therefore don''t be anxious, saying, ''What will we eat?'', ''What will we drink?'' or, ''With what will we be clothed?'''),
  ('0c8abb00-1aa6-527c-a056-057d2e897b86', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 32, 32, 'For the Gentiles seek after all these things; for your heavenly Father knows that you need all these things.'),
  ('c7af9610-e524-56cb-ae20-3cae627558f2', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 33, 33, 'But seek first God''s Kingdom, and his righteousness; and all these things will be given to you as well.'),
  ('9ebdcc1a-d74d-5027-a973-5a38441c5d83', '0ff1d3bd-97f1-5701-abc0-15a0275623ca', NULL, 34, 34, 'Therefore don''t be anxious for tomorrow, for tomorrow will be anxious for itself. Each day''s own evil is sufficient.'),
  ('862ff342-4b37-5f0a-af28-7cc02a8b4f1d', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 1, 1, '"Don''t judge, so that you won''t be judged.'),
  ('e252c252-c36b-5791-a47d-08dea8c4b42f', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 2, 2, 'For with whatever judgment you judge, you will be judged; and with whatever measure you measure, it will be measured to you.'),
  ('0a03fbe2-ab55-557a-a026-fcf657aa2750', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 3, 3, 'Why do you see the speck that is in your brother''s eye, but don''t consider the beam that is in your own eye?'),
  ('21bd2aac-ee8b-5468-ac24-b9f640f60b2f', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 4, 4, 'Or how will you tell your brother, ''Let me remove the speck from your eye;'' and behold, the beam is in your own eye?'),
  ('9470e831-46a2-51cd-a711-d1fc7efb4aae', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 5, 5, 'You hypocrite! First remove the beam out of your own eye, and then you can see clearly to remove the speck out of your brother''s eye.'),
  ('f9e0e63c-fc3d-5dca-a71a-b9ac526b21f3', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 6, 6, '"Don''t give that which is holy to the dogs, neither throw your pearls before the pigs, lest perhaps they trample them under their feet, and turn and tear you to pieces.'),
  ('c565be61-835a-5da2-ae22-2b9d1986e127', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 7, 7, '"Ask, and it will be given you. Seek, and you will find. Knock, and it will be opened for you.'),
  ('9b703e7f-48be-5ab3-a34b-fbd9dcd388bc', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 8, 8, 'For everyone who asks receives. He who seeks finds. To him who knocks it will be opened.'),
  ('a3fc9472-13c3-5b17-a069-0fc586f09cb0', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 9, 9, 'Or who is there among you, who, if his son asks him for bread, will give him a stone?'),
  ('2da288d9-97a6-56a9-a173-91bdee2dac9c', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 10, 10, 'Or if he asks for a fish, who will give him a serpent?'),
  ('2e99b2d6-8776-52de-a9ea-d5af55ab1081', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 11, 11, 'If you then, being evil, know how to give good gifts to your children, how much more will your Father who is in heaven give good things to those who ask him!'),
  ('03bb401b-d6e6-5659-ace3-74fee536abdb', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 12, 12, 'Therefore whatever you desire for men to do to you, you shall also do to them; for this is the law and the prophets.'),
  ('8c4e720f-3e53-5f7b-a4ee-e6d468de2682', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 13, 13, '"Enter in by the narrow gate; for wide is the gate and broad is the way that leads to destruction, and many are those who enter in by it.'),
  ('945aee06-f839-5d62-a134-8e51e0939548', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 14, 14, 'How narrow is the gate, and restricted is the way that leads to life! Few are those who find it.'),
  ('c1f0f208-57b8-5e17-a46f-e9ef36b29c29', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 15, 15, '"Beware of false prophets, who come to you in sheep''s clothing, but inwardly are ravening wolves.'),
  ('89fab3f7-4309-52a6-a829-2efe6f70b99e', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 16, 16, 'By their fruits you will know them. Do you gather grapes from thorns, or figs from thistles?'),
  ('5ce81ce3-2078-55d1-ae9f-81e7b171e000', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 17, 17, 'Even so, every good tree produces good fruit; but the corrupt tree produces evil fruit.'),
  ('2a152577-72ba-5789-a302-307c93f44d01', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 18, 18, 'A good tree can''t produce evil fruit, neither can a corrupt tree produce good fruit.'),
  ('abae437f-a3b9-5032-afba-22a4f8ee77f5', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 19, 19, 'Every tree that doesn''t grow good fruit is cut down, and thrown into the fire.'),
  ('1a9302ec-92c1-5bc1-ac72-4cb30a03bd07', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 20, 20, 'Therefore, by their fruits you will know them.'),
  ('7bedf844-fa00-5528-a6d5-ee3f8cdb0f35', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 21, 21, 'Not everyone who says to me, ''Lord, Lord,'' will enter into the Kingdom of Heaven; but he who does the will of my Father who is in heaven.'),
  ('c72083be-6bad-5a16-abf2-1c127c82f667', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 22, 22, 'Many will tell me in that day, ''Lord, Lord, didn''t we prophesy in your name, in your name cast out demons, and in your name do many mighty works?'''),
  ('026f42c5-421c-50ff-a9eb-3a10f4883d30', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 23, 23, 'Then I will tell them, ''I never knew you. Depart from me, you who work iniquity.'''),
  ('59691893-8a78-5bd0-a9c5-b12ca1a9bcf6', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 24, 24, '"Everyone therefore who hears these words of mine, and does them, I will liken him to a wise man, who built his house on a rock.'),
  ('f682ff2c-4300-583e-ac8e-77cb2f4d6606', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 25, 25, 'The rain came down, the floods came, and the winds blew, and beat on that house; and it didn''t fall, for it was founded on the rock.'),
  ('7bd86a37-4841-5eba-ae8a-f85723d0a5ad', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 26, 26, 'Everyone who hears these words of mine, and doesn''t do them will be like a foolish man, who built his house on the sand.'),
  ('ad9a308a-493d-5678-a7eb-3c8d3ce32499', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 27, 27, 'The rain came down, the floods came, and the winds blew, and beat on that house; and it fell--and great was its fall."'),
  ('05b926db-faf0-51ff-ad61-a73aa10509a5', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 28, 28, 'It happened, when Jesus had finished saying these things, that the multitudes were astonished at his teaching,'),
  ('bb9eef19-34ea-525b-ae05-28980f7f6437', '4596fb73-ca8b-5672-aef3-0a09d2e4a06d', NULL, 29, 29, 'for he taught them with authority, and not like the scribes.'),
  ('df50cb7b-44df-5900-a9ae-a9aee0479d34', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 1, 1, 'When he came down from the mountain, great multitudes followed him.'),
  ('4b4f39a9-7757-513f-a5c3-bf8d37e1e1f9', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 2, 2, 'Behold, a leper came to him and worshiped him, saying, "Lord, if you want to, you can make me clean."'),
  ('0ebfae1e-48c0-58de-ad92-16863996d995', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 3, 3, 'Jesus stretched out his hand, and touched him, saying, "I want to. Be made clean." Immediately his leprosy was cleansed.'),
  ('13cc1af0-1ccd-5572-a638-795950b70c2f', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 4, 4, 'Jesus said to him, "See that you tell nobody, but go, show yourself to the priest, and offer the gift that Moses commanded, as a testimony to them."'),
  ('a0fca2aa-8aa5-51c4-a949-8f412ebd6d3e', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 5, 5, 'When he came into Capernaum, a centurion came to him, asking him,'),
  ('a01e93f4-722e-5fe9-a201-b0c7fc5c1e52', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 6, 6, 'and saying, "Lord, my servant lies in the house paralyzed, grievously tormented."'),
  ('8163d91a-4b72-56ac-a02a-ff3b6021acad', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 7, 7, 'Jesus said to him, "I will come and heal him."'),
  ('a1ec3b5d-f021-5f7f-a744-a222b6b96315', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 8, 8, 'The centurion answered, "Lord, I''m not worthy for you to come under my roof. Just say the word, and my servant will be healed.'),
  ('6ba2b359-dd29-5988-a6a3-26dea79e4332', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 9, 9, 'For I am also a man under authority, having under myself soldiers. I tell this one, ''Go,'' and he goes; and tell another, ''Come,'' and he comes; and tell my servant, ''Do this,'' and he does it."'),
  ('0abf3195-0b02-5e19-a6c9-28967f95b37f', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 10, 10, 'When Jesus heard it, he marveled, and said to those who followed, "Most certainly I tell you, I haven''t found so great a faith, not even in Israel.'),
  ('a52c176d-121f-5105-a99f-ca09d1f8bdc3', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 11, 11, 'I tell you that many will come from the east and the west, and will sit down with Abraham, Isaac, and Jacob in the Kingdom of Heaven,'),
  ('f476ebbd-fd95-552f-a502-ea2bb61a442c', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 12, 12, 'but the children of the Kingdom will be thrown out into the outer darkness. There will be weeping and gnashing of teeth."'),
  ('f5a7f674-df95-5cb9-ad3a-f46a99c29a8a', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 13, 13, 'Jesus said to the centurion, "Go your way. Let it be done for you as you have believed." His servant was healed in that hour.'),
  ('186fcfff-fa96-5739-a0fb-f4a24a266dcc', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 14, 14, 'When Jesus came into Peter''s house, he saw his wife''s mother lying sick with a fever.'),
  ('4766ca07-b09f-5710-aaa5-2b39d280a72c', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 15, 15, 'He touched her hand, and the fever left her. She got up and served him.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2060a049-39ec-5144-a9a0-77e76042ca4e', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 16, 16, 'When evening came, they brought to him many possessed with demons. He cast out the spirits with a word, and healed all who were sick;'),
  ('78bebf99-f18e-584c-a194-87c8f4abf32e', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 17, 17, 'that it might be fulfilled which was spoken through Isaiah the prophet, saying: "He took our infirmities, and bore our diseases."'),
  ('d8545a16-5056-5f40-a60e-9c28fe1767df', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 18, 18, 'Now when Jesus saw great multitudes around him, he gave the order to depart to the other side.'),
  ('c76cc760-c712-54c3-a0f9-2742452dd86e', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 19, 19, 'A scribe came, and said to him, "Teacher, I will follow you wherever you go."'),
  ('65774877-fa3b-5df7-ada1-fd3d6d976ae6', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 20, 20, 'Jesus said to him, "The foxes have holes, and the birds of the sky have nests, but the Son of Man has nowhere to lay his head."'),
  ('894e7d88-35be-582d-ade4-9124333ad933', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 21, 21, 'Another of his disciples said to him, "Lord, allow me first to go and bury my father."'),
  ('d9623f00-c7e9-5afd-ae51-48bdb1614af9', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 22, 22, 'But Jesus said to him, "Follow me, and leave the dead to bury their own dead."'),
  ('437ec615-4a73-5374-a612-8e30a6d62bbe', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 23, 23, 'When he got into a boat, his disciples followed him.'),
  ('d700dbfb-612c-56a9-a665-5561d44cfd62', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 24, 24, 'Behold, a violent storm came up on the sea, so much that the boat was covered with the waves, but he was asleep.'),
  ('01ac0fb2-df15-513b-ac67-b3fb0f3acaa7', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 25, 25, 'They came to him, and woke him up, saying, "Save us, Lord! We are dying!"'),
  ('ce7593dd-36a3-52d3-a374-49515cc27c95', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 26, 26, 'He said to them, "Why are you fearful, O you of little faith?" Then he got up, rebuked the wind and the sea, and there was a great calm.'),
  ('a5066699-6a44-50f7-a0bb-ef3a1dc7f7c6', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 27, 27, 'The men marveled, saying, "What kind of man is this, that even the wind and the sea obey him?"'),
  ('cf5355ce-fcf1-5fee-aa15-b614cb3c0772', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 28, 28, 'When he came to the other side, into the country of the Gergesenes, two people possessed by demons met him there, coming out of the tombs, exceedingly fierce, so that nobody could pass that way.'),
  ('baf1996d-8385-5fed-a497-614934bb5f55', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 29, 29, 'Behold, they cried out, saying, "What do we have to do with you, Jesus, Son of God? Have you come here to torment us before the time?"'),
  ('db4a5527-6e46-5c7b-a2d2-1abb9495a089', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 30, 30, 'Now there was a herd of many pigs feeding far away from them.'),
  ('425c1f4d-0e00-5ceb-a495-38ab9115fbf8', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 31, 31, 'The demons begged him, saying, "If you cast us out, permit us to go away into the herd of pigs."'),
  ('c4163b53-af48-52e0-a586-6270c4569d81', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 32, 32, 'He said to them, "Go!" They came out, and went into the herd of pigs: and behold, the whole herd of pigs rushed down the cliff into the sea, and died in the water.'),
  ('95daf965-f6e1-5d3b-a2cf-1f8b957feaa6', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 33, 33, 'Those who fed them fled, and went away into the city, and told everything, including what happened to those who were possessed with demons.'),
  ('19f2a68b-63e8-518a-ad47-0e5972ed5062', 'bc1f849e-41fc-58d7-a9e6-a5e928aec5a3', NULL, 34, 34, 'Behold, all the city came out to meet Jesus. When they saw him, they begged that he would depart from their borders.'),
  ('768b98a6-dab4-5833-a486-2db3246fa057', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 1, 1, 'He entered into a boat, and crossed over, and came into his own city.'),
  ('2a8ec7cd-027d-5ba9-ae65-d77cb9438d8e', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 2, 2, 'Behold, they brought to him a man who was paralyzed, lying on a bed. Jesus, seeing their faith, said to the paralytic, "Son, cheer up! Your sins are forgiven you."'),
  ('d4044d4b-5bfd-5226-a650-3f4bb5321baf', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 3, 3, 'Behold, some of the scribes said to themselves, "This man blasphemes."'),
  ('019709ab-8fbc-5773-a69f-44d275d023c8', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 4, 4, 'Jesus, knowing their thoughts, said, "Why do you think evil in your hearts?'),
  ('02a1010d-c867-5ea8-a2ce-244d6ef34499', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 5, 5, 'For which is easier, to say, ''Your sins are forgiven;'' or to say, ''Get up, and walk?'''),
  ('b640a000-b540-5646-a097-cdeaa9477125', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 6, 6, 'But that you may know that the Son of Man has authority on earth to forgive sins..." (then he said to the paralytic), "Get up, and take up your mat, and go up to your house."'),
  ('be86971b-4a60-5ba5-a121-cd0683c37367', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 7, 7, 'He arose and departed to his house.'),
  ('abee9bc9-589f-59c9-a6d3-07535e74c217', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 8, 8, 'But when the multitudes saw it, they marveled and glorified God, who had given such authority to men.'),
  ('988c9538-0880-5112-a4c9-b74b9e52d77d', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 9, 9, 'As Jesus passed by from there, he saw a man called Matthew sitting at the tax collection office. He said to him, "Follow me." He got up and followed him.'),
  ('ee53f9f3-1b03-58ac-a578-075497900d46', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 10, 10, 'It happened as he sat in the house, behold, many tax collectors and sinners came and sat down with Jesus and his disciples.'),
  ('a02edec4-c013-5d64-a055-bf9b2c03263d', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 11, 11, 'When the Pharisees saw it, they said to his disciples, "Why does your teacher eat with tax collectors and sinners?"'),
  ('85e97e89-1679-5181-a9ff-29e6fbe6af42', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 12, 12, 'When Jesus heard it, he said to them, "Those who are healthy have no need for a physician, but those who are sick do.'),
  ('d5f82d0d-4c2f-56a1-a2b5-4beedace224d', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 13, 13, 'But you go and learn what this means: ''I desire mercy, and not sacrifice,'' for I came not to call the righteous, but sinners to repentance."'),
  ('c281673c-0fe1-5cff-a7db-d338a03ef545', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 14, 14, 'Then John''s disciples came to him, saying, "Why do we and the Pharisees fast often, but your disciples don''t fast?"'),
  ('5969a81e-295e-5de1-a806-fe733100b117', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 15, 15, 'Jesus said to them, "Can the friends of the bridegroom mourn, as long as the bridegroom is with them? But the days will come when the bridegroom will be taken away from them, and then they will fast.'),
  ('8a832193-ba47-51f2-ad56-a246ac64b005', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 16, 16, 'No one puts a piece of unshrunk cloth on an old garment; for the patch would tear away from the garment, and a worse hole is made.'),
  ('91898378-a595-5277-a019-0530faeb1d2a', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 17, 17, 'Neither do people put new wine into old wineskins, or else the skins would burst, and the wine be spilled, and the skins ruined. No, they put new wine into fresh wineskins, and both are preserved."'),
  ('b3824343-0273-52ba-a587-4f1da99da3d2', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 18, 18, 'While he told these things to them, behold, a ruler came and worshiped him, saying, "My daughter has just died, but come and lay your hand on her, and she will live."'),
  ('6ce68e86-3483-583a-a917-141fcb4577d3', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 19, 19, 'Jesus got up and followed him, as did his disciples.'),
  ('84522eaa-9344-5bb8-a497-5032ca5b3817', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 20, 20, 'Behold, a woman who had an issue of blood for twelve years came behind him, and touched the fringe of his garment;'),
  ('26791e86-ddae-561a-a661-3d955fbce0de', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 21, 21, 'for she said within herself, "If I just touch his garment, I will be made well."'),
  ('eda45405-e75c-5cc0-ae94-899f3ad43cfd', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 22, 22, 'But Jesus, turning around and seeing her, said, "Daughter, cheer up! Your faith has made you well." And the woman was made well from that hour.'),
  ('ab4c7c23-f6f1-5d4a-aacd-a4a74d762b79', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 23, 23, 'When Jesus came into the ruler''s house, and saw the flute players, and the crowd in noisy disorder,'),
  ('a4b3c87d-9cfa-50a5-a50f-ce47f3f2bec7', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 24, 24, 'he said to them, "Make room, because the girl isn''t dead, but sleeping." They were ridiculing him.'),
  ('c503cad0-a5f5-5d32-aa31-84b3d166826a', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 25, 25, 'But when the crowd was put out, he entered in, took her by the hand, and the girl arose.'),
  ('6a95fbe5-3ef5-5007-a1f6-0db7b8f31a05', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 26, 26, 'The report of this went out into all that land.'),
  ('e979acd4-a139-52af-a1fe-88405467e62b', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 27, 27, 'As Jesus passed by from there, two blind men followed him, calling out and saying, "Have mercy on us, son of David!"'),
  ('f3daeafa-6a51-5a96-a7af-2c383575084a', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 28, 28, 'When he had come into the house, the blind men came to him. Jesus said to them, "Do you believe that I am able to do this?" They told him, "Yes, Lord."'),
  ('2c7f5770-6fa7-574e-aaa7-b9b262fb18a4', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 29, 29, 'Then he touched their eyes, saying, "According to your faith be it done to you."'),
  ('935917c3-8323-59cd-a682-0e52afcbd310', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 30, 30, 'Their eyes were opened. Jesus strictly commanded them, saying, "See that no one knows about this."'),
  ('6537ec3f-2a1c-56c3-acb8-604d50952f48', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 31, 31, 'But they went out and spread abroad his fame in all that land.'),
  ('f2838709-482c-5f76-aeae-4fc51c3302a6', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 32, 32, 'As they went out, behold, a mute man who was demon possessed was brought to him.'),
  ('c3ea2b3d-24c8-55c0-aea9-c15ef7bd2da4', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 33, 33, 'When the demon was cast out, the mute man spoke. The multitudes marveled, saying, "Nothing like this has ever been seen in Israel!"'),
  ('226165fe-64d0-51ad-a162-116f46bd850f', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 34, 34, 'But the Pharisees said, "By the prince of the demons, he casts out demons."'),
  ('89aa866b-42f5-5b59-ab86-18d565d21c31', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 35, 35, 'Jesus went about all the cities and the villages, teaching in their synagogues, and preaching the Good News of the Kingdom, and healing every disease and every sickness among the people.'),
  ('749c3cfa-6f8f-5bb9-a6d7-6e7da3ab205b', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 36, 36, 'But when he saw the multitudes, he was moved with compassion for them, because they were harassed and scattered, like sheep without a shepherd.'),
  ('5c39d57f-16d8-5955-a636-a74cb6835fdf', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 37, 37, 'Then he said to his disciples, "The harvest indeed is plentiful, but the laborers are few.'),
  ('d0136abb-f720-5466-a115-be47a2b0cfd2', 'd87f529e-9b13-5208-a03b-84532c1e865e', NULL, 38, 38, 'Pray therefore that the Lord of the harvest will send out laborers into his harvest."'),
  ('29a40943-ed9c-5552-ae45-293f1e30142c', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 1, 1, 'He called to himself his twelve disciples, and gave them authority over unclean spirits, to cast them out, and to heal every disease and every sickness.'),
  ('e11f19ed-4370-5675-a0f1-687d9ad2c88f', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 2, 2, 'Now the names of the twelve apostles are these. The first, Simon, who is called Peter; Andrew, his brother; James the son of Zebedee; John, his brother;'),
  ('65f9c90f-8e3f-503c-a46b-2bd352adcb15', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 3, 3, 'Philip; Bartholomew; Thomas; Matthew the tax collector; James the son of Alphaeus; Lebbaeus, whose surname was Thaddaeus;'),
  ('44274cfa-f1f4-52b7-ae6d-c1cde6f4a619', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 4, 4, 'Simon the Canaanite; and Judas Iscariot, who also betrayed him.'),
  ('7fec2850-44a1-5764-a835-2bede119debd', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 5, 5, 'Jesus sent these twelve out, and commanded them, saying, "Don''t go among the Gentiles, and don''t enter into any city of the Samaritans.'),
  ('bb61e68e-3073-50a4-a459-d985760a472a', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 6, 6, 'Rather, go to the lost sheep of the house of Israel.'),
  ('3facf8c6-6b5c-5c7b-a628-3e1984221637', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 7, 7, 'As you go, preach, saying, ''The Kingdom of Heaven is at hand!'''),
  ('468db543-a68e-57dd-a280-08cd79fb3559', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 8, 8, 'Heal the sick, cleanse the lepers, and cast out demons. Freely you received, so freely give.'),
  ('a28ac264-922f-59fd-aa2a-9ece11aa20c5', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 9, 9, 'Don''t take any gold, nor silver, nor brass in your money belts.'),
  ('732470fc-7638-5bf3-a562-b8766d08f30a', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 10, 10, 'Take no bag for your journey, neither two coats, nor shoes, nor staff: for the laborer is worthy of his food.'),
  ('b268e467-4c5e-50db-a144-55f4a0a6bbc2', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 11, 11, 'Into whatever city or village you enter, find out who in it is worthy; and stay there until you go on.'),
  ('53a67e44-b6c4-5f3d-a7eb-ad5eb5e059c6', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 12, 12, 'As you enter into the household, greet it.'),
  ('296cdc93-310b-5cba-a1f8-7a79d62de9be', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 13, 13, 'If the household is worthy, let your peace come on it, but if it isn''t worthy, let your peace return to you.'),
  ('3a430d0f-0443-5505-a068-dc2e757a5e92', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 14, 14, 'Whoever doesn''t receive you, nor hear your words, as you go out of that house or that city, shake off the dust from your feet.'),
  ('588ab72f-d016-52b9-afbf-c5e533c76dcb', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 15, 15, 'Most certainly I tell you, it will be more tolerable for the land of Sodom and Gomorrah in the day of judgment than for that city.'),
  ('920391c9-62d3-5852-a535-af6744184f78', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 16, 16, '"Behold, I send you out as sheep in the midst of wolves. Therefore be wise as serpents, and harmless as doves.'),
  ('b26ee5c3-91a7-57cb-ac56-d8ccc0b006b0', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 17, 17, 'But beware of men: for they will deliver you up to councils, and in their synagogues they will scourge you.'),
  ('8a5c40f2-1bd5-55a1-a5e2-6bb1381cbfb2', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 18, 18, 'Yes, and you will be brought before governors and kings for my sake, for a testimony to them and to the nations.'),
  ('9b52cb40-f15b-5be0-a0d3-08209929691d', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 19, 19, 'But when they deliver you up, don''t be anxious how or what you will say, for it will be given you in that hour what you will say.'),
  ('fbf01f67-a484-5eb5-a0d6-32af07ca8bcf', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 20, 20, 'For it is not you who speak, but the Spirit of your Father who speaks in you.'),
  ('d03fc4be-bdac-5f1c-a5a2-e24dfc5e3002', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 21, 21, '"Brother will deliver up brother to death, and the father his child. Children will rise up against parents, and cause them to be put to death.'),
  ('1ce6e282-d067-5225-ab7b-c4cfb39ed068', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 22, 22, 'You will be hated by all men for my name''s sake, but he who endures to the end will be saved.'),
  ('1d3e174c-f78f-5281-a62d-aaba4b082855', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 23, 23, 'But when they persecute you in this city, flee into the next, for most certainly I tell you, you will not have gone through the cities of Israel, until the Son of Man has come.'),
  ('32efb087-d7f3-53bb-a27a-b8db2ca5c531', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 24, 24, '"A disciple is not above his teacher, nor a servant above his lord.'),
  ('ae0501e9-4085-50bf-a2e1-6f1fc7f5703d', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 25, 25, 'It is enough for the disciple that he be like his teacher, and the servant like his lord. If they have called the master of the house Beelzebul, how much more those of his household!'),
  ('fd7e17f6-07e9-51eb-ae65-d1c9c1543044', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 26, 26, 'Therefore don''t be afraid of them, for there is nothing covered that will not be revealed; and hidden that will not be known.'),
  ('0bb9594f-bd69-51c4-a8e3-c371f6fdf2da', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 27, 27, 'What I tell you in the darkness, speak in the light; and what you hear whispered in the ear, proclaim on the housetops.'),
  ('e910ecaf-b834-51b1-ac01-36d94eb332d5', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 28, 28, 'Don''t be afraid of those who kill the body, but are not able to kill the soul. Rather, fear him who is able to destroy both soul and body in Gehenna.'),
  ('25194524-9f6e-5f95-a9a4-4069b193bb41', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 29, 29, '"Aren''t two sparrows sold for an assarion coin? Not one of them falls on the ground apart from your Father''s will,'),
  ('8f92b549-7e4e-56f0-aaeb-44c0c2c82934', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 30, 30, 'but the very hairs of your head are all numbered.'),
  ('1475a40a-3579-5b64-af9a-a4f55d1105ae', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 31, 31, 'Therefore don''t be afraid. You are of more value than many sparrows.'),
  ('ae9a591d-0b3f-58d3-a507-bc74bcd2e645', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 32, 32, 'Everyone therefore who confesses me before men, him I will also confess before my Father who is in heaven.'),
  ('c4045284-5063-55d3-aa3c-9b3019ee237c', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 33, 33, 'But whoever denies me before men, him I will also deny before my Father who is in heaven.'),
  ('fc37f703-2fbb-5396-ae84-08cbaac576dc', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 34, 34, '"Don''t think that I came to send peace on the earth. I didn''t come to send peace, but a sword.'),
  ('ca94d1cf-dad3-5c5a-a349-b9fdf75aba2e', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 35, 35, 'For I came to set a man at odds against his father, and a daughter against her mother, and a daughter-in-law against her mother-in-law.'),
  ('732853cb-4102-5aa4-a57d-0c3d47172d99', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 36, 36, 'A man''s foes will be those of his own household.'),
  ('054286e7-534a-5f32-a81d-dce3b2d1dfbf', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 37, 37, 'He who loves father or mother more than me is not worthy of me; and he who loves son or daughter more than me isn''t worthy of me.'),
  ('d0717d39-880e-5f00-abe6-766e9f18c6d4', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 38, 38, 'He who doesn''t take his cross and follow after me, isn''t worthy of me.'),
  ('1ce8477a-46e2-5e09-a0c7-bfc304b68609', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 39, 39, 'He who seeks his life will lose it; and he who loses his life for my sake will find it.'),
  ('a349240c-7eda-5d54-a923-8a0057cf775a', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 40, 40, 'He who receives you receives me, and he who receives me receives him who sent me.'),
  ('62a48cc2-77ad-5b9e-adde-979349330fb3', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 41, 41, 'He who receives a prophet in the name of a prophet will receive a prophet''s reward. He who receives a righteous man in the name of a righteous man will receive a righteous man''s reward.'),
  ('6be25b05-fc06-59d3-a6ae-5c353250d6db', '988a8319-4ef2-5ae6-ad77-53ea787459d1', NULL, 42, 42, 'Whoever gives one of these little ones just a cup of cold water to drink in the name of a disciple, most certainly I tell you he will in no way lose his reward."'),
  ('c72feb78-3edc-5ed4-a9dd-fa96218911f2', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 1, 1, 'It happened that when Jesus had finished directing his twelve disciples, he departed from there to teach and preach in their cities.'),
  ('ba64b598-5bf6-5048-ac87-7a3e7e9ad517', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 2, 2, 'Now when John heard in the prison the works of Christ, he sent two of his disciples'),
  ('953c1fcc-a8d8-53c3-ad47-5bdfd6139112', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 3, 3, 'and said to him, "Are you he who comes, or should we look for another?"'),
  ('24b64482-2358-509f-a62c-ed6dd95d1d55', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 4, 4, 'Jesus answered them, "Go and tell John the things which you hear and see:'),
  ('b7f26cc5-dc40-5ad3-a960-15705973942b', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 5, 5, 'the blind receive their sight, the lame walk, the lepers are cleansed, the deaf hear, the dead are raised up, and the poor have good news preached to them.'),
  ('38a7f40c-6646-5af2-a998-97b651b6d60a', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 6, 6, 'Blessed is he who finds no occasion for stumbling in me."'),
  ('1e42d9c0-6d8e-517e-a3ca-6758a92951d6', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 7, 7, 'As these went their way, Jesus began to say to the multitudes concerning John, "What did you go out into the wilderness to see? A reed shaken by the wind?'),
  ('f1465426-ab84-5f4e-a296-979b434b476a', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 8, 8, 'But what did you go out to see? A man in soft clothing? Behold, those who wear soft clothing are in king''s houses.'),
  ('5b9f8f87-13ef-5e0c-a67c-a17f96afc665', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 9, 9, 'But why did you go out? To see a prophet? Yes, I tell you, and much more than a prophet.'),
  ('ae8abe1b-5323-57d5-a208-80de00885976', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 10, 10, 'For this is he, of whom it is written, ''Behold, I send my messenger before your face, who will prepare your way before you.'''),
  ('0215ac6b-09ac-55f6-ac9d-de68a7d76cbe', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 11, 11, 'Most certainly I tell you, among those who are born of women there has not arisen anyone greater than John the Baptizer; yet he who is least in the Kingdom of Heaven is greater than he.'),
  ('ea6761ce-b259-58e8-aa14-70c579bddef6', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 12, 12, 'From the days of John the Baptizer until now, the Kingdom of Heaven suffers violence, and the violent take it by force.'),
  ('b1f19714-0e17-5da7-a025-1951f9e16365', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 13, 13, 'For all the prophets and the law prophesied until John.'),
  ('176a8c62-1f03-5afc-a15e-de31278b7126', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 14, 14, 'If you are willing to receive it, this is Elijah, who is to come.'),
  ('c677c5f4-c016-5a71-a5d4-7ec3cc29e4d0', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 15, 15, 'He who has ears to hear, let him hear.'),
  ('1cd405bd-5415-5eee-a478-5965888a56b7', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 16, 16, '"But to what shall I compare this generation? It is like children sitting in the marketplaces, who call to their companions'),
  ('6f120b84-ccff-5344-a367-17a606cfb40b', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 17, 17, 'and say, ''We played the flute for you, and you didn''t dance. We mourned for you, and you didn''t lament.'''),
  ('b7ebf701-222a-554b-a0f0-620cce918765', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 18, 18, 'For John came neither eating nor drinking, and they say, ''He has a demon.'''),
  ('e17ce28b-2218-500d-a8de-3aa58517c551', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 19, 19, 'The Son of Man came eating and drinking, and they say, ''Behold, a gluttonous man and a drunkard, a friend of tax collectors and sinners!'' But wisdom is justified by her children."'),
  ('f8578f24-526d-5166-a380-5ce1bd23a113', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 20, 20, 'Then he began to denounce the cities in which most of his mighty works had been done, because they didn''t repent.'),
  ('2a575e53-bc97-5dbd-a837-7b45450ce5db', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 21, 21, '"Woe to you, Chorazin! Woe to you, Bethsaida! For if the mighty works had been done in Tyre and Sidon which were done in you, they would have repented long ago in sackcloth and ashes.'),
  ('f8a412f4-5abf-5c2e-a334-cd21c13d20bf', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 22, 22, 'But I tell you, it will be more tolerable for Tyre and Sidon on the day of judgment than for you.'),
  ('63f16e6b-1d8b-5da6-a0f3-ef586ddc573a', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 23, 23, 'You, Capernaum, who are exalted to heaven, you will go down to Hades. For if the mighty works had been done in Sodom which were done in you, it would have remained until this day.'),
  ('09365ec5-b869-51d1-a1ca-81e883cf3bab', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 24, 24, 'But I tell you that it will be more tolerable for the land of Sodom, on the day of judgment, than for you."'),
  ('5c2e6360-2244-545c-aba3-6516797dfdc0', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 25, 25, 'At that time, Jesus answered, "I thank you, Father, Lord of heaven and earth, that you hid these things from the wise and understanding, and revealed them to infants.'),
  ('8e992120-3dc9-59f9-a31d-d06d824a6b82', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 26, 26, 'Yes, Father, for so it was well-pleasing in your sight.'),
  ('0cf993bf-9023-53bb-aa5b-95bf3fd49ff3', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 27, 27, 'All things have been delivered to me by my Father. No one knows the Son, except the Father; neither does anyone know the Father, except the Son, and he to whom the Son desires to reveal him.'),
  ('94cd2c25-6643-5a16-a0e3-d33bc62fb86c', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 28, 28, '"Come to me, all you who labor and are heavily burdened, and I will give you rest.'),
  ('7e5e7e25-7264-5850-af6a-4dfa5fbe555f', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 29, 29, 'Take my yoke upon you, and learn from me, for I am gentle and lowly in heart; and you will find rest for your souls.'),
  ('c5a43933-e126-5422-ac07-7c3a6b73dc07', '01adb843-c7d3-5595-ac1a-de79f3cf4138', NULL, 30, 30, 'For my yoke is easy, and my burden is light."'),
  ('0031a2f2-3122-58c5-af26-ce72bc034f02', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 1, 1, 'At that time, Jesus went on the Sabbath day through the grain fields. His disciples were hungry and began to pluck heads of grain and to eat.'),
  ('ba5a0051-79b5-5ad3-a7aa-31b550c1f05e', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 2, 2, 'But the Pharisees, when they saw it, said to him, "Behold, your disciples do what is not lawful to do on the Sabbath."'),
  ('0803e778-aacc-5eb0-a144-49bdc30f3e9a', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 3, 3, 'But he said to them, "Haven''t you read what David did, when he was hungry, and those who were with him;'),
  ('73946fc4-5b2a-527c-ad71-d82cd9dfbc67', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 4, 4, 'how he entered into the house of God, and ate the show bread, which was not lawful for him to eat, neither for those who were with him, but only for the priests?'),
  ('49fc6188-5756-54e2-a740-a65dfa0ac86d', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 5, 5, 'Or have you not read in the law, that on the Sabbath day, the priests in the temple profane the Sabbath, and are guiltless?'),
  ('e446a510-71a5-5481-ab07-6c887fad6736', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 6, 6, 'But I tell you that one greater than the temple is here.'),
  ('81b40370-0b0b-50fb-acff-c0dc3040b8d5', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 7, 7, 'But if you had known what this means, ''I desire mercy, and not sacrifice,'' you would not have condemned the guiltless.'),
  ('546a9ac6-8f5b-5fe6-a7ab-3de1fa804ecf', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 8, 8, 'For the Son of Man is Lord of the Sabbath."'),
  ('48380d4a-5561-5f4b-a3c9-55848747f461', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 9, 9, 'He departed there, and went into their synagogue.'),
  ('e52412b3-98f1-597a-a537-a3d53d14921b', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 10, 10, 'And behold there was a man with a withered hand. They asked him, "Is it lawful to heal on the Sabbath day?" that they might accuse him.'),
  ('e3fb50d1-1cd3-58b8-ab91-b323b0226873', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 11, 11, 'He said to them, "What man is there among you, who has one sheep, and if this one falls into a pit on the Sabbath day, won''t he grab on to it, and lift it out?'),
  ('18c9cf47-6b55-55df-a0e6-de18189c1d4b', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 12, 12, 'Of how much more value then is a man than a sheep! Therefore it is lawful to do good on the Sabbath day."'),
  ('a278716e-a43f-5271-a817-f1e6314da8d5', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 13, 13, 'Then he told the man, "Stretch out your hand." He stretched it out; and it was restored whole, just like the other.'),
  ('82ea8612-fd73-53c0-a7fa-a5a67301be59', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 14, 14, 'But the Pharisees went out, and conspired against him, how they might destroy him.'),
  ('89bc9cca-eb04-5258-ae5b-263bad870a3d', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 15, 15, 'Jesus, perceiving that, withdrew from there. Great multitudes followed him; and he healed them all,'),
  ('f90912c8-0544-5d48-a79b-a084d1b00477', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 16, 16, 'and commanded them that they should not make him known:'),
  ('a1d15afe-f859-544e-aaa9-90341442206b', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 17, 17, 'that it might be fulfilled which was spoken through Isaiah the prophet, saying,'),
  ('4dc90574-54bb-5f50-ab2a-2d9add7df041', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 18, 18, '"Behold, my servant whom I have chosen; my beloved in whom my soul is well pleased: I will put my Spirit on him. He will proclaim justice to the nations.'),
  ('f5a11b88-2fe8-5662-a711-1622ab511406', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 19, 19, 'He will not strive, nor shout; neither will anyone hear his voice in the streets.'),
  ('adc577e2-8305-5546-ac04-3011103a3dcd', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 20, 20, 'He won''t break a bruised reed. He won''t quench a smoking flax, until he leads justice to victory.'),
  ('f2c313b4-783f-5eb9-a43f-2aabe38b9a19', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 21, 21, 'In his name, the nations will hope."'),
  ('b82db383-f6ec-52c9-a654-cd8e64711443', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 22, 22, 'Then one possessed by a demon, blind and mute, was brought to him and he healed him, so that the blind and mute man both spoke and saw.'),
  ('f4e23927-4acf-55ef-aae4-8e27a7d7ee07', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 23, 23, 'All the multitudes were amazed, and said, "Can this be the son of David?"'),
  ('ad9a57db-43ac-5442-a0fc-b16b644ba9d2', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 24, 24, 'But when the Pharisees heard it, they said, "This man does not cast out demons, except by Beelzebul, the prince of the demons."'),
  ('d8395328-7c7a-5162-a0de-24edd15ceff3', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 25, 25, 'Knowing their thoughts, Jesus said to them, "Every kingdom divided against itself is brought to desolation, and every city or house divided against itself will not stand.'),
  ('87c2e015-5e45-5dc0-a65a-1e4cb0c1bf4b', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 26, 26, 'If Satan casts out Satan, he is divided against himself. How then will his kingdom stand?'),
  ('9883f123-648f-5990-a175-436e068df457', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 27, 27, 'If I by Beelzebul cast out demons, by whom do your children cast them out? Therefore they will be your judges.'),
  ('ffe31e25-7ec5-5713-ad56-d9c9963539ed', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 28, 28, 'But if I by the Spirit of God cast out demons, then the Kingdom of God has come upon you.'),
  ('82cf3a02-ff5f-59a4-ad07-88cb289ebe99', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 29, 29, 'Or how can one enter into the house of the strong man, and plunder his goods, unless he first bind the strong man? Then he will plunder his house.'),
  ('0ca117e9-3c4d-5a76-a4b7-8f0598bc8cc3', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 30, 30, '"He who is not with me is against me, and he who doesn''t gather with me, scatters.'),
  ('4fe2faa8-f8f6-50b8-a431-bc852249e979', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 31, 31, 'Therefore I tell you, every sin and blasphemy will be forgiven men, but the blasphemy against the Spirit will not be forgiven men.'),
  ('5a72896c-f4e4-5aa6-a5cf-5f64ee90031f', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 32, 32, 'Whoever speaks a word against the Son of Man, it will be forgiven him; but whoever speaks against the Holy Spirit, it will not be forgiven him, neither in this age, nor in that which is to come.'),
  ('79e95155-885c-51ef-a377-a1567b20d092', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 33, 33, '"Either make the tree good, and its fruit good, or make the tree corrupt, and its fruit corrupt; for the tree is known by its fruit.'),
  ('e1a209fc-1679-56a2-a9c3-a38833e5981b', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 34, 34, 'You offspring of vipers, how can you, being evil, speak good things? For out of the abundance of the heart, the mouth speaks.'),
  ('b5b5b6b4-c679-5f5a-acb3-705053769e3a', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 35, 35, 'The good man out of his good treasure brings out good things, and the evil man out of his evil treasure brings out evil things.'),
  ('782e8896-e284-5d42-a925-bbadd3370c01', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 36, 36, 'I tell you that every idle word that men speak, they will give account of it in the day of judgment.'),
  ('98acff67-67a8-5f02-a640-db2cb51e0976', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 37, 37, 'For by your words you will be justified, and by your words you will be condemned."'),
  ('455d028f-b4c8-5363-ada6-b2a93491ca7c', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 38, 38, 'Then certain of the scribes and Pharisees answered, "Teacher, we want to see a sign from you."'),
  ('668a7cd6-31f5-5775-a45d-512e41a101e0', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 39, 39, 'But he answered them, "An evil and adulterous generation seeks after a sign, but no sign will be given it but the sign of Jonah the prophet.'),
  ('e9c06dee-4ace-5878-aa5e-8f4f340c98f8', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 40, 40, 'For as Jonah was three days and three nights in the belly of the whale, so will the Son of Man be three days and three nights in the heart of the earth.'),
  ('93cf9aaf-3f7f-50dc-a975-5bd0099dfa64', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 41, 41, 'The men of Nineveh will stand up in the judgment with this generation, and will condemn it, for they repented at the preaching of Jonah; and behold, someone greater than Jonah is here.'),
  ('edb40277-fdd5-555a-a710-d6f94601d713', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 42, 42, 'The queen of the south will rise up in the judgment with this generation, and will condemn it, for she came from the ends of the earth to hear the wisdom of Solomon; and behold, someone greater than Solomon is here.'),
  ('65b8d918-cc9c-5172-a78e-7930b0da6335', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 43, 43, 'But the unclean spirit, when he is gone out of the man, passes through waterless places, seeking rest, and doesn''t find it.'),
  ('ee4d3538-36bf-5fde-a0c8-b4bad0a31e39', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 44, 44, 'Then he says, ''I will return into my house from which I came out,'' and when he has come back, he finds it empty, swept, and put in order.'),
  ('94857cf8-f011-5b7b-af1d-eb94ad06674f', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 45, 45, 'Then he goes, and takes with himself seven other spirits more evil than he is, and they enter in and dwell there. The last state of that man becomes worse than the first. Even so will it be also to this evil generation."'),
  ('361053f6-3559-5921-a7b4-c37e78083189', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 46, 46, 'While he was yet speaking to the multitudes, behold, his mother and his brothers stood outside, seeking to speak to him.'),
  ('1fe548b8-873a-5c92-a588-69b7a34cca3b', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 47, 47, 'One said to him, "Behold, your mother and your brothers stand outside, seeking to speak to you."'),
  ('64bbd1de-92fb-5a9c-abd2-133aec90c542', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 48, 48, 'But he answered him who spoke to him, "Who is my mother? Who are my brothers?"'),
  ('3e930d97-fa09-583a-a3e6-bde4483dd693', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 49, 49, 'He stretched out his hand towards his disciples, and said, "Behold, my mother and my brothers!'),
  ('7ee15de2-41ce-53c9-ab3b-69d9c038fbdc', '70507d35-78bb-54e3-a806-dd3c64261ca2', NULL, 50, 50, 'For whoever does the will of my Father who is in heaven, he is my brother, and sister, and mother."'),
  ('cbc30e6c-e0eb-5cf9-a096-b39ede5bd33f', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 1, 1, 'On that day Jesus went out of the house, and sat by the seaside.'),
  ('70a9bcd9-5a47-5629-aa2c-61da86934b13', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 2, 2, 'Great multitudes gathered to him, so that he entered into a boat, and sat, and all the multitude stood on the beach.'),
  ('7bda0a53-ed5c-5ec7-a29a-ce7d8172cb6c', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 3, 3, 'He spoke to them many things in parables, saying, "Behold, a farmer went out to sow.'),
  ('3d83b449-1109-5e6b-adb0-aa9121d55edf', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 4, 4, 'As he sowed, some seeds fell by the roadside, and the birds came and devoured them.'),
  ('2969b8c3-2115-5dcf-aa4e-5206cd2686bc', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 5, 5, 'Others fell on rocky ground, where they didn''t have much soil, and immediately they sprang up, because they had no depth of earth.'),
  ('012e4f76-7eb7-58da-a028-94fa4e8eddbb', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 6, 6, 'When the sun had risen, they were scorched. Because they had no root, they withered away.'),
  ('f4ea818f-e20b-5a85-ad0f-f1d44088cbf4', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 7, 7, 'Others fell among thorns. The thorns grew up and choked them.'),
  ('0aeb30f3-ee2d-5492-ad41-6adede7d2e6c', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 8, 8, 'Others fell on good soil, and yielded fruit: some one hundred times as much, some sixty, and some thirty.'),
  ('43c4d9fe-0641-5ea2-a8cf-aa4af8e62756', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 9, 9, 'He who has ears to hear, let him hear."'),
  ('1dddffe0-7a5c-5097-aa60-be4e47e173ae', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 10, 10, 'The disciples came, and said to him, "Why do you speak to them in parables?"'),
  ('3e12e218-1b28-5573-a0a9-29ac99cd5023', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 11, 11, 'He answered them, "To you it is given to know the mysteries of the Kingdom of Heaven, but it is not given to them.'),
  ('bb4b81d4-02ed-542f-a47c-634087a93034', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 12, 12, 'For whoever has, to him will be given, and he will have abundance, but whoever doesn''t have, from him will be taken away even that which he has.'),
  ('65015ee5-2d61-5390-a4f3-0727f4b740c7', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 13, 13, 'Therefore I speak to them in parables, because seeing they don''t see, and hearing, they don''t hear, neither do they understand.'),
  ('8d92c926-bc80-5656-a073-c8d6ed599834', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 14, 14, 'In them the prophecy of Isaiah is fulfilled, which says, ''By hearing you will hear, and will in no way understand; Seeing you will see, and will in no way perceive:'),
  ('5b1c8696-6417-5ed9-af32-a102418a071b', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 15, 15, 'for this people''s heart has grown callous, their ears are dull of hearing, they have closed their eyes; or else perhaps they might perceive with their eyes, hear with their ears, understand with their heart, and should turn again; and I would heal them.'''),
  ('12df9f8d-7353-5438-ad81-b93e11cc6a30', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 16, 16, '"But blessed are your eyes, for they see; and your ears, for they hear.'),
  ('a97ae8bc-e511-5fc4-ad91-5391ac24e34b', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 17, 17, 'For most certainly I tell you that many prophets and righteous men desired to see the things which you see, and didn''t see them; and to hear the things which you hear, and didn''t hear them.'),
  ('9624ce61-a2d3-51e2-aa93-0ac48b355194', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 18, 18, '"Hear, then, the parable of the farmer.'),
  ('36211d43-78cf-5850-ac78-076c01887cc3', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 19, 19, 'When anyone hears the word of the Kingdom, and doesn''t understand it, the evil one comes, and snatches away that which has been sown in his heart. This is what was sown by the roadside.'),
  ('dc6d316c-97f8-5521-a8cb-3c033ad87bb6', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 20, 20, 'What was sown on the rocky places, this is he who hears the word, and immediately with joy receives it;'),
  ('d446e5ba-80d4-5e98-aedb-2b69dd0ee7a3', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 21, 21, 'yet he has no root in himself, but endures for a while. When oppression or persecution arises because of the word, immediately he stumbles.'),
  ('7c95108b-209f-579c-aab2-6d49c97fd8b3', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 22, 22, 'What was sown among the thorns, this is he who hears the word, but the cares of this age and the deceitfulness of riches choke the word, and he becomes unfruitful.'),
  ('dd4f1a30-5277-5962-a514-e2a2eb0ee1c6', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 23, 23, 'What was sown on the good ground, this is he who hears the word, and understands it, who most certainly bears fruit, and brings forth, some one hundred times as much, some sixty, and some thirty."'),
  ('e37b83c2-7b9a-53ab-abb3-7fa7c8c7240d', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 24, 24, 'He set another parable before them, saying, "The Kingdom of Heaven is like a man who sowed good seed in his field,'),
  ('571e05c7-4c85-5340-aba9-dab8ec43992e', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 25, 25, 'but while people slept, his enemy came and sowed darnel weeds also among the wheat, and went away.'),
  ('aeed2fca-8973-5b20-a439-4ed79cd2e555', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 26, 26, 'But when the blade sprang up and brought forth fruit, then the darnel weeds appeared also.'),
  ('eb0ca20e-936d-5d18-af88-920cabca4aa2', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 27, 27, 'The servants of the householder came and said to him, ''Sir, didn''t you sow good seed in your field? Where did this darnel come from?'''),
  ('89282cad-3d6b-51cb-ae5d-d4dd0de526f0', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 28, 28, '"He said to them, ''An enemy has done this.'' "The servants asked him, ''Do you want us to go and gather them up?'''),
  ('1353ff79-4811-5202-a9d6-1fd44adcb15c', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 29, 29, '"But he said, ''No, lest perhaps while you gather up the darnel weeds, you root up the wheat with them.'),
  ('a43715d0-246b-587d-a930-a0121cb49ef4', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 30, 30, 'Let both grow together until the harvest, and in the harvest time I will tell the reapers, "First, gather up the darnel weeds, and bind them in bundles to burn them; but gather the wheat into my barn."''"'),
  ('12ed6460-a8c1-5c01-a11a-1219d391c8cf', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 31, 31, 'He set another parable before them, saying, "The Kingdom of Heaven is like a grain of mustard seed, which a man took, and sowed in his field;'),
  ('8dd42a8f-e18e-5e71-af1a-0f60c3f33201', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 32, 32, 'which indeed is smaller than all seeds. But when it is grown, it is greater than the herbs, and becomes a tree, so that the birds of the air come and lodge in its branches."'),
  ('f28dc2ca-1089-5cda-a826-43df46db7e6c', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 33, 33, 'He spoke another parable to them. "The Kingdom of Heaven is like yeast, which a woman took, and hid in three measures of meal, until it was all leavened."'),
  ('f11410cc-5d36-5e02-a03f-b3c9072abf33', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 34, 34, 'Jesus spoke all these things in parables to the multitudes; and without a parable, he didn''t speak to them,'),
  ('f0f4b356-b12b-5820-a942-9c5344b9687c', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 35, 35, 'that it might be fulfilled which was spoken through the prophet, saying, "I will open my mouth in parables; I will utter things hidden from the foundation of the world."'),
  ('431f433a-ed5b-5d8f-a759-41a8da63af77', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 36, 36, 'Then Jesus sent the multitudes away, and went into the house. His disciples came to him, saying, "Explain to us the parable of the darnel weeds of the field."'),
  ('28e1ffdc-76ab-571f-a4bb-b25b1c265ce7', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 37, 37, 'He answered them, "He who sows the good seed is the Son of Man,'),
  ('070f73d5-291e-5da4-aa98-2116d4c063ec', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 38, 38, 'the field is the world; and the good seed, these are the children of the Kingdom; and the darnel weeds are the children of the evil one.'),
  ('4e266543-7532-55bb-ac2b-10d0938410ae', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 39, 39, 'The enemy who sowed them is the devil. The harvest is the end of the age, and the reapers are angels.'),
  ('b2806ab0-9eee-5a55-a8fd-afab86ee1c65', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 40, 40, 'As therefore the darnel weeds are gathered up and burned with fire; so will it be at the end of this age.'),
  ('b0af4890-7c69-59ba-ab6a-8def6ec70a7b', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 41, 41, 'The Son of Man will send out his angels, and they will gather out of his Kingdom all things that cause stumbling, and those who do iniquity,'),
  ('96aae55f-1111-517e-aa33-0be8875ffac4', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 42, 42, 'and will cast them into the furnace of fire. There will be weeping and the gnashing of teeth.'),
  ('f8c2cab9-a82e-5fa1-a3dc-6fdff2dfd075', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 43, 43, 'Then the righteous will shine forth like the sun in the Kingdom of their Father. He who has ears to hear, let him hear.'),
  ('98047e37-fe3d-5f5a-a56b-6d96e7677c2d', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 44, 44, '"Again, the Kingdom of Heaven is like a treasure hidden in the field, which a man found, and hid. In his joy, he goes and sells all that he has, and buys that field.'),
  ('4744cc6a-69ca-548c-a371-9384b928a3fe', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 45, 45, '"Again, the Kingdom of Heaven is like a man who is a merchant seeking fine pearls,'),
  ('7148c90e-c1e8-5ee4-a27f-ea75174bbac6', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 46, 46, 'who having found one pearl of great price, he went and sold all that he had, and bought it.'),
  ('d5b9cf67-fe45-5d83-aa7d-68ea49c18b57', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 47, 47, '"Again, the Kingdom of Heaven is like a dragnet, that was cast into the sea, and gathered some fish of every kind,'),
  ('0e66f386-2977-5f6f-a9e8-36b4ecf656eb', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 48, 48, 'which, when it was filled, they drew up on the beach. They sat down, and gathered the good into containers, but the bad they threw away.'),
  ('e968627d-acd8-54bb-af89-6c243381e616', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 49, 49, 'So will it be in the end of the world. The angels will come forth, and separate the wicked from among the righteous,'),
  ('c1c57136-7cdb-5511-a6c9-f2c2efda20c6', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 50, 50, 'and will cast them into the furnace of fire. There will be the weeping and the gnashing of teeth."'),
  ('cedd582e-9263-5eb2-a8bf-8c88a990066a', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 51, 51, 'Jesus said to them, "Have you understood all these things?" They answered him, "Yes, Lord."'),
  ('c0b52f4d-2b8c-5340-a534-0aa46b4e3f02', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 52, 52, 'He said to them, "Therefore, every scribe who has been made a disciple in the Kingdom of Heaven is like a man who is a householder, who brings out of his treasure new and old things."'),
  ('653126b1-838c-5a63-af60-5681227f1825', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 53, 53, 'It happened that when Jesus had finished these parables, he departed from there.'),
  ('554fc68a-6384-5c73-a49e-8a8b0db84c5a', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 54, 54, 'Coming into his own country, he taught them in their synagogue, so that they were astonished, and said, "Where did this man get this wisdom, and these mighty works?'),
  ('cd7086e0-a62b-5e2c-a14d-b86cacf4b3a8', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 55, 55, 'Isn''t this the carpenter''s son? Isn''t his mother called Mary, and his brothers, James, Joses, Simon, and Judas?'),
  ('308871aa-adfd-51c8-a27e-ce42dd7aca53', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 56, 56, 'Aren''t all of his sisters with us? Where then did this man get all of these things?"'),
  ('0a21fb65-3d54-5c79-a50f-8bb411ead571', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 57, 57, 'They were offended by him. But Jesus said to them, "A prophet is not without honor, except in his own country, and in his own house."'),
  ('ca4b55db-4ae5-5605-a2ed-5d1aaf720831', '4243cd1d-c67f-5a8e-a0c7-0c2a8a8b4516', NULL, 58, 58, 'He didn''t do many mighty works there because of their unbelief.'),
  ('b7cac3a4-9365-57c1-a308-7717d4660535', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 1, 1, 'At that time, Herod the tetrarch heard the report concerning Jesus,'),
  ('b80c79a4-b945-5f79-a00b-dfcdb2a0428c', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 2, 2, 'and said to his servants, "This is John the Baptizer. He is risen from the dead. That is why these powers work in him."'),
  ('c499d1e8-bea4-508b-aeac-c2ee9bef61ae', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 3, 3, 'For Herod had laid hold of John, and bound him, and put him in prison for the sake of Herodias, his brother Philip''s wife.'),
  ('4589000c-b5bb-521a-a1df-79e8e15cbdc9', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 4, 4, 'For John said to him, "It is not lawful for you to have her."'),
  ('a03660ee-a3ee-5c0f-a207-e65459359f9d', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 5, 5, 'When he would have put him to death, he feared the multitude, because they counted him as a prophet.'),
  ('7fe7367f-d3db-5995-ac1d-e287ff61da57', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 6, 6, 'But when Herod''s birthday came, the daughter of Herodias danced among them and pleased Herod.'),
  ('003bf198-4254-5399-adc5-8bde007bcff8', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 7, 7, 'Whereupon he promised with an oath to give her whatever she should ask.'),
  ('dcdf2c25-97d4-57ef-a9bc-d844ae6910ff', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 8, 8, 'She, being prompted by her mother, said, "Give me here on a platter the head of John the Baptizer."'),
  ('d442c60a-4cd5-53d1-a7d6-4123b7b6a9d5', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 9, 9, 'The king was grieved, but for the sake of his oaths, and of those who sat at the table with him, he commanded it to be given,'),
  ('01155ab8-e9ea-5e09-a492-d5aff8dd46ab', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 10, 10, 'and he sent and beheaded John in the prison.'),
  ('786a460d-e914-519a-a7d5-3ef3788c46ad', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 11, 11, 'His head was brought on a platter, and given to the young lady: and she brought it to her mother.'),
  ('3988a331-5655-52ba-ad98-aaf7614767ff', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 12, 12, 'His disciples came, and took the body, and buried it; and they went and told Jesus.'),
  ('7342b055-4daa-586b-a33e-7ba08bc42890', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 13, 13, 'Now when Jesus heard this, he withdrew from there in a boat, to a deserted place apart. When the multitudes heard it, they followed him on foot from the cities.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('9131077d-416b-5d1a-aa4e-fc93378dff02', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 14, 14, 'Jesus went out, and he saw a great multitude. He had compassion on them, and healed their sick.'),
  ('e4c1b766-40a3-5f06-a5fa-77228901ac44', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 15, 15, 'When evening had come, his disciples came to him, saying, "This place is deserted, and the hour is already late. Send the multitudes away, that they may go into the villages, and buy themselves food."'),
  ('90940df7-8b8a-5793-a44b-e5d0c24ac327', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 16, 16, 'But Jesus said to them, "They don''t need to go away. You give them something to eat."'),
  ('1cc56e21-daf1-5eee-a7ba-bc9508e6b2f6', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 17, 17, 'They told him, "We only have here five loaves and two fish."'),
  ('82bc5032-1d50-5872-a8a6-f056f8136784', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 18, 18, 'He said, "Bring them here to me."'),
  ('c1426374-0f69-5679-a4da-5c9974b88e1d', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 19, 19, 'He commanded the multitudes to sit down on the grass; and he took the five loaves and the two fish, and looking up to heaven, he blessed, broke and gave the loaves to the disciples, and the disciples gave to the multitudes.'),
  ('511c3699-830d-5c56-add6-3275e8fe6f0a', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 20, 20, 'They all ate, and were filled. They took up twelve baskets full of that which remained left over from the broken pieces.'),
  ('becd394f-d7fe-515d-a13e-d1ab8785fe3a', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 21, 21, 'Those who ate were about five thousand men, besides women and children.'),
  ('59c96b9c-77e1-5926-a62b-ecda9a31170b', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 22, 22, 'Immediately Jesus made the disciples get into the boat, and to go ahead of him to the other side, while he sent the multitudes away.'),
  ('f07dccad-f8a9-5522-afa7-0ba841ec44f8', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 23, 23, 'After he had sent the multitudes away, he went up into the mountain by himself to pray. When evening had come, he was there alone.'),
  ('0aae2bba-2042-52d3-ace7-d1d680c51748', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 24, 24, 'But the boat was now in the middle of the sea, distressed by the waves, for the wind was contrary.'),
  ('d64f5cfe-ac1b-5679-a601-7d2d7d0bfe3a', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 25, 25, 'In the fourth watch of the night, Jesus came to them, walking on the sea.'),
  ('4a19da87-d115-55a8-ae8e-1880f86276a7', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 26, 26, 'When the disciples saw him walking on the sea, they were troubled, saying, "It''s a ghost!" and they cried out for fear.'),
  ('23f7c89f-14c2-5f19-ab4e-55646ef85b27', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 27, 27, 'But immediately Jesus spoke to them, saying "Cheer up! It is I! Don''t be afraid."'),
  ('9b326505-c6c7-5090-a0d3-8601cb6ab320', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 28, 28, 'Peter answered him and said, "Lord, if it is you, command me to come to you on the waters."'),
  ('8dc7bc75-a5eb-553a-acfb-7f63441af366', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 29, 29, 'He said, "Come!" Peter stepped down from the boat, and walked on the waters to come to Jesus.'),
  ('8364f36a-6246-56c8-a56b-31ea6b948659', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 30, 30, 'But when he saw that the wind was strong, he was afraid, and beginning to sink, he cried out, saying, "Lord, save me!"'),
  ('b5ad8bdc-d2b3-5f3a-acff-0b7a5f6c8f6e', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 31, 31, 'Immediately Jesus stretched out his hand, took hold of him, and said to him, "You of little faith, why did you doubt?"'),
  ('e4762a55-e5cd-5e7e-a745-ae7332fb13a8', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 32, 32, 'When they got up into the boat, the wind ceased.'),
  ('fc591831-715d-5321-a379-dc32aefc049b', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 33, 33, 'Those who were in the boat came and worshiped him, saying, "You are truly the Son of God!"'),
  ('0ba7e3ff-c967-5047-a3d0-6f449ed91f30', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 34, 34, 'When they had crossed over, they came to the land of Gennesaret.'),
  ('82a58de7-6028-58b1-a121-9c44d3eee0c8', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 35, 35, 'When the people of that place recognized him, they sent into all that surrounding region, and brought to him all who were sick,'),
  ('fb795ac9-4503-5477-a53c-73c175cca91c', 'afef9aa3-18fe-5854-abe8-06f84da5bb8d', NULL, 36, 36, 'and they begged him that they might just touch the fringe of his garment. As many as touched it were made whole.'),
  ('332b6342-8ed0-5fe3-a38d-e45d7688ad4a', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 1, 1, 'Then Pharisees and scribes came to Jesus from Jerusalem, saying,'),
  ('6e871193-0b06-56eb-a928-f220b8d090a3', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 2, 2, '"Why do your disciples disobey the tradition of the elders? For they don''t wash their hands when they eat bread."'),
  ('082d0d79-fc76-5b70-adac-9ad0e1b8248a', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 3, 3, 'He answered them, "Why do you also disobey the commandment of God because of your tradition?'),
  ('fd16ccd0-e08b-5725-a83a-0fb56a5bd35d', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 4, 4, 'For God commanded, ''Honor your father and your mother,'' and, ''He who speaks evil of father or mother, let him be put to death.'''),
  ('d2bf2cb2-190f-59ce-a919-925c736539d0', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 5, 5, 'But you say, ''Whoever may tell his father or his mother, "Whatever help you might otherwise have gotten from me is a gift devoted to God,"'),
  ('c05340a3-8558-52d6-a2e1-05f482dbb874', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 6, 6, 'he shall not honor his father or mother.'' You have made the commandment of God void because of your tradition.'),
  ('7a29ccc1-42e6-5474-a8f9-eed023629147', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 7, 7, 'You hypocrites! Well did Isaiah prophesy of you, saying,'),
  ('9c94dd71-504a-5871-ab9f-d1ba03eba2fa', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 8, 8, '''These people draw near to me with their mouth, and honor me with their lips; but their heart is far from me.'),
  ('7b51ed1f-a772-5dd9-ac24-2a34cc8a7a9f', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 9, 9, 'And in vain do they worship me, teaching as doctrine rules made by men.''"'),
  ('cf575e31-bf2d-5576-aab3-f673eea09daf', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 10, 10, 'He summoned the multitude, and said to them, "Hear, and understand.'),
  ('18908a5d-f705-545f-af3f-dc114fc922d6', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 11, 11, 'That which enters into the mouth doesn''t defile the man; but that which proceeds out of the mouth, this defiles the man."'),
  ('477123fb-49c7-5a79-aa7e-b0f6d1b62219', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 12, 12, 'Then the disciples came, and said to him, "Do you know that the Pharisees were offended, when they heard this saying?"'),
  ('31557482-43de-5b74-af2d-cab230f044aa', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 13, 13, 'But he answered, "Every plant which my heavenly Father didn''t plant will be uprooted.'),
  ('6d469593-3432-5b89-ae1f-a0d657c1227d', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 14, 14, 'Leave them alone. They are blind guides of the blind. If the blind guide the blind, both will fall into a pit."'),
  ('0a9df13b-3495-5f3d-a234-77c67e507092', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 15, 15, 'Peter answered him, "Explain the parable to us."'),
  ('fa9afcda-2535-599b-af9d-b5ce0c058f46', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 16, 16, 'So Jesus said, "Do you also still not understand?'),
  ('c3d19c9e-4cd0-5783-a561-421d0630144a', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 17, 17, 'Don''t you understand that whatever goes into the mouth passes into the belly, and then out of the body?'),
  ('21a7c743-0a87-5d45-abe0-fb40909e468e', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 18, 18, 'But the things which proceed out of the mouth come out of the heart, and they defile the man.'),
  ('a12277c5-3f0d-58c9-aefc-552cd3f4d040', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 19, 19, 'For out of the heart come forth evil thoughts, murders, adulteries, sexual sins, thefts, false testimony, and blasphemies.'),
  ('78c51441-d595-5607-a6a2-a680b89a0b34', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 20, 20, 'These are the things which defile the man; but to eat with unwashed hands doesn''t defile the man."'),
  ('e42abbee-e81d-50b7-afcf-725ee47309aa', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 21, 21, 'Jesus went out from there, and withdrew into the region of Tyre and Sidon.'),
  ('36587c5f-3655-55a2-a084-2e882a930b14', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 22, 22, 'Behold, a Canaanite woman came out from those borders, and cried, saying, "Have mercy on me, Lord, you son of David! My daughter is severely demonized!"'),
  ('22ca0d22-1a35-5710-a29d-a034665e05a3', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 23, 23, 'But he answered her not a word. His disciples came and begged him, saying, "Send her away; for she cries after us."'),
  ('562c9ac4-48d0-5b0e-a69c-30ffbe0cb5e4', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 24, 24, 'But he answered, "I wasn''t sent to anyone but the lost sheep of the house of Israel."'),
  ('546d77fe-3a26-5b82-a861-a033c8d45471', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 25, 25, 'But she came and worshiped him, saying, "Lord, help me."'),
  ('11fad33c-b06c-58e8-a6d3-d5dee6d49697', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 26, 26, 'But he answered, "It is not appropriate to take the children''s bread and throw it to the dogs."'),
  ('041419a2-62e6-5aef-a137-709893cb7c82', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 27, 27, 'But she said, "Yes, Lord, but even the dogs eat the crumbs which fall from their masters'' table."'),
  ('d5f8a3f8-2d6e-5fd2-a444-36685405ad96', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 28, 28, 'Then Jesus answered her, "Woman, great is your faith! Be it done to you even as you desire." And her daughter was healed from that hour.'),
  ('5fca2d7c-ab82-5608-a25c-cfb654408d4a', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 29, 29, 'Jesus departed there, and came near to the sea of Galilee; and he went up into the mountain, and sat there.'),
  ('0cbcd3a4-4095-59aa-a6e0-ffdeca90cd74', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 30, 30, 'Great multitudes came to him, having with them the lame, blind, mute, maimed, and many others, and they put them down at his feet. He healed them,'),
  ('f88c8cb7-986c-51d4-a09e-0f505a71cf5e', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 31, 31, 'so that the multitude wondered when they saw the mute speaking, injured whole, lame walking, and blind seeing--and they glorified the God of Israel.'),
  ('1bfffa66-f2c0-5dc4-a85d-bb632af100aa', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 32, 32, 'Jesus summoned his disciples and said, "I have compassion on the multitude, because they continue with me now three days and have nothing to eat. I don''t want to send them away fasting, or they might faint on the way."'),
  ('df0b2055-9af7-5a42-afc2-f85a07768997', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 33, 33, 'The disciples said to him, "Where should we get so many loaves in a deserted place as to satisfy so great a multitude?"'),
  ('d0aa228d-e160-55e9-a522-6f92d2ffd56e', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 34, 34, 'Jesus said to them, "How many loaves do you have?" They said, "Seven, and a few small fish."'),
  ('523609e5-1c4d-5a0f-aa07-1fee3de06825', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 35, 35, 'He commanded the multitude to sit down on the ground;'),
  ('baa7ca4a-dbad-5308-ab84-6399582bb6d9', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 36, 36, 'and he took the seven loaves and the fish. He gave thanks and broke them, and gave to the disciples, and the disciples to the multitudes.'),
  ('2279f349-c11a-5bd8-af21-a91aac37c82d', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 37, 37, 'They all ate, and were filled. They took up seven baskets full of the broken pieces that were left over.'),
  ('37155ec4-9f06-5c2a-ad55-a9c8e54548fa', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 38, 38, 'Those who ate were four thousand men, besides women and children.'),
  ('02f1526a-d151-525a-a4ea-e53c012832a8', 'a48eddee-fc90-50bf-ac5a-2e49845d3e5f', NULL, 39, 39, 'Then he sent away the multitudes, got into the boat, and came into the borders of Magdala.'),
  ('74d862db-5508-5d5f-a4b6-0e19fbd1bcb0', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 1, 1, 'The Pharisees and Sadducees came, and testing him, asked him to show them a sign from heaven.'),
  ('51a9fafe-bb8f-566e-ab43-0afd99192a9c', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 2, 2, 'But he answered them, "When it is evening, you say, ''It will be fair weather, for the sky is red.'''),
  ('3d8ea736-8836-57d8-a873-67d1e81c3463', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 3, 3, 'In the morning, ''It will be foul weather today, for the sky is red and threatening.'' Hypocrites! You know how to discern the appearance of the sky, but you can''t discern the signs of the times!'),
  ('1eb750dc-8e03-53f7-a5fd-398005dc98b9', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 4, 4, 'An evil and adulterous generation seeks after a sign, and there will be no sign given to it, except the sign of the prophet Jonah." He left them, and departed.'),
  ('5e204923-3d63-5ab1-a367-3f96dde79c16', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 5, 5, 'The disciples came to the other side and had forgotten to take bread.'),
  ('2fe46641-2a43-56f4-a8c1-d95e161d2f50', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 6, 6, 'Jesus said to them, "Take heed and beware of the yeast of the Pharisees and Sadducees."'),
  ('b1cc995e-9eeb-5f96-a715-6dec2075d996', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 7, 7, 'They reasoned among themselves, saying, "We brought no bread."'),
  ('5db755aa-ec7a-5dba-a13a-4a0fb5b4031c', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 8, 8, 'Jesus, perceiving it, said, "Why do you reason among yourselves, you of little faith, ''because you have brought no bread?'''),
  ('8df01326-bc6d-55e1-a40e-b301e274519a', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 9, 9, 'Don''t you yet perceive, neither remember the five loaves for the five thousand, and how many baskets you took up?'),
  ('fc958500-c837-5f6b-a171-f05272410844', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 10, 10, 'Nor the seven loaves for the four thousand, and how many baskets you took up?'),
  ('71482356-3f39-57e8-afb6-3aebdf7591ce', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 11, 11, 'How is it that you don''t perceive that I didn''t speak to you concerning bread? But beware of the yeast of the Pharisees and Sadducees."'),
  ('c00590be-f20f-50fc-afd3-01e693229c5e', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 12, 12, 'Then they understood that he didn''t tell them to beware of the yeast of bread, but of the teaching of the Pharisees and Sadducees.'),
  ('a7eb0235-b40e-5f59-a96e-c39f551d6af2', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 13, 13, 'Now when Jesus came into the parts of Caesarea Philippi, he asked his disciples, saying, "Who do men say that I, the Son of Man, am?"'),
  ('135888b3-4bbf-5f60-a8ac-16c8a3188d60', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 14, 14, 'They said, "Some say John the Baptizer, some, Elijah, and others, Jeremiah, or one of the prophets."'),
  ('5dbe8b31-e02e-5a9c-a325-c2884f10057b', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 15, 15, 'He said to them, "But who do you say that I am?"'),
  ('aa1fad92-d2c4-5789-a6d5-14302ed081ca', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 16, 16, 'Simon Peter answered, "You are the Christ, the Son of the living God."'),
  ('c2bdc0eb-9464-52e5-a017-d61f207900f5', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 17, 17, 'Jesus answered him, "Blessed are you, Simon Bar Jonah, for flesh and blood has not revealed this to you, but my Father who is in heaven.'),
  ('94aa28c1-6983-5651-aa76-4a47445e3227', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 18, 18, 'I also tell you that you are Peter, and on this rock I will build my assembly, and the gates of Hades will not prevail against it.'),
  ('e7629559-91a0-573a-a372-99af873da72c', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 19, 19, 'I will give to you the keys of the Kingdom of Heaven, and whatever you bind on earth will have been bound in heaven; and whatever you release on earth will have been released in heaven."'),
  ('263e872f-bcae-5eff-ac72-87a77d316000', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 20, 20, 'Then he commanded the disciples that they should tell no one that he was Jesus the Christ.'),
  ('6217c5ce-67fb-5b6d-a18e-3e6f7e8b2960', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 21, 21, 'From that time, Jesus began to show his disciples that he must go to Jerusalem and suffer many things from the elders, chief priests, and scribes, and be killed, and the third day be raised up.'),
  ('fbd4e1e2-1e34-51fd-a19b-f55455c542a3', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 22, 22, 'Peter took him aside, and began to rebuke him, saying, "Far be it from you, Lord! This will never be done to you."'),
  ('5d984ea0-7de9-59c7-a57c-124b16d7d7ce', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 23, 23, 'But he turned, and said to Peter, "Get behind me, Satan! You are a stumbling block to me, for you are not setting your mind on the things of God, but on the things of men."'),
  ('1767fcc8-2c39-5cc7-a369-303f0b01a831', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 24, 24, 'Then Jesus said to his disciples, "If anyone desires to come after me, let him deny himself, and take up his cross, and follow me.'),
  ('b42b3a21-ba3f-521e-af34-fc8226a84f04', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 25, 25, 'For whoever desires to save his life will lose it, and whoever will lose his life for my sake will find it.'),
  ('1604f5fb-883d-58d5-a5e2-5033fd367bdd', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 26, 26, 'For what will it profit a man, if he gains the whole world, and forfeits his life? Or what will a man give in exchange for his life?'),
  ('ba2f65fc-93b9-5480-a485-db1616d859cc', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 27, 27, 'For the Son of Man will come in the glory of his Father with his angels, and then he will render to everyone according to his deeds.'),
  ('b177c87d-b470-5635-ae85-0cb1430ba50f', 'b670ed9e-c267-589c-a849-29bb74568df6', NULL, 28, 28, 'Most certainly I tell you, there are some standing here who will in no way taste of death, until they see the Son of Man coming in his Kingdom."'),
  ('1fc57a76-8b2f-582e-a1ab-4144a48c23b9', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 1, 1, 'After six days, Jesus took with him Peter, James, and John his brother, and brought them up into a high mountain by themselves.'),
  ('e3891190-fb9d-565e-a858-e92461f0ad4a', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 2, 2, 'He was transfigured before them. His face shone like the sun, and his garments became as white as the light.'),
  ('3855eb09-313d-57c6-a5dc-f363ff8e3e78', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 3, 3, 'Behold, Moses and Elijah appeared to them talking with him.'),
  ('c5dfc936-e85f-5dbc-ad87-7fefd8c00a9f', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 4, 4, 'Peter answered, and said to Jesus, "Lord, it is good for us to be here. If you want, let''s make three tents here: one for you, one for Moses, and one for Elijah."'),
  ('c6e856a0-41dd-51a8-ae0b-49a6a9e10ac9', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 5, 5, 'While he was still speaking, behold, a bright cloud overshadowed them. Behold, a voice came out of the cloud, saying, "This is my beloved Son, in whom I am well pleased. Listen to him."'),
  ('90c5db4a-56b2-5525-a895-737af582eb11', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 6, 6, 'When the disciples heard it, they fell on their faces, and were very afraid.'),
  ('4c2f389c-2523-52f9-ac58-fb9ca17448c3', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 7, 7, 'Jesus came and touched them and said, "Get up, and don''t be afraid."'),
  ('9d29bdc2-ca8f-5227-ac59-05dedb57279f', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 8, 8, 'Lifting up their eyes, they saw no one, except Jesus alone.'),
  ('2729ebcc-de58-5650-a6c2-50c8868efed1', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 9, 9, 'As they were coming down from the mountain, Jesus commanded them, saying, "Don''t tell anyone what you saw, until the Son of Man has risen from the dead."'),
  ('f32c46ea-9875-5087-a5fb-15fbc3c513a4', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 10, 10, 'His disciples asked him, saying, "Then why do the scribes say that Elijah must come first?"'),
  ('48362149-69a1-5ea5-aa6e-140eb0de0583', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 11, 11, 'Jesus answered them, "Elijah indeed comes first, and will restore all things,'),
  ('a8e4b966-df1e-5b67-acfa-018db10d90a2', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 12, 12, 'but I tell you that Elijah has come already, and they didn''t recognize him, but did to him whatever they wanted to. Even so the Son of Man will also suffer by them."'),
  ('e0f89b05-1233-5198-a11a-dd8bbe7e6ced', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 13, 13, 'Then the disciples understood that he spoke to them of John the Baptizer.'),
  ('a2813f38-69cd-5cde-aa3c-0f482f27aca1', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 14, 14, 'When they came to the multitude, a man came to him, kneeling down to him, saying,'),
  ('45806d13-9b0c-50cb-aad9-cd91a0936aa7', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 15, 15, '"Lord, have mercy on my son, for he is epileptic, and suffers grievously; for he often falls into the fire, and often into the water.'),
  ('632e1345-01e5-5b15-a7ea-4e860aa11374', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 16, 16, 'So I brought him to your disciples, and they could not cure him."'),
  ('7a8f758d-a187-5bb6-a8a1-6702ada7cb32', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 17, 17, 'Jesus answered, "Faithless and perverse generation! How long will I be with you? How long will I bear with you? Bring him here to me."'),
  ('9281f1d7-3a58-5170-a5d9-05984c590b12', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 18, 18, 'Jesus rebuked him, the demon went out of him, and the boy was cured from that hour.'),
  ('3e5ab6c2-7950-5029-aa34-7dc22dd06291', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 19, 19, 'Then the disciples came to Jesus privately, and said, "Why weren''t we able to cast it out?"'),
  ('76e72947-8221-5376-a61a-c7ec85b8c3e2', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 20, 20, 'He said to them, "Because of your unbelief. For most certainly I tell you, if you have faith as a grain of mustard seed, you will tell this mountain, ''Move from here to there,'' and it will move; and nothing will be impossible for you.'),
  ('6db8342f-b052-5c5e-a0ae-3dfd45c1a6c9', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 21, 21, 'But this kind doesn''t go out except by prayer and fasting."'),
  ('edc4cb99-4607-52f0-a781-1bdad8d64cc6', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 22, 22, 'While they were staying in Galilee, Jesus said to them, "The Son of Man is about to be delivered up into the hands of men,'),
  ('603df838-4ff5-5996-ac20-984c16ac2778', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 23, 23, 'and they will kill him, and the third day he will be raised up." They were exceedingly sorry.'),
  ('6a044f41-fb93-547c-ae94-15c2f4b77a98', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 24, 24, 'When they had come to Capernaum, those who collected the didrachma coins came to Peter, and said, "Doesn''t your teacher pay the didrachma?"'),
  ('f42a69c3-c7e8-57bc-a2f6-1c6c7b479687', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 25, 25, 'He said, "Yes." When he came into the house, Jesus anticipated him, saying, "What do you think, Simon? From whom do the kings of the earth receive toll or tribute? From their children, or from strangers?"'),
  ('54c25966-ebf9-55d2-a2e2-22b6eb38f1ce', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 26, 26, 'Peter said to him, "From strangers." Jesus said to him, "Therefore the children are exempt.'),
  ('f2084951-be5e-5aac-a202-f42810f41c0f', '1a502db8-e380-56b9-ab0f-61af840a0b53', NULL, 27, 27, 'But, lest we cause them to stumble, go to the sea, cast a hook, and take up the first fish that comes up. When you have opened its mouth, you will find a stater coin. Take that, and give it to them for me and you."'),
  ('9ea5e07d-b8e3-541f-a432-f040917c97c9', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 1, 1, 'In that hour the disciples came to Jesus, saying, "Who then is greatest in the Kingdom of Heaven?"'),
  ('7286f348-8962-5e3e-a066-faa6b53254df', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 2, 2, 'Jesus called a little child to himself, and set him in the midst of them,'),
  ('8f9ecf2d-5c04-574c-ac0a-a3012d330d94', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 3, 3, 'and said, "Most certainly I tell you, unless you turn, and become as little children, you will in no way enter into the Kingdom of Heaven.'),
  ('0ee41721-7a26-5588-a750-306dd04dd6c7', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 4, 4, 'Whoever therefore humbles himself as this little child, the same is the greatest in the Kingdom of Heaven.'),
  ('acadfefe-2c21-5c4c-a9da-f030eef109cc', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 5, 5, 'Whoever receives one such little child in my name receives me,'),
  ('d5de9f11-a7ee-5d7c-a25b-e39c9fce4acf', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 6, 6, 'but whoever causes one of these little ones who believe in me to stumble, it would be better for him that a huge millstone should be hung around his neck, and that he should be sunk in the depths of the sea.'),
  ('be282010-1a5e-578c-a17d-acbfbb0223e2', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 7, 7, '"Woe to the world because of occasions of stumbling! For it must be that the occasions come, but woe to that person through whom the occasion comes!'),
  ('b73aad64-ddaa-5e66-a3e4-d7d053561fad', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 8, 8, 'If your hand or your foot causes you to stumble, cut it off, and cast it from you. It is better for you to enter into life maimed or crippled, rather than having two hands or two feet to be cast into the eternal fire.'),
  ('516bfdc1-aed0-500e-a430-e6fc03eb1641', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 9, 9, 'If your eye causes you to stumble, pluck it out, and cast it from you. It is better for you to enter into life with one eye, rather than having two eyes to be cast into the Gehenna of fire.'),
  ('4911230c-ec41-5b8f-a290-0490afa0fabf', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 10, 10, 'See that you don''t despise one of these little ones, for I tell you that in heaven their angels always see the face of my Father who is in heaven.'),
  ('a28ac3bb-14c7-53e0-a4fd-9b0c4d09a88b', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 11, 11, 'For the Son of Man came to save that which was lost.'),
  ('e8977e2e-c63c-52c1-ad2f-93cddda01118', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 12, 12, '"What do you think? If a man has one hundred sheep, and one of them goes astray, doesn''t he leave the ninety-nine, go to the mountains, and seek that which has gone astray?'),
  ('1b490060-baaa-55de-abae-80d13f9514f9', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 13, 13, 'If he finds it, most certainly I tell you, he rejoices over it more than over the ninety-nine which have not gone astray.'),
  ('072de5ef-1100-5bce-a725-5f221f3f9d62', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 14, 14, 'Even so it is not the will of your Father who is in heaven that one of these little ones should perish.'),
  ('66d39aa0-c181-5b97-aa08-cdcba9967b62', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 15, 15, '"If your brother sins against you, go, show him his fault between you and him alone. If he listens to you, you have gained back your brother.'),
  ('ce3a34cf-2ea1-5a89-a559-0466ad95dd7f', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 16, 16, 'But if he doesn''t listen, take one or two more with you, that at the mouth of two or three witnesses every word may be established.'),
  ('b14798e9-b853-5358-ad88-ec8e99f29d48', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 17, 17, 'If he refuses to listen to them, tell it to the assembly. If he refuses to hear the assembly also, let him be to you as a Gentile or a tax collector.'),
  ('31b24f2e-ad2a-5503-a6e4-79a05e238a5b', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 18, 18, 'Most certainly I tell you, whatever things you bind on earth will have been bound in heaven, and whatever things you release on earth will have been released in heaven.'),
  ('01f763cc-c992-57fb-a5cd-7a82e3c55de5', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 19, 19, 'Again, assuredly I tell you, that if two of you will agree on earth concerning anything that they will ask, it will be done for them by my Father who is in heaven.'),
  ('29f4a7e1-6dc3-5871-a8fc-f92bcbfb38f9', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 20, 20, 'For where two or three are gathered together in my name, there I am in the midst of them."'),
  ('a385f282-2ca0-5e64-a1ba-13d617d11670', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 21, 21, 'Then Peter came and said to him, "Lord, how often shall my brother sin against me, and I forgive him? Until seven times?"'),
  ('a607d0c4-9b7d-5b4e-acbe-b7f07deb41ae', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 22, 22, 'Jesus said to him, "I don''t tell you until seven times, but, until seventy times seven.'),
  ('56c0e8a6-01a6-5b52-aa95-e2f6b5eee5d2', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 23, 23, 'Therefore the Kingdom of Heaven is like a certain king, who wanted to reconcile accounts with his servants.'),
  ('72a3925b-bb35-52e6-a01c-2b9c36194d13', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 24, 24, 'When he had begun to reconcile, one was brought to him who owed him ten thousand talents.'),
  ('b396edc4-0124-58c8-a3a7-4ec70ab71a67', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 25, 25, 'But because he couldn''t pay, his lord commanded him to be sold, with his wife, his children, and all that he had, and payment to be made.'),
  ('4acb0cee-35ec-52d4-ad11-5bc21b59579e', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 26, 26, 'The servant therefore fell down and kneeled before him, saying, ''Lord, have patience with me, and I will repay you all!'''),
  ('4d437ac8-bf76-5ef2-a3c3-0b3c5bf6e5df', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 27, 27, 'The lord of that servant, being moved with compassion, released him, and forgave him the debt.'),
  ('258b598b-4be6-5312-a007-44f1e92534c6', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 28, 28, '"But that servant went out, and found one of his fellow servants, who owed him one hundred denarii, and he grabbed him, and took him by the throat, saying, ''Pay me what you owe!'''),
  ('ea0c8cd7-7ffd-5222-a604-fed04ec82b47', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 29, 29, '"So his fellow servant fell down at his feet and begged him, saying, ''Have patience with me, and I will repay you!'''),
  ('4bfd0f56-f940-55e9-aee7-5d3cfb468f4a', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 30, 30, 'He would not, but went and cast him into prison, until he should pay back that which was due.'),
  ('fdf885bf-1f0e-5107-ab6c-c75c2e993b0b', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 31, 31, 'So when his fellow servants saw what was done, they were exceedingly sorry, and came and told to their lord all that was done.'),
  ('5809afc3-7344-541d-ae63-520a828935bd', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 32, 32, 'Then his lord called him in, and said to him, ''You wicked servant! I forgave you all that debt, because you begged me.'),
  ('446a1cf4-6b9c-5d4b-a6a3-31c4c9697258', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 33, 33, 'Shouldn''t you also have had mercy on your fellow servant, even as I had mercy on you?'''),
  ('432b9498-8101-5d26-ab7d-9329c0223f4b', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 34, 34, 'His lord was angry, and delivered him to the tormentors, until he should pay all that was due to him.'),
  ('b1924200-57d4-525a-a576-4c339f67affe', 'c9eb8855-2f05-5d9c-a43d-298bbbca3b39', NULL, 35, 35, 'So my heavenly Father will also do to you, if you don''t each forgive your brother from your hearts for his misdeeds."'),
  ('69344320-60aa-5221-a684-2afe2d110dd2', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 1, 1, 'It happened when Jesus had finished these words, he departed from Galilee, and came into the borders of Judea beyond the Jordan.'),
  ('296edf59-9f9d-54fb-a43c-f938ee6fbfe2', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 2, 2, 'Great multitudes followed him, and he healed them there.'),
  ('c39909ef-751c-57ec-a1a4-f589dc9bf090', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 3, 3, 'Pharisees came to him, testing him, and saying, "Is it lawful for a man to divorce his wife for any reason?"'),
  ('83240cf8-aea0-5e5d-a0dd-0941a1a618a4', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 4, 4, 'He answered, "Haven''t you read that he who made them from the beginning made them male and female,'),
  ('0e4bb38c-874a-5fb1-a44e-9cce6eb54ff8', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 5, 5, 'and said, ''For this cause a man shall leave his father and mother, and shall join to his wife; and the two shall become one flesh?'''),
  ('c7973b1f-2d83-549f-a0c5-18b687aef402', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 6, 6, 'So that they are no more two, but one flesh. What therefore God has joined together, don''t let man tear apart."'),
  ('cffa4955-67be-5890-ab9b-bc7a29f38e66', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 7, 7, 'They asked him, "Why then did Moses command us to give her a bill of divorce, and divorce her?"'),
  ('9b7e5f78-f9ee-50f7-a61d-803b66b39d33', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 8, 8, 'He said to them, "Moses, because of the hardness of your hearts, allowed you to divorce your wives, but from the beginning it has not been so.'),
  ('4f3075a0-18a1-5ac6-a8ab-a047f46101dc', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 9, 9, 'I tell you that whoever divorces his wife, except for sexual immorality, and marries another, commits adultery; and he who marries her when she is divorced commits adultery."'),
  ('36fd2c5d-0ed6-5d27-afb7-80afb4f97bf6', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 10, 10, 'His disciples said to him, "If this is the case of the man with his wife, it is not expedient to marry."'),
  ('913fdee4-96b3-5ec3-a7a6-d9b405c2ed40', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 11, 11, 'But he said to them, "Not all men can receive this saying, but those to whom it is given.'),
  ('ed3a2205-c254-516d-a09b-5f3fc7a77636', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 12, 12, 'For there are eunuchs who were born that way from their mother''s womb, and there are eunuchs who were made eunuchs by men; and there are eunuchs who made themselves eunuchs for the Kingdom of Heaven''s sake. He who is able to receive it, let him receive it."'),
  ('c72159e7-86ef-5c17-a269-35a9d9424102', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 13, 13, 'Then little children were brought to him, that he should lay his hands on them and pray; and the disciples rebuked them.'),
  ('b8fef3da-228d-5751-a785-a1d1ac12462f', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 14, 14, 'But Jesus said, "Allow the little children, and don''t forbid them to come to me; for the Kingdom of Heaven belongs to ones like these."'),
  ('340f7c85-be54-5f30-a31b-500ab043d4f3', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 15, 15, 'He laid his hands on them, and departed from there.'),
  ('c234101e-6426-5f65-abbe-1ea2f1499582', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 16, 16, 'Behold, one came to him and said, "Good teacher, what good thing shall I do, that I may have eternal life?"'),
  ('8aa52fff-39ca-5e32-a1e3-69fa35ea7775', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 17, 17, 'He said to him, "Why do you call me good? No one is good but one, that is, God. But if you want to enter into life, keep the commandments."'),
  ('16a145fb-3af4-51a1-a118-0265c714757d', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 18, 18, 'He said to him, "Which ones?" Jesus said, "''You shall not murder.'' ''You shall not commit adultery.'' ''You shall not steal.'' ''You shall not offer false testimony.'''),
  ('11c3ab2f-ae31-5cdf-abae-6583a9edf57e', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 19, 19, '''Honor your father and mother.'' And, ''You shall love your neighbor as yourself.''"'),
  ('90862f73-3f56-573d-af6f-d6fa9fed3aec', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 20, 20, 'The young man said to him, "All these things I have observed from my youth. What do I still lack?"'),
  ('81807e22-b95b-5864-abdc-e3986549cdbd', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 21, 21, 'Jesus said to him, "If you want to be perfect, go, sell what you have, and give to the poor, and you will have treasure in heaven; and come, follow me."'),
  ('c674ee44-8f16-5d8a-ac52-b49978858fed', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 22, 22, 'But when the young man heard the saying, he went away sad, for he was one who had great possessions.'),
  ('87caf9f1-fe20-5b8a-a92e-a95d0c4150d1', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 23, 23, 'Jesus said to his disciples, "Most certainly I say to you, a rich man will enter into the Kingdom of Heaven with difficulty.'),
  ('861e9de8-3df1-5633-a4a3-b10fb8a949ad', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 24, 24, 'Again I tell you, it is easier for a camel to go through a needle''s eye, than for a rich man to enter into the Kingdom of God."'),
  ('aade51e7-b3ac-54e6-ac1d-7b9651ed2b7f', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 25, 25, 'When the disciples heard it, they were exceedingly astonished, saying, "Who then can be saved?"'),
  ('cbac2293-73ca-5bf9-a21d-ed507a923278', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 26, 26, 'Looking at them, Jesus said, "With men this is impossible, but with God all things are possible."'),
  ('8c4d0364-4e60-5548-a0c8-7b061211ed21', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 27, 27, 'Then Peter answered, "Behold, we have left everything, and followed you. What then will we have?"'),
  ('04ebec05-d203-5c21-a334-77365522a38e', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 28, 28, 'Jesus said to them, "Most certainly I tell you that you who have followed me, in the regeneration when the Son of Man will sit on the throne of his glory, you also will sit on twelve thrones, judging the twelve tribes of Israel.'),
  ('e633a5b6-3e1a-55f4-a67e-9133bf26ea6e', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 29, 29, 'Everyone who has left houses, or brothers, or sisters, or father, or mother, or wife, or children, or lands, for my name''s sake, will receive one hundred times, and will inherit eternal life.'),
  ('275568c9-d96b-5957-a224-c94b7b749fa0', '54c358c3-2e5d-59cc-a1da-c148eff39b4e', NULL, 30, 30, 'But many will be last who are first; and first who are last.'),
  ('770cd929-6a5f-57f6-a936-6366d53657f4', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 1, 1, '"For the Kingdom of Heaven is like a man who was the master of a household, who went out early in the morning to hire laborers for his vineyard.'),
  ('ab70f678-99c4-5483-abf2-954e5b277c1a', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 2, 2, 'When he had agreed with the laborers for a denarius a day, he sent them into his vineyard.'),
  ('6b3b510d-32ef-5630-a8f3-eeefb4fbdff5', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 3, 3, 'He went out about the third hour, and saw others standing idle in the marketplace.'),
  ('4178a66f-a4f6-57c2-a408-fdf9f53bebc9', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 4, 4, 'To them he said, ''You also go into the vineyard, and whatever is right I will give you.'' So they went their way.'),
  ('c01b15f0-3faf-54d5-aed8-557ad4d5611e', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 5, 5, 'Again he went out about the sixth and the ninth hour, and did likewise.'),
  ('cd9f0385-886b-52c2-a9e6-689b46f6626f', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 6, 6, 'About the eleventh hour he went out, and found others standing idle. He said to them, ''Why do you stand here all day idle?'''),
  ('7d6ee103-13b2-5c45-aaa0-d1a085ba10bf', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 7, 7, '"They said to him, ''Because no one has hired us.'' "He said to them, ''You also go into the vineyard, and you will receive whatever is right.'''),
  ('96f8e636-8552-5913-a138-1abfed6b635d', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 8, 8, 'When evening had come, the lord of the vineyard said to his manager, ''Call the laborers and pay them their wages, beginning from the last to the first.'''),
  ('1ef1793c-76ad-5fa5-afff-7b69a83cdae5', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 9, 9, '"When those who were hired at about the eleventh hour came, they each received a denarius.'),
  ('aaae4f11-ee13-55db-aa24-b32b37538117', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 10, 10, 'When the first came, they supposed that they would receive more; and they likewise each received a denarius.'),
  ('9d9958f4-c7c6-5cee-ac21-b5189eb83ccd', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 11, 11, 'When they received it, they murmured against the master of the household,'),
  ('81a3a2ff-212a-5ca6-a557-32dc9b5ac329', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 12, 12, 'saying, ''These last have spent one hour, and you have made them equal to us, who have borne the burden of the day and the scorching heat!'''),
  ('fc604f4e-57e6-5e0c-a98a-7fe4458ae7ab', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 13, 13, '"But he answered one of them, ''Friend, I am doing you no wrong. Didn''t you agree with me for a denarius?'),
  ('c9525731-907e-5773-aec2-3e491097be2d', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 14, 14, 'Take that which is yours, and go your way. It is my desire to give to this last just as much as to you.'),
  ('815d0f5c-6298-5cf8-aaa1-4b06cc0c9364', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 15, 15, 'Isn''t it lawful for me to do what I want to with what I own? Or is your eye evil, because I am good?'''),
  ('55d08e5f-d9f6-5de9-a4dc-f91648ea0795', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 16, 16, 'So the last will be first, and the first last. For many are called, but few are chosen."'),
  ('0a063ba9-ccb0-5030-a880-9f8df9a33844', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 17, 17, 'As Jesus was going up to Jerusalem, he took the twelve disciples aside, and on the way he said to them,'),
  ('9a764954-82bf-51ab-a2a2-eadde16d7582', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 18, 18, '"Behold, we are going up to Jerusalem, and the Son of Man will be delivered to the chief priests and scribes, and they will condemn him to death,'),
  ('e15f483e-f53d-5028-acb5-fd9076c4fee7', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 19, 19, 'and will hand him over to the Gentiles to mock, to scourge, and to crucify; and the third day he will be raised up."'),
  ('d0afc16d-cc4e-56f2-a83f-1c204f6cb0ee', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 20, 20, 'Then the mother of the sons of Zebedee came to him with her sons, kneeling and asking a certain thing of him.'),
  ('d50c7e55-3cf0-5c30-aeb5-3a47d6ddbb96', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 21, 21, 'He said to her, "What do you want?" She said to him, "Command that these, my two sons, may sit, one on your right hand, and one on your left hand, in your Kingdom."'),
  ('8a67b13f-efcf-5350-aa32-9b5d7d26900f', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 22, 22, 'But Jesus answered, "You don''t know what you are asking. Are you able to drink the cup that I am about to drink, and be baptized with the baptism that I am baptized with?" They said to him, "We are able."'),
  ('f2ebe6d8-9ec5-5d35-a24c-52d51f75ced8', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 23, 23, 'He said to them, "You will indeed drink my cup, and be baptized with the baptism that I am baptized with, but to sit on my right hand and on my left hand is not mine to give; but it is for whom it has been prepared by my Father."'),
  ('8cd2d4c5-892f-555b-a57b-7ff3f3dd596d', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 24, 24, 'When the ten heard it, they were indignant with the two brothers.'),
  ('0780c276-db27-50b6-abaa-22e56638b3af', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 25, 25, 'But Jesus summoned them, and said, "You know that the rulers of the nations lord it over them, and their great ones exercise authority over them.'),
  ('a252cc47-8888-5666-af5d-71478db89d36', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 26, 26, 'It shall not be so among you, but whoever desires to become great among you shall be your servant.'),
  ('5491792c-c39a-5a65-ac1b-80b6118045a7', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 27, 27, 'Whoever desires to be first among you shall be your bondservant,'),
  ('bd90e762-f720-5cc9-a4d2-e4222b832c9d', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 28, 28, 'even as the Son of Man came not to be served, but to serve, and to give his life as a ransom for many."'),
  ('58ac3c08-405d-5099-a650-484f92dc3e8b', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 29, 29, 'As they went out from Jericho, a great multitude followed him.'),
  ('d0e756b1-d34d-553a-a9b4-b1eac42ce329', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 30, 30, 'Behold, two blind men sitting by the road, when they heard that Jesus was passing by, cried out, "Lord, have mercy on us, you son of David!"'),
  ('a2051926-be28-5237-a1fc-54976a1a7f94', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 31, 31, 'The multitude rebuked them, telling them that they should be quiet, but they cried out even more, "Lord, have mercy on us, you son of David!"'),
  ('1fdb63ec-7666-55b5-ade2-4bad0555c5b1', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 32, 32, 'Jesus stood still, and called them, and asked, "What do you want me to do for you?"'),
  ('f34044d7-5604-5a59-a08c-30cc257c805a', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 33, 33, 'They told him, "Lord, that our eyes may be opened."'),
  ('1e88931a-205b-5167-ac19-5df6e18b945c', '6bee8326-66ad-5fd5-afe0-03d39011fbae', NULL, 34, 34, 'Jesus, being moved with compassion, touched their eyes; and immediately their eyes received their sight, and they followed him.'),
  ('c043d5cb-006f-5abd-a994-c8e02bf295a0', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 1, 1, 'When they drew near to Jerusalem, and came to Bethsphage, to the Mount of Olives, then Jesus sent two disciples,'),
  ('ec6e4397-2c68-58bc-a510-e4abb32ec9f2', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 2, 2, 'saying to them, "Go into the village that is opposite you, and immediately you will find a donkey tied, and a colt with her. Untie them, and bring them to me.'),
  ('a267a0c8-81e7-5824-a2de-d894fc502ac3', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 3, 3, 'If anyone says anything to you, you shall say, ''The Lord needs them,'' and immediately he will send them."'),
  ('2f4fd644-7c37-5f26-a4f5-d3fceae4a3f0', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 4, 4, 'All this was done, that it might be fulfilled which was spoken through the prophet, saying,'),
  ('0468af29-879d-5e95-a1c7-dc0eade2f6a6', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 5, 5, '"Tell the daughter of Zion, behold, your King comes to you, humble, and riding on a donkey, on a colt, the foal of a donkey."'),
  ('efaf7d31-b2ea-53ad-a40b-5df3cad9b061', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 6, 6, 'The disciples went, and did just as Jesus commanded them,'),
  ('978a1b41-2549-54d8-ae36-7753e07980a2', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 7, 7, 'and brought the donkey and the colt, and laid their clothes on them; and he sat on them.'),
  ('30806889-2b39-5638-ad7e-00223203a180', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 8, 8, 'A very great multitude spread their clothes on the road. Others cut branches from the trees, and spread them on the road.'),
  ('2ddaf643-c382-5a29-a461-d797eeef3c85', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 9, 9, 'The multitudes who went before him, and who followed kept shouting, "Hosanna to the son of David! Blessed is he who comes in the name of the Lord! Hosanna in the highest!"'),
  ('1038e956-8bc1-5fda-a2e5-4affcce541e8', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 10, 10, 'When he had come into Jerusalem, all the city was stirred up, saying, "Who is this?"'),
  ('a8fe56fd-8a4f-51b3-a64f-fdfe0622735a', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 11, 11, 'The multitudes said, "This is the prophet, Jesus, from Nazareth of Galilee."'),
  ('65ea15b8-a59e-5074-a11e-6df65a04185e', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 12, 12, 'Jesus entered into the temple of God, and drove out all of those who sold and bought in the temple, and overthrew the money changers'' tables and the seats of those who sold the doves.'),
  ('5a706eb2-1f54-5d5d-a49f-2d4a026d249c', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 13, 13, 'He said to them, "It is written, ''My house shall be called a house of prayer,'' but you have made it a den of robbers!"'),
  ('c7b66175-cf8d-5359-ac95-4db428d5f48c', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 14, 14, 'The blind and the lame came to him in the temple, and he healed them.'),
  ('f52939e9-a30e-5428-ad1e-4195ee6659c2', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 15, 15, 'But when the chief priests and the scribes saw the wonderful things that he did, and the children who were crying in the temple and saying, "Hosanna to the son of David!" they were indignant,'),
  ('a38597bc-0dc5-58d4-ad89-c10476768dec', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 16, 16, 'and said to him, "Do you hear what these are saying?" Jesus said to them, "Yes. Did you never read, ''Out of the mouth of babes and nursing babies you have perfected praise?''"'),
  ('3470191d-37e9-5f18-a3a8-96bba34d19e9', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 17, 17, 'He left them, and went out of the city to Bethany, and lodged there.'),
  ('58aa0f9b-0ec5-5492-a8b7-faaf4a3e5f55', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 18, 18, 'Now in the morning, as he returned to the city, he was hungry.'),
  ('405c8499-e000-53e2-a9f4-55fbee9056e0', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 19, 19, 'Seeing a fig tree by the road, he came to it, and found nothing on it but leaves. He said to it, "Let there be no fruit from you forever!" Immediately the fig tree withered away.'),
  ('74408459-85d9-52d8-af82-1d57c7db0ae2', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 20, 20, 'When the disciples saw it, they marveled, saying, "How did the fig tree immediately wither away?"'),
  ('d4d6fd3e-402d-5bd1-a50a-26e07cbd02c4', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 21, 21, 'Jesus answered them, "Most certainly I tell you, if you have faith, and don''t doubt, you will not only do what was done to the fig tree, but even if you told this mountain, ''Be taken up and cast into the sea,'' it would be done.'),
  ('d99b348f-1d22-55df-afd9-a9a6dc42bc59', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 22, 22, 'All things, whatever you ask in prayer, believing, you will receive."'),
  ('cbd225dc-b1d6-552f-aa79-3a21cf33be06', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 23, 23, 'When he had come into the temple, the chief priests and the elders of the people came to him as he was teaching, and said, "By what authority do you do these things? Who gave you this authority?"'),
  ('d22593fc-348a-53c2-ab61-7bb10b6243cd', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 24, 24, 'Jesus answered them, "I also will ask you one question, which if you tell me, I likewise will tell you by what authority I do these things.'),
  ('3e086437-262f-52b2-a604-a36077704e04', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 25, 25, 'The baptism of John, where was it from? From heaven or from men?" They reasoned with themselves, saying, "If we say, ''From heaven,'' he will ask us, ''Why then did you not believe him?'''),
  ('2560ba10-3126-5a05-afd3-0d0fa150f96c', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 26, 26, 'But if we say, ''From men,'' we fear the multitude, for all hold John as a prophet."'),
  ('a9f4a9b7-622d-55dc-a485-7f4d40211615', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 27, 27, 'They answered Jesus, and said, "We don''t know." He also said to them, "Neither will I tell you by what authority I do these things.'),
  ('71617f31-adb8-5240-aa6c-26a305d899d7', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 28, 28, 'But what do you think? A man had two sons, and he came to the first, and said, ''Son, go work today in my vineyard.'''),
  ('a870b4e9-a72b-585c-a5dc-fab7673382a8', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 29, 29, 'He answered, ''I will not,'' but afterward he changed his mind, and went.'),
  ('af878483-bb75-516a-a1ab-de4c8dc75292', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 30, 30, 'He came to the second, and said the same thing. He answered, ''I go, sir,'' but he didn''t go.'),
  ('8dcade6e-bc57-5ff1-ae77-0e353c521018', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 31, 31, 'Which of the two did the will of his father?" They said to him, "The first." Jesus said to them, "Most certainly I tell you that the tax collectors and the prostitutes are entering into the Kingdom of God before you.'),
  ('28d6c7ed-83a2-5573-a474-e1c063dfa582', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 32, 32, 'For John came to you in the way of righteousness, and you didn''t believe him, but the tax collectors and the prostitutes believed him. When you saw it, you didn''t even repent afterward, that you might believe him.'),
  ('d5fb4ddd-12ca-5b4f-aa66-46b9a0c7e982', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 33, 33, '"Hear another parable. There was a man who was a master of a household, who planted a vineyard, set a hedge about it, dug a winepress in it, built a tower, leased it out to farmers, and went into another country.'),
  ('47518dee-a4ad-56be-ad26-9425e56e3079', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 34, 34, 'When the season for the fruit drew near, he sent his servants to the farmers, to receive his fruit.')
